-- Vinabike ERP version-controlled bootstrap/reference schema.
--
-- TRUST BOUNDARY:
-- This file is NOT proof of the live production schema and MUST NOT be treated
-- as a guaranteed 100% representation of the deployed backend. Historical
-- standalone production changes were not always mirrored here, so this file
-- may still contain omissions or stale definitions until an explicit
-- production-to-bootstrap reconciliation proves parity.
--
-- Production catalogs are authoritative for what is currently deployed. This
-- file remains the repository target for deterministic clean/local bootstrap:
-- every new schema change must have a reviewed idempotent forward migration and
-- the same final objects/logic must be added or updated here.
--
-- Never run this complete file, or copied fragments from it, against production
-- or in the Supabase SQL Editor. Deploy only the smallest reviewed standalone
-- migration through the guarded workflow in docs/development/SUPABASE_WORKFLOW.md.
--
-- UUID columns default to gen_random_uuid(); ensure the extension is enabled first.
-- Match Supabase's hosted public-schema defaults before provisioning objects.
-- Object-specific REVOKE statements later in this snapshot remain authoritative.
grant usage on schema public to anon, authenticated, service_role;
alter default privileges in schema public
  grant all on tables to anon, authenticated, service_role;
alter default privileges in schema public
  grant all on sequences to anon, authenticated, service_role;
alter default privileges in schema public
  grant execute on functions to anon, authenticated, service_role;

-- CRITICAL: Drop ALL triggers on mechanic_job_items and mechanic_job_tasks
-- that reference old task functions (cascade will remove dependencies)
do $$
declare
  r record;
begin
  -- Drop ALL triggers on mechanic_job_tasks first (prevent any misattached triggers)
  for r in (
    select trigger_name
    from information_schema.triggers
    where event_object_table = 'mechanic_job_tasks'
  ) loop
    execute format('drop trigger if exists %I on mechanic_job_tasks cascade', r.trigger_name);
    raise notice 'Dropped task trigger: %', r.trigger_name;
  end loop;

  -- Drop ALL triggers on mechanic_job_items that might cause conflicts
  for r in (
    select trigger_name
    from information_schema.triggers
    where event_object_table = 'mechanic_job_items'
      and trigger_name like '%task%'
  ) loop
    execute format('drop trigger if exists %I on mechanic_job_items cascade', r.trigger_name);
    raise notice 'Dropped trigger: %', r.trigger_name;
  end loop;

  -- Drop ALL triggers on mechanic_jobs related to tasks
  for r in (
    select trigger_name
    from information_schema.triggers
    where event_object_table = 'mechanic_jobs'
      and trigger_name like '%task%'
  ) loop
    execute format('drop trigger if exists %I on mechanic_jobs cascade', r.trigger_name);
    raise notice 'Dropped trigger: %', r.trigger_name;
  end loop;
end $$;

-- Data fix: ensure every mechanic job has a unique job_number and align the sequence
do $$
declare
  v_job_id uuid;
  v_max_number integer;
begin
  -- In a fresh/local DB the table (and sequence/function) may not exist yet.
  -- This data-fix block is safe to skip when bootstrapping from scratch.
  if not exists (
    select 1
    from information_schema.tables
    where table_schema = 'public'
      and table_name = 'mechanic_jobs'
  ) then
    return;
  end if;

  if not exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname = 'generate_mechanic_job_number'
  ) then
    return;
  end if;

  -- Backfill missing/blank job numbers
  for v_job_id in
    select id
    from mechanic_jobs
    where job_number is null or btrim(job_number) = ''
  loop
    update mechanic_jobs
    set job_number = public.generate_mechanic_job_number()
    where id = v_job_id;
  end loop;

  -- Align the sequence with the highest PG-##### that currently exists
  select max((substring(job_number from '[0-9]+$'))::integer)
  into v_max_number
  from mechanic_jobs
  where job_number ~ '^PG-[0-9]+$';

  if v_max_number is null then
    v_max_number := 0;
  end if;

  if v_max_number < 1 then
    begin
      perform setval('public.mechanic_job_number_seq', 1, false);
    exception when undefined_table or undefined_object then null;
    end;
  else
    begin
      perform setval('public.mechanic_job_number_seq', v_max_number, true);
    exception when undefined_table or undefined_object then null;
    end;
  end if;
end $$;

