  ('mail', 'System reserved'),
  ('ftp', 'System reserved'),
  ('store', 'System reserved'),
  ('shop', 'System reserved'),
  ('dashboard', 'System reserved'),
  ('login', 'System reserved'),
  ('signup', 'System reserved'),
  ('auth', 'System reserved'),
  ('cdn', 'System reserved'),
  ('static', 'System reserved'),
