-- Step 1: Create the new product_categories table if it doesn't exist
create table if not exists product_categories (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade not null,
  name text not null,
  full_path text not null, -- e.g., "Accesorios / Asientos / Tija"
  parent_id uuid references product_categories(id) on delete cascade,
  level integer not null default 0, -- 0 = root, 1 = child, 2 = grandchild, etc.
  description text,
  image_url text,
  is_active boolean not null default true,
  show_on_website boolean not null default false, -- Whether to show in public store navigation
  sort_order integer not null default 0,
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  unique(tenant_id, full_path) -- Each tenant can have same category paths
);

-- Add show_on_website column if not exists (for existing tables)
alter table product_categories add column if not exists show_on_website boolean not null default false;

-- Step 2: Create indexes for product_categories
create index if not exists idx_product_categories_parent_id on product_categories(parent_id);
create index if not exists idx_product_categories_full_path on product_categories(full_path);
create index if not exists idx_product_categories_level on product_categories(level);
create index if not exists idx_product_categories_is_active on product_categories(is_active);
create index if not exists idx_product_categories_name on product_categories using gin (to_tsvector('spanish', coalesce(name, '')));

-- Trigger: keep products.category_name synced when product_categories.name changes
drop trigger if exists trg_sync_products_on_category_change on product_categories;
create trigger trg_sync_products_on_category_change
  after update of name
  on product_categories
  for each row
  execute function sync_products_on_category_change();

-- Canonical Website Builder command: replace the published category set in
-- one tenant-scoped transaction, preserving unchanged timestamps and an exact
-- actor/diff trail.
create or replace function public.replace_website_category_visibility(
  p_tenant_id uuid,
  p_visible_category_ids uuid[] default '{}'::uuid[]
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
declare
  v_caller_id uuid := auth.uid();
  v_caller_tenant_id uuid := public.user_tenant_id();
  v_requested_ids uuid[];
  v_before_ids uuid[];
  v_added_ids uuid[];
  v_removed_ids uuid[];
  v_invalid_ids uuid[];
  v_changed_at timestamptz := clock_timestamp();
begin
  if v_caller_id is null
     or p_tenant_id is null
     or v_caller_tenant_id is distinct from p_tenant_id
     or not public.can_edit_tenant_settings(p_tenant_id) then
    raise exception 'website_category_publication_tenant_forbidden'
      using errcode = '42501';
  end if;

  if array_position(p_visible_category_ids, null) is not null then
    raise exception 'website_category_publication_invalid_category'
      using errcode = '22023';
  end if;

  select coalesce(
    array_agg(requested.category_id order by requested.category_id),
    '{}'::uuid[]
  )
  into v_requested_ids
  from (
    select distinct category_id
    from unnest(
      coalesce(p_visible_category_ids, '{}'::uuid[])
    ) as requested_id(category_id)
  ) requested;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'website_category_publication:' || p_tenant_id::text,
      0
    )
  );

  select coalesce(
    array_agg(requested.category_id order by requested.category_id),
    '{}'::uuid[]
  )
  into v_invalid_ids
  from unnest(v_requested_ids) requested(category_id)
  left join public.product_categories category
    on category.id = requested.category_id
   and category.tenant_id = p_tenant_id
   and category.is_active is true
  where category.id is null;

  if cardinality(v_invalid_ids) > 0 then
    raise exception 'website_category_publication_invalid_category'
      using errcode = '22023';
  end if;

  select coalesce(
    array_agg(category.id order by category.id),
    '{}'::uuid[]
  )
  into v_before_ids
  from public.product_categories category
  where category.tenant_id = p_tenant_id
    and category.show_on_website is true;

  select coalesce(
    array_agg(category_id order by category_id),
    '{}'::uuid[]
  )
  into v_added_ids
  from (
    select unnest(v_requested_ids) as category_id
    except
    select unnest(v_before_ids) as category_id
  ) added;

  select coalesce(
    array_agg(category_id order by category_id),
    '{}'::uuid[]
  )
  into v_removed_ids
  from (
    select unnest(v_before_ids) as category_id
    except
    select unnest(v_requested_ids) as category_id
  ) removed;

  update public.product_categories category
  set show_on_website = category.id = any(v_requested_ids),
      updated_at = v_changed_at
  where category.tenant_id = p_tenant_id
    and category.show_on_website is distinct from (
      category.id = any(v_requested_ids)
    );

  if cardinality(v_added_ids) > 0 or cardinality(v_removed_ids) > 0 then
    insert into public.user_activity_log (
      tenant_id,
      user_id,
      action,
      details,
      performed_by,
      created_at
    )
    values (
      p_tenant_id,
      v_caller_id,
      'website_category_publication_replaced',
      jsonb_build_object(
        'before_ids', to_jsonb(v_before_ids),
        'after_ids', to_jsonb(v_requested_ids),
        'added_ids', to_jsonb(v_added_ids),
        'removed_ids', to_jsonb(v_removed_ids)
      ),
      v_caller_id,
      v_changed_at
    );
  end if;

  return jsonb_build_object(
    'visible_ids', to_jsonb(v_requested_ids),
    'added_ids', to_jsonb(v_added_ids),
    'removed_ids', to_jsonb(v_removed_ids),
    'changed_at', v_changed_at
  );
end;
$$;

revoke all on function public.replace_website_category_visibility(uuid, uuid[])
  from public, anon;
grant execute on function public.replace_website_category_visibility(uuid, uuid[])
  to authenticated;

-- Step 3: Migrate existing data from 'categories' to 'product_categories' (if old table exists)
do $$
declare
  old_table_exists boolean;
  has_sort_order boolean;
  has_description boolean;
  has_image_url boolean;
  migration_sql text;
begin
  -- Check if old 'categories' table exists
  select exists (
    select from pg_tables
    where schemaname = 'public'
    and tablename = 'categories'
  ) into old_table_exists;

  if old_table_exists then
    raise notice 'Found old categories table, migrating data...';

    -- Check which columns exist in old table
    select exists (
      select 1 from information_schema.columns
      where table_schema = 'public'
      and table_name = 'categories'
      and column_name = 'sort_order'
    ) into has_sort_order;

    select exists (
      select 1 from information_schema.columns
      where table_schema = 'public'
      and table_name = 'categories'
      and column_name = 'description'
    ) into has_description;

    select exists (
      select 1 from information_schema.columns
      where table_schema = 'public'
      and table_name = 'categories'
      and column_name = 'image_url'
    ) into has_image_url;

    -- Build dynamic SQL based on available columns
    migration_sql := 'insert into product_categories (id, name, full_path, parent_id, level, description, image_url, is_active, sort_order, created_at, updated_at) ' ||
                     'select id, name, name as full_path, null as parent_id, 0 as level, ';

    if has_description then
      migration_sql := migration_sql || 'description, ';
    else
      migration_sql := migration_sql || 'null as description, ';
    end if;

    if has_image_url then
      migration_sql := migration_sql || 'image_url, ';
    else
      migration_sql := migration_sql || 'null as image_url, ';
    end if;

    migration_sql := migration_sql || 'coalesce(is_active, true) as is_active, ';

    if has_sort_order then
      migration_sql := migration_sql || 'coalesce(sort_order, 0) as sort_order, ';
    else
      migration_sql := migration_sql || '0 as sort_order, ';
    end if;

    migration_sql := migration_sql || 'created_at, updated_at from categories on conflict (id) do nothing';

    -- Execute migration
    execute migration_sql;

    raise notice 'Migrated % categories from old table', (select count(*) from categories);
  else
    raise notice 'Old categories table does not exist, skipping migration';
  end if;
end $$;

-- Step 4: Drop old foreign key constraint if it exists and points to wrong table
do $$
begin
  -- Check if constraint exists and points to 'categories' table
  if exists (
    select 1
    from pg_constraint c
    join pg_class t on c.conrelid = t.oid
    join pg_class ft on c.confrelid = ft.oid
    where t.relname = 'products'
    and c.conname = 'products_category_id_fkey'
    and ft.relname = 'categories'
  ) then
    alter table products drop constraint products_category_id_fkey;
    raise notice 'Dropped old products_category_id_fkey constraint pointing to categories table';
  end if;
end $$;

-- Step 5: Add new foreign key constraint pointing to product_categories
do $$
begin
  if not exists (
    select 1
      from pg_constraint
     where conrelid = 'public.products'::regclass
       and conname = 'products_category_id_fkey'
  ) then
    alter table products
      add constraint products_category_id_fkey
        foreign key (category_id) references public.product_categories(id) on delete set null;
    raise notice 'Added products_category_id_fkey constraint pointing to product_categories';
  end if;
end $$;

create index if not exists idx_products_category_id on products(category_id);

