-- ============================================================================
-- SALES PAYMENTS TABLE (Updated to use payment_method_id)
-- ============================================================================
create table if not exists sales_payments (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade not null,
  invoice_id uuid not null references sales_invoices(id) on delete cascade,
  invoice_reference text,
  payment_method_id uuid not null,
  idempotency_key text,
  amount numeric(12,2) not null default 0,
  tax_treatment text not null default 'no_tax',
  net_amount numeric(12,2) not null default 0,
  iva_amount numeric(12,2) not null default 0,
  date timestamp with time zone not null default now(),
  reference text,
  notes text,
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  deleted_at timestamp with time zone,
  deleted_by uuid references auth.users(id) on delete set null
);

-- Add composite FK for sales_payments.payment_method_id (tenant-scoped)
do $$ begin
  alter table sales_payments drop constraint if exists sales_payments_payment_method_id_fkey;
  alter table sales_payments add constraint sales_payments_payment_method_id_fkey
    foreign key (tenant_id, payment_method_id) references payment_methods(tenant_id, id) on delete restrict;
exception
  when undefined_column then null;
  when others then raise notice '⚠️  sales_payments.payment_method_id FK: %', sqlerrm;
end $$;

-- Migration: Handle existing sales_payments with old 'method' column
-- CRITICAL: This must run BEFORE creating indexes on payment_method_id
do $$
declare
  v_has_method_column boolean;
  v_has_payment_method_id boolean;
  v_cash_method_id uuid;
begin
  -- Check if payment_method_id column already exists
  select exists (
    select 1 from information_schema.columns
    where table_schema = 'public'
      and table_name = 'sales_payments'
      and column_name = 'payment_method_id'
  ) into v_has_payment_method_id;

  -- Check if old 'method' column exists
  select exists (
    select 1 from information_schema.columns
    where table_schema = 'public'
      and table_name = 'sales_payments'
      and column_name = 'method'
  ) into v_has_method_column;

  if v_has_method_column and not v_has_payment_method_id then
    raise notice 'Migrating sales_payments from method column to payment_method_id...';

    -- Get cash payment method ID as default
    select id into v_cash_method_id from payment_methods where code = 'cash' limit 1;

    if v_cash_method_id is null then
      raise exception 'Cash payment method not found! Ensure payment_methods table is populated.';
    end if;

    -- Add new column (nullable first)
    alter table sales_payments add column payment_method_id uuid;

    -- Migrate data: map old method values to payment_method_id
    update sales_payments sp
    set payment_method_id = pm.id
    from payment_methods pm
    where sp.payment_method_id is null
      and (
        (sp.method = 'cash' and pm.code = 'cash') or
        (sp.method = 'transfer' and pm.code = 'transfer') or
        (sp.method = 'card' and pm.code = 'card') or
        (sp.method = 'check' and pm.code = 'check') or
        (sp.method = 'other' and pm.code = 'cash')  -- Default 'other' to cash
      );

    -- Set default for any remaining nulls
    update sales_payments
    set payment_method_id = v_cash_method_id
    where payment_method_id is null;

    -- Add composite foreign key constraint (tenant-scoped)
    alter table sales_payments
      add constraint sales_payments_payment_method_id_fkey
      foreign key (tenant_id, payment_method_id)
      references payment_methods(tenant_id, id);

    -- Drop old method column and constraint
    alter table sales_payments drop constraint if exists sales_payments_method_check;
    alter table sales_payments drop column if exists method;

    -- Make payment_method_id NOT NULL
    alter table sales_payments alter column payment_method_id set not null;

    raise notice 'Migration complete!';
  elsif not v_has_payment_method_id then
    raise notice 'No existing sales_payments data, payment_method_id will be added by CREATE TABLE';
  else
    raise notice 'payment_method_id already exists, skipping migration';
  end if;
end $$;

create index if not exists idx_sales_payments_invoice_id
  on sales_payments(invoice_id);
create index if not exists idx_sales_payments_payment_method_id
  on sales_payments(payment_method_id);
alter table public.sales_payments
  add column if not exists idempotency_key text;
create unique index if not exists idx_sales_payments_tenant_idempotency_key
  on sales_payments(tenant_id, idempotency_key)
  where idempotency_key is not null;

alter table public.sales_payments
  add column if not exists invoice_reference text,
  add column if not exists idempotency_key text,
  add column if not exists notes text,
  add column if not exists tax_treatment text not null default 'no_tax',
  add column if not exists net_amount numeric(12,2) not null default 0,
  add column if not exists iva_amount numeric(12,2) not null default 0,
  add column if not exists created_at timestamp with time zone not null default now(),
  add column if not exists updated_at timestamp with time zone not null default now(),
  add column if not exists deleted_at timestamp with time zone,
  add column if not exists deleted_by uuid references auth.users(id) on delete set null;

do $$
begin
  if not exists (
    select 1 from pg_trigger t
    join pg_class c on c.oid = t.tgrelid
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relname = 'sales_payments'
      and t.tgname = 'trg_sales_payments_updated_at'
  ) then
    create trigger trg_sales_payments_updated_at
      before update on sales_payments
      for each row execute procedure public.set_updated_at();
  end if;
end $$;

do $$
begin
  if not exists (
    select 1
      from pg_constraint
     where conrelid = 'public.sales_payments'::regclass
       and conname = 'sales_payments_amount_positive'
  ) then
    alter table public.sales_payments
      add constraint sales_payments_amount_positive check (amount > 0) not valid;
  end if;

  alter table public.sales_payments
    validate constraint sales_payments_amount_positive;
end $$;

create or replace function public.validate_sales_payment_integrity()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_invoice record;
  v_existing_paid numeric(12,2);
  v_remaining numeric(12,2);
  v_amount numeric(12,2);
begin
  if TG_OP = 'DELETE' then
    return OLD;
  end if;

  if NEW.deleted_at is not null then
    NEW.amount := round(coalesce(NEW.amount, 0), 2);
    return NEW;
  end if;

  if NEW.invoice_id is null then
    raise exception 'El pago debe pertenecer a una factura de venta.';
  end if;

  v_amount := round(coalesce(NEW.amount, 0), 2);
  if v_amount <= 0 then
    raise exception 'El monto del pago debe ser mayor a cero.';
  end if;
  NEW.amount := v_amount;

  select id, tenant_id, total
    into v_invoice
    from public.sales_invoices
   where id = NEW.invoice_id
   for update;

  if not found then
    raise exception 'La factura de venta asociada al pago no existe.';
  end if;

  if NEW.tenant_id is null then
    NEW.tenant_id := v_invoice.tenant_id;
  end if;

  if NEW.tenant_id is distinct from v_invoice.tenant_id then
    raise exception 'El pago no pertenece al mismo tenant que la factura de venta.';
  end if;

  select coalesce(sum(amount), 0)
    into v_existing_paid
    from public.sales_payments
   where invoice_id = NEW.invoice_id
     and deleted_at is null
     and id is distinct from NEW.id;

  v_remaining := round(greatest(coalesce(v_invoice.total, 0) - v_existing_paid, 0), 2);

  if v_amount > v_remaining then
    raise exception 'El pago excede el saldo pendiente de la factura de venta. Saldo pendiente: %, monto enviado: %.',
      v_remaining, v_amount;
  end if;

  return NEW;
end;
$$;

drop trigger if exists trg_sales_payments_validate_integrity on public.sales_payments;
create trigger trg_sales_payments_validate_integrity
  before insert or update on public.sales_payments
  for each row execute function public.validate_sales_payment_integrity();

create or replace function public.recalculate_sales_invoice_payments(p_invoice_id uuid)
returns void as $$
declare
  v_invoice record;
  v_total numeric(12,2);
  v_new_status text;
  v_balance numeric(12,2);
  v_balance_raw numeric(12,2);
begin
  if p_invoice_id is null then
    return;
  end if;

  select id,
         total,
         status
    into v_invoice
    from public.sales_invoices
   where id = p_invoice_id
   for update;

  if not found then
    return;
  end if;

  select coalesce(sum(amount), 0)
    into v_total
    from public.sales_payments
   where invoice_id = p_invoice_id
     and deleted_at is null;

  v_balance_raw := round(coalesce(v_invoice.total, 0) - v_total, 2);
  v_balance := case
    when abs(v_balance_raw) < 1 then 0
    else greatest(v_balance_raw, 0)
  end;

  -- Determine new status based on payment totals and current status
  if v_invoice.status = 'cancelled' then
    -- Keep cancelled status
    v_new_status := v_invoice.status;
  elsif v_invoice.status = 'draft' then
    -- Draft stays draft unless fully paid
    if v_balance = 0 and v_total > 0 then
      v_new_status := 'paid';
    else
      v_new_status := 'draft';
    end if;
  elsif v_balance = 0 and v_total > 0 then
    -- Fully paid
    v_new_status := 'paid';
  elsif v_total > 0 and v_balance > 0 then
    -- Partially paid - keep current status if it's overdue, otherwise set to confirmed
    if v_invoice.status = 'overdue' then
      v_new_status := 'overdue';
    else
      v_new_status := 'confirmed';
    end if;
  elsif v_total = 0 then
    -- No payments
    if v_invoice.status = 'paid' then
      -- If was paid but now has no payments, revert to confirmed
      v_new_status := 'confirmed';
    else
      -- Otherwise keep current status (draft/sent/confirmed/overdue)
      v_new_status := v_invoice.status;
    end if;
  else
    -- Fallback: keep current status
    v_new_status := v_invoice.status;
  end if;

  update public.sales_invoices
     set paid_amount = v_total,
         balance = v_balance,
         status = v_new_status,
         updated_at = now()
   where id = p_invoice_id;

  -- SYNC: Update mechanic_jobs if this invoice is linked to a job
  perform public.sync_invoice_status_to_job(p_invoice_id);
end;
$$ language plpgsql;

create or replace function public.create_sales_payment_journal_entry(p_payment public.sales_payments)
returns void as $$
declare
  v_invoice record;
  v_entry_id uuid := gen_random_uuid();
  v_exists boolean;
  v_payment_method record;
  v_cash_account_id uuid;
  v_cash_account_code text;
  v_cash_account_name text;
  v_receivable_account_id uuid;
  v_receivable_account_code text := '1130';
  v_receivable_account_name text := 'Cuentas por Cobrar Comerciales';
  v_description text;
  v_tenant_id uuid;
begin
  if p_payment.invoice_id is null then
    return;
  end if;

  -- Skip if payment is soft deleted
  if p_payment.deleted_at is not null then
    raise notice 'create_sales_payment_journal_entry: Payment % is deleted, skipping', p_payment.id;
    return;
  end if;

  v_tenant_id := p_payment.tenant_id;

  -- CRITICAL: Validate tenant_id for service role context (webhooks)
  if v_tenant_id is null then
    raise warning 'create_sales_payment_journal_entry: No tenant_id on payment %, skipping', p_payment.id;
    return;
  end if;

  select exists (
           select 1
             from public.journal_entries
            where source_module = 'sales_payments'
              and source_reference = p_payment.id::text
              and tenant_id = v_tenant_id
        )
    into v_exists;

  if v_exists then
    return;
  end if;

  select id,
         invoice_number,
         customer_name,
         total
    into v_invoice
    from public.sales_invoices
   where id = p_payment.invoice_id;

  if not found then
    return;
  end if;

  -- Get payment method and its associated account (DYNAMIC!)
  select pm.id, pm.code, pm.name, a.id as account_id, a.code as account_code, a.name as account_name
    into v_payment_method
    from public.payment_methods pm
    join public.accounts a on a.id = pm.account_id
   where pm.id = p_payment.payment_method_id;

  if not found then
    raise exception 'Payment method not found for payment %', p_payment.id;
  end if;

  -- Use the account from payment method configuration
  v_cash_account_id := v_payment_method.account_id;
  v_cash_account_code := v_payment_method.account_code;
  v_cash_account_name := v_payment_method.account_name;

  v_receivable_account_id := public.ensure_account(
    v_tenant_id,
    v_receivable_account_code,
    v_receivable_account_name,
    'asset',
    'currentAsset',
    'Cuentas por cobrar a clientes',
    null
  );

  v_description := format('Pago factura %s - %s',
    coalesce(v_invoice.invoice_number, v_invoice.id::text),
    v_payment_method.name
  );

  insert into public.journal_entries (
    id,
    tenant_id,
    entry_number,
    entry_date,
    description,
    type,
    source_module,
    source_reference,
    status,
    total_debit,
    total_credit,
    created_at,
    updated_at
  ) values (
    v_entry_id,
    v_tenant_id,
    public.get_next_document_number(v_tenant_id, 'journal_entry'),
    coalesce(p_payment.date, now()),
    v_description,
    'payment',
    'sales_payments',
    p_payment.id::text,
    'posted',
    p_payment.amount,
    p_payment.amount,
    now(),
    now()
  );

  insert into public.journal_lines (
    id,
    tenant_id,
    entry_id,
    account_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_tenant_id,
    v_entry_id,
    v_cash_account_id,
    v_cash_account_code,
    v_cash_account_name,
    format('Cobro a %s', coalesce(v_invoice.customer_name, 'Cliente')),
    p_payment.amount,
    0,
    now(),
    now()
  );

  -- Payment JE clears accounts receivable only.
  -- Revenue and IVA recognition belong in the sales invoice JE.
  insert into public.journal_lines (
    id,
    tenant_id,
    entry_id,
    account_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_tenant_id,
    v_entry_id,
    v_receivable_account_id,
    v_receivable_account_code,
    v_receivable_account_name,
    format('Cancelación factura %s', coalesce(v_invoice.invoice_number, v_invoice.id::text)),
    0,
    p_payment.amount,
    now(),
    now()
  );
end;
$$ language plpgsql security definer set search_path = public;

create or replace function public.delete_sales_payment_journal_entry(p_payment_id uuid)
returns void as $$
begin
  if p_payment_id is null then
    return;
  end if;

  delete from public.journal_entries
   where source_module = 'sales_payments'
     and source_reference = p_payment_id::text;
end;
$$ language plpgsql security definer set search_path = public;

-- ============================================================================
-- PURCHASE PAYMENT JOURNAL ENTRY FUNCTIONS (Mirror sales payment pattern)
-- ============================================================================

create or replace function public.recalculate_purchase_invoice_payments(p_invoice_id uuid)
returns void as $$
declare
  v_invoice record;
  v_total numeric(12,2);
  v_new_status text;
  v_balance numeric(12,2);
  v_balance_raw numeric(12,2);
begin
  if p_invoice_id is null then
    return;
  end if;

  select id,
         total,
         status,
         prepayment_model,
         received_date
    into v_invoice
    from public.purchase_invoices
   where id = p_invoice_id
   for update;

  if not found then
    return;
  end if;

  select coalesce(sum(amount), 0)
    into v_total
    from public.purchase_payments
   where invoice_id = p_invoice_id
     and deleted_at is null;

  v_balance_raw := round(coalesce(v_invoice.total, 0) - v_total, 2);
  v_balance := case
    when abs(v_balance_raw) < 1 then 0
    else greatest(v_balance_raw, 0)
  end;

  -- Status transition logic based on prepayment model
  -- Standard model: Draft→Sent→Confirmed→Received→Paid
  -- Prepayment model: Draft→Sent→Confirmed→Paid→Received

  if v_invoice.status = 'cancelled' then
    -- Cancelled invoices stay cancelled regardless of payments
    v_new_status := 'cancelled';

  elsif v_invoice.status = 'received' or v_invoice.received_date is not null then
    -- Receiving inventory is the terminal purchase workflow state.
    -- Payment recalculation must never downgrade it back to paid/confirmed.
    v_new_status := 'received';

  elsif v_invoice.status IN ('draft', 'sent') then
    -- Pre-confirmation statuses: stay as-is regardless of payments
    v_new_status := v_invoice.status;

  elsif v_balance = 0 and v_total > 0 then
    -- Fully paid
    v_new_status := 'paid';

  elsif v_total > 0 and v_balance > 0 then
    -- A partially paid invoice cannot remain marked paid. Received invoices
    -- were handled above and keep their physical receipt state.
    v_new_status := 'confirmed';

  else
    -- No active payments: a non-received paid invoice returns to confirmed.
    v_new_status := case
      when v_invoice.status = 'paid' then 'confirmed'
      else v_invoice.status
    end;
  end if;

  update public.purchase_invoices
     set paid_amount = v_total,
         balance = v_balance,
         status = v_new_status,
         updated_at = now()
   where id = p_invoice_id;
end;
$$ language plpgsql;

-- CRITICAL: Drop ALL versions of function to clear cached type definition
-- Drop old version with uuid parameter (if exists from previous schema)
drop function if exists public.create_purchase_payment_journal_entry(uuid) cascade;
drop function if exists public.create_purchase_payment_journal_entry(p_payment_id uuid) cascade;
-- Drop new version with composite type parameter
drop function if exists public.create_purchase_payment_journal_entry(public.purchase_payments) cascade;
drop function if exists public.create_purchase_payment_journal_entry(p_payment public.purchase_payments) cascade;

-- WORKAROUND: Use payment ID instead of composite type to avoid type cache issues
create or replace function public.create_purchase_payment_journal_entry(p_payment_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payment record;
  v_invoice record;
  v_entry_id uuid := gen_random_uuid();
  v_exists boolean;
  v_payment_method record;
  v_cash_account_id uuid;
  v_cash_account_code text;
  v_cash_account_name text;
  v_payable_account_id uuid;
  v_payable_account_code text := '2101';
  v_payable_account_name text := 'Cuentas por Pagar Proveedores';
  v_description text;
  v_tenant_id uuid;
begin
  -- Fetch payment data from table instead of using composite type parameter
  select id, invoice_id, amount, date, payment_method_id, tenant_id, deleted_at
    into v_payment
    from public.purchase_payments
   where id = p_payment_id;

  if not found or v_payment.invoice_id is null or v_payment.deleted_at is not null then
    return;
  end if;

  v_tenant_id := v_payment.tenant_id;

  if v_tenant_id is null then
    raise warning 'create_purchase_payment_journal_entry: No tenant_id on payment %, skipping', v_payment.id;
    return;
  end if;

  select exists (
           select 1
             from public.journal_entries
            where tenant_id = v_tenant_id
              and source_module = 'purchase_payments'
              and source_reference = v_payment.id::text
        )
    into v_exists;

  if v_exists then
    return;
  end if;

  select id,
         invoice_number,
         supplier_name,
         total
    into v_invoice
    from public.purchase_invoices
   where id = v_payment.invoice_id;

  if not found then
    return;
  end if;

  -- Get payment method and its associated account (DYNAMIC!)
  select pm.id, pm.code, pm.name, a.id as account_id, a.code as account_code, a.name as account_name
    into v_payment_method
    from public.payment_methods pm
    join public.accounts a on a.id = pm.account_id
   where pm.id = v_payment.payment_method_id;

  if not found then
    raise exception 'Payment method not found for payment %', v_payment.id;
  end if;

  -- Use the account from payment method configuration
  v_cash_account_id := v_payment_method.account_id;
  v_cash_account_code := v_payment_method.account_code;
  v_cash_account_name := v_payment_method.account_name;

  v_payable_account_id := public.ensure_account(
    v_tenant_id,
    v_payable_account_code,
    v_payable_account_name,
    'liability',
    'currentLiability',
    'Cuentas por pagar a proveedores',
    null
  );

  v_description := format('Pago factura compra %s - %s',
    coalesce(v_invoice.invoice_number, v_invoice.id::text),
    v_payment_method.name
  );

  insert into public.journal_entries (
    id,
    tenant_id,
    entry_number,
    entry_date,
    description,
    type,
    source_module,
    source_reference,
    status,
    total_debit,
    total_credit,
    created_at,
    updated_at
  ) values (
    v_entry_id,
    v_tenant_id,
    public.get_next_document_number(v_tenant_id, 'journal_entry'),
    coalesce(v_payment.date, now()),
    v_description,
    'payment',
    'purchase_payments',
    v_payment.id::text,
    'posted',
    v_payment.amount,
    v_payment.amount,
    now(),
    now()
  );

  -- DR: Accounts Payable (reduce liability)
  insert into public.journal_lines (
    id,
    tenant_id,
    entry_id,
    account_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_tenant_id,
    v_entry_id,
    v_payable_account_id,
    v_payable_account_code,
    v_payable_account_name,
    v_description,
    v_payment.amount,
    0,
    now(),
    now()
  );

  -- CR: Cash/Bank account (reduce asset)
  insert into public.journal_lines (
    id,
    tenant_id,
    entry_id,
    account_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_tenant_id,
    v_entry_id,
    v_cash_account_id,
    v_cash_account_code,
    v_cash_account_name,
    v_description,
    0,
    v_payment.amount,
    now(),
    now()
  );
end;
$$;

create or replace function public.delete_purchase_payment_journal_entry(p_payment_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_payment_id is null then
    return;
  end if;

  delete from public.journal_entries
   where source_module = 'purchase_payments'
     and source_reference = p_payment_id::text;
end;
$$;

create or replace function public.delete_purchase_payment_journal_entry(
  p_payment_id uuid,
  p_invoice_id uuid,
  p_tenant_id uuid,
  p_expected_amount numeric
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_invoice_number text;
  v_id_journal_count integer;
  v_legacy_journal_count integer;
  v_matching_legacy_count integer;
begin
  if p_payment_id is null then
    return;
  end if;

  select count(*)::integer
    into v_id_journal_count
    from public.journal_entries entry
   where entry.tenant_id = p_tenant_id
     and entry.source_module = 'purchase_payments'
     and entry.source_reference = p_payment_id::text;

  if v_id_journal_count > 1 then
    raise exception 'Payment % has % current journal entries', p_payment_id, v_id_journal_count
      using errcode = 'check_violation';
  elsif v_id_journal_count = 1 then
    delete from public.journal_entries entry
     where entry.tenant_id = p_tenant_id
       and entry.source_module = 'purchase_payments'
       and entry.source_reference = p_payment_id::text;
    return;
  end if;

  select invoice.invoice_number
    into v_invoice_number
    from public.purchase_invoices invoice
   where invoice.id = p_invoice_id
     and invoice.tenant_id = p_tenant_id;

  if v_invoice_number is null then
    return;
  end if;

  select
    count(*)::integer,
    count(*) filter (
      where public.clp_round(entry.total_debit)
            = public.clp_round(p_expected_amount)
        and public.clp_round(entry.total_credit)
            = public.clp_round(p_expected_amount)
    )::integer
    into v_legacy_journal_count, v_matching_legacy_count
    from public.journal_entries entry
   where entry.tenant_id = p_tenant_id
     and entry.source_module = 'purchase_payments'
     and entry.source_reference = v_invoice_number;

  if v_legacy_journal_count = 0 then
    return;
  end if;

  if v_legacy_journal_count <> 1 or v_matching_legacy_count <> 1 then
    raise exception
      'Legacy payment journals for invoice % are ambiguous (journals %, matching amount %); payment edit/undo stopped for audit review',
      v_invoice_number, v_legacy_journal_count, v_matching_legacy_count
      using errcode = 'check_violation';
  end if;

  delete from public.journal_entries entry
   where entry.tenant_id = p_tenant_id
     and entry.source_module = 'purchase_payments'
     and entry.source_reference = v_invoice_number;
end;
$$;

-- CRITICAL: Drop trigger FIRST, then function to clear cached type definition
-- Using CASCADE to ensure all dependencies are dropped
do $$
begin
  if to_regclass('public.purchase_payments') is not null then
    execute 'drop trigger if exists trg_purchase_payments_change on public.purchase_payments cascade';
  end if;
exception
  when others then
    raise notice '⚠️  trg_purchase_payments_change drop skipped: %', sqlerrm;
end;
$$;
drop function if exists public.handle_purchase_payment_change() cascade;

create or replace function public.handle_purchase_payment_change()
returns trigger as $$
begin
  if TG_OP = 'INSERT' then
    perform public.create_purchase_payment_journal_entry(NEW.id);
    perform public.recalculate_purchase_invoice_payments(NEW.invoice_id);
  elsif TG_OP = 'UPDATE' then
    if NEW.invoice_id is distinct from OLD.invoice_id then
      perform public.recalculate_purchase_invoice_payments(OLD.invoice_id);
    end if;
    perform public.delete_purchase_payment_journal_entry(
      OLD.id, OLD.invoice_id, OLD.tenant_id, OLD.amount
    );
    perform public.create_purchase_payment_journal_entry(NEW.id);
    perform public.recalculate_purchase_invoice_payments(NEW.invoice_id);
  elsif TG_OP = 'DELETE' then
    perform public.delete_purchase_payment_journal_entry(
      OLD.id, OLD.invoice_id, OLD.tenant_id, OLD.amount
    );
    perform public.recalculate_purchase_invoice_payments(OLD.invoice_id);
  end if;
  return NULL;
end;
$$ language plpgsql;

create or replace function public.consume_sales_invoice_inventory(p_invoice public.sales_invoices)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_item record;
  v_resolved_product_id uuid;
  v_quantity_int integer;
  v_status text;
  v_reference text;
  v_net_quantity integer;
  v_items_count integer;
  v_is_set boolean;
  v_component record;
  v_qty_to_deduct integer;
  v_set_name text;
begin
  -- CRITICAL: Set flag to skip stock_adjustment trigger for automatic changes
  perform set_config('app.skip_stock_adjustment_trigger', 'true', true);

  -- Early exit if invoice ID is null
  if p_invoice.id is null then
    raise notice 'consume_sales_invoice_inventory: invoice ID is null';
    return;
  end if;
  if p_invoice.tenant_id is null then
    raise exception 'Sales invoice tenant is required for inventory consumption'
      using errcode = '23503';
  end if;

  v_status := lower(coalesce(p_invoice.status, 'draft'));

  -- Only process if status is posted
  if v_status = any (array['draft','borrador','cancelled','cancelado','cancelada','anulado','anulada']) then
    return;
  end if;

  -- Check if inventory reduction already done
  v_reference := concat('sales_invoice:', p_invoice.id::text);
  select coalesce(sum(quantity), 0)::integer
    into v_net_quantity
    from public.stock_movements
   where tenant_id = p_invoice.tenant_id
     and reference = v_reference;

  if v_net_quantity < 0 then
    return;
  end if;

  -- Count items
  select jsonb_array_length(coalesce(p_invoice.items, '[]'::jsonb))
    into v_items_count;

  -- Process each item
  for v_item in
    select
      nullif(item->>'product_id', '')::uuid as product_id,
      (item->>'product_sku')::text as product_sku,
      coalesce(nullif(item->>'purchase_treatment', ''), 'inventory')::text as purchase_treatment,
      (item->>'quantity')::numeric as quantity
    from jsonb_array_elements(coalesce(p_invoice.items, '[]'::jsonb)) item
  loop
    v_resolved_product_id := v_item.product_id;

    if v_resolved_product_id is not null and not exists (
      select 1 from public.products product
      where product.id = v_resolved_product_id
        and product.tenant_id = p_invoice.tenant_id
    ) then
      if exists (
        select 1 from public.products product
        where product.id = v_resolved_product_id
      ) then
        raise exception 'Sales invoice product belongs to another tenant'
          using errcode = '42501';
      end if;
      v_resolved_product_id := null;
    end if;

    -- Resolve SKU only inside the invoice tenant. A SKU known exclusively in
    -- another tenant is an isolation violation, not a free-text line.
    if v_resolved_product_id is null
       and nullif(v_item.product_sku, '') is not null then
      select product.id
        into v_resolved_product_id
        from public.products product
       where product.tenant_id = p_invoice.tenant_id
         and product.sku = v_item.product_sku
       limit 1;
      if not found then
        if exists (
          select 1 from public.products product
          where product.sku = v_item.product_sku
            and product.tenant_id <> p_invoice.tenant_id
        ) then
          raise exception 'Sales invoice SKU belongs to another tenant'
            using errcode = '42501';
        end if;
      end if;
    end if;

    v_quantity_int := coalesce(v_item.quantity::int, 0);

    if v_resolved_product_id is null or v_quantity_int <= 0 then
      continue;
    end if;

    if v_item.purchase_treatment = 'workshop_consumable' then
      continue;
    end if;

    -- CHECK IF PRODUCT IS A SET
    select is_set, name
      into v_is_set, v_set_name
     from public.products
     where id = v_resolved_product_id
       and tenant_id = p_invoice.tenant_id
       and coalesce(track_stock, true) = true;

    if not found then
      continue;
    end if;

    if v_is_set then
       -- Iterate over components
       for v_component in
         select
           component_product_id,
           quantity_in_set
         from public.product_set_components
         where tenant_id = p_invoice.tenant_id
           and set_product_id = v_resolved_product_id
       loop
          v_qty_to_deduct := v_quantity_int * v_component.quantity_in_set;

          -- Deduct Component Stock
          update public.products
             set inventory_qty = coalesce(stock_quantity, inventory_qty, 0) - v_qty_to_deduct,
                 stock_quantity = coalesce(stock_quantity, inventory_qty, 0) - v_qty_to_deduct,
                 updated_at = now()
           where id = v_component.component_product_id
             and tenant_id = p_invoice.tenant_id;

          if not found then
            raise exception 'Sales invoice set component is outside the current tenant'
              using errcode = '42501';
          else
            -- Log Component Movement (FIXED: Includes tenant_id)
            insert into public.stock_movements (
              tenant_id, id, product_id, warehouse_id, type, movement_type, quantity,
              reference, notes, date, created_at, updated_at
            ) values (
              p_invoice.tenant_id, -- ✅ Added tenant_id
              gen_random_uuid(),
              v_component.component_product_id,
              null,
              'OUT',
              'sales_invoice_component',
              -v_qty_to_deduct,
              v_reference,
              format('Salida por venta de Set "%s" (Factura %s)',
                     v_set_name,
                     coalesce(nullif(p_invoice.invoice_number, ''), p_invoice.id::text)
              ),
              coalesce(p_invoice.date, now()),
              now(),
              now()
            );
          end if;
       end loop;

    else
      -- STANDARD LOGIC: NOT A SET
      update public.products
         set inventory_qty = coalesce(stock_quantity, inventory_qty, 0) - v_quantity_int,
             stock_quantity = coalesce(stock_quantity, inventory_qty, 0) - v_quantity_int,
             updated_at = now()
       where id = v_resolved_product_id
         and tenant_id = p_invoice.tenant_id
         and coalesce(is_service, false) = false
         and coalesce(track_stock, true) = true;

      if found then
        -- Create stock movement record (FIXED: Includes tenant_id)
        insert into public.stock_movements (
          tenant_id, id, product_id, warehouse_id, type, movement_type, quantity,
          reference, notes, date, created_at, updated_at
        ) values (
          p_invoice.tenant_id, -- ✅ Added tenant_id
          gen_random_uuid(),
          v_resolved_product_id,
          null,
          'OUT',
          'sale',
          -v_quantity_int,
          v_reference,
          concat('Salida por venta (Factura ', coalesce(nullif(p_invoice.invoice_number, ''), p_invoice.id::text), ')'),
          coalesce(p_invoice.date, now()),
          now(),
          now()
        );
      end if;
    end if;
  end loop;

  raise notice 'consume_sales_invoice_inventory: completed for invoice %', p_invoice.id;
end;
$$;

create or replace function public.restore_sales_invoice_inventory(p_invoice public.sales_invoices)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_reference text;
  v_movement record;
  v_has_inventory_qty boolean := false;
  v_has_stock_quantity boolean := false;
  v_has_is_service boolean := false;
  v_has_track_stock boolean := false;
  v_has_updated_at boolean := false;
  v_update_assignments text := '';
  v_update_sql text;
  v_quantity_int integer;
begin
  if p_invoice.id is null then
    return;
  end if;

  perform set_config('app.skip_stock_adjustment_trigger', 'true', true);

  v_reference := concat('sales_invoice:', p_invoice.id::text);

  select exists (
           select 1
             from information_schema.columns
            where table_schema = 'public'
              and table_name = 'products'
              and column_name = 'inventory_qty'
         )
    into v_has_inventory_qty;

  select exists (
           select 1
             from information_schema.columns
            where table_schema = 'public'
              and table_name = 'products'
              and column_name = 'stock_quantity'
         )
    into v_has_stock_quantity;

  select exists (
           select 1
             from information_schema.columns
            where table_schema = 'public'
              and table_name = 'products'
              and column_name = 'is_service'
         )
    into v_has_is_service;

  select exists (
           select 1
             from information_schema.columns
            where table_schema = 'public'
              and table_name = 'products'
              and column_name = 'track_stock'
         )
    into v_has_track_stock;

  select exists (
           select 1
             from information_schema.columns
            where table_schema = 'public'
              and table_name = 'products'
              and column_name = 'updated_at'
         )
    into v_has_updated_at;

  if not v_has_inventory_qty and not v_has_stock_quantity then
    perform set_config('app.skip_stock_adjustment_trigger', '', true);
    return;
  end if;

  if v_has_inventory_qty then
    v_update_assignments := v_update_assignments || 'inventory_qty = coalesce(inventory_qty, 0) + $1';
  end if;

  if v_has_stock_quantity then
    if v_update_assignments <> '' then
      v_update_assignments := v_update_assignments || ', ';
    end if;
    v_update_assignments := v_update_assignments || 'stock_quantity = coalesce(stock_quantity, 0) + $1';
  end if;

  if v_has_updated_at then
    if v_update_assignments <> '' then
      v_update_assignments := v_update_assignments || ', ';
    end if;
    v_update_assignments := v_update_assignments || 'updated_at = now()';
  end if;

  if v_update_assignments = '' then
    perform set_config('app.skip_stock_adjustment_trigger', '', true);
    return;
  end if;

  v_update_sql := 'update public.products set ' || v_update_assignments || ' where id = $2';

  if v_has_is_service then
    v_update_sql := v_update_sql || ' and coalesce(is_service, false) = false';
  end if;

  if v_has_track_stock then
    v_update_sql := v_update_sql || ' and coalesce(track_stock, true) = true';
  end if;

  for v_movement in
    select product_id, abs(sum(quantity))::integer as quantity
      from public.stock_movements
     where reference = v_reference
     group by product_id
    having sum(quantity) < 0
  loop
    if v_movement.product_id is null or v_movement.quantity = 0 then
      continue;
    end if;

    v_quantity_int := abs(coalesce(v_movement.quantity::int, 0));

    if v_quantity_int = 0 then
      continue;
    end if;

    execute v_update_sql using v_quantity_int, v_movement.product_id;

    insert into public.stock_movements (
      tenant_id,
      id,
      product_id,
      warehouse_id,
      type,
      movement_type,
      quantity,
      reference,
      notes,
      date,
      created_at,
      updated_at
    ) values (
      p_invoice.tenant_id,
      gen_random_uuid(),
      v_movement.product_id,
      null,
      'IN',
      'sales_invoice_reversal',
      v_quantity_int,
      v_reference,
      concat(
        'Reversión de salida por factura ',
        coalesce(nullif(p_invoice.invoice_number, ''), p_invoice.id::text)
      ),
      coalesce(p_invoice.date, now()),
      now(),
      now()
    );
  end loop;

  perform set_config('app.skip_stock_adjustment_trigger', '', true);
end;
$$;

create or replace function public.create_sales_invoice_journal_entry(p_invoice public.sales_invoices)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_exists boolean;
  v_entry_id uuid := gen_random_uuid();
  v_receivable_account_code text := '1130';
  v_receivable_account_name text := 'Cuentas por Cobrar Comerciales';
  v_receivable_account_id uuid;
  v_revenue_account_code text := '4100';
  v_revenue_account_name text := 'Ingresos Operacionales';
  v_revenue_account_id uuid;
  v_iva_account_code text := '2150';
  v_iva_account_name text := 'IVA Débito Fiscal';
  v_iva_account_id uuid;
  v_inventory_account_code text := '1105';
  v_inventory_account_name text := 'Inventarios';
  v_inventory_account_id uuid;
  v_cogs_account_code text := '5100';
  v_cogs_account_name text := 'Costo de Ventas';
  v_cogs_account_id uuid;
  v_invoice_number text;
  v_customer_name text;
  v_description text;
  v_subtotal numeric(12,2);
  v_iva numeric(12,2);
  v_total numeric(12,2);
  v_total_cost numeric(12,2);
  v_tenant_id uuid;
begin
  if p_invoice.id is null then
    return;
  end if;

  if coalesce(p_invoice.status, 'draft') in ('draft', 'cancelled') then
    return;
  end if;

  v_tenant_id := p_invoice.tenant_id;

  -- CRITICAL: Validate tenant_id for service role context (webhooks)
  if v_tenant_id is null then
    raise warning 'create_sales_invoice_journal_entry: No tenant_id on invoice %, skipping', p_invoice.id;
    return;
  end if;

  -- Check for existing journal entry using invoice_number (consistent with INSERT)
  select exists (
           select 1
             from public.journal_entries
            where source_module = 'sales_invoices'
              and source_reference = p_invoice.invoice_number
              and tenant_id = v_tenant_id
       )
    into v_exists;

  if v_exists then
    raise notice 'create_sales_invoice_journal_entry: Entry already exists for invoice %, skipping', p_invoice.invoice_number;
    return;
  end if;

  raise notice 'create_sales_invoice_journal_entry: Creating entry for invoice % (status: %)', p_invoice.invoice_number, p_invoice.status;

  -- ✅ CRITICAL: Use net_amount (tax-adjusted) if available, fallback to subtotal
  -- [FIX: IVA BREAKDOWN] Ensure net_amount and iva_amount are correctly handled
  -- If tax_included, we MUST have a breakdown. Fallback to calculation if fields are 0.
  v_subtotal := coalesce(nullif(p_invoice.net_amount, 0), p_invoice.subtotal, 0);
  v_iva := coalesce(nullif(p_invoice.iva_amount, 0), 0);

  if p_invoice.tax_treatment = 'tax_included' and (v_iva = 0 or v_subtotal = p_invoice.total) then
    v_subtotal := round(p_invoice.total / 1.19, 2);
    v_iva := p_invoice.total - v_subtotal;
  end if;

  v_total := coalesce(p_invoice.total, v_subtotal + v_iva);

  if v_total = 0 then
    return;
  end if;

  v_receivable_account_id := public.ensure_account(
    v_tenant_id,
    v_receivable_account_code,
    v_receivable_account_name,
    'asset',
    'currentAsset',
    'Cuentas por cobrar a clientes',
    null
  );

  v_revenue_account_id := public.ensure_account(
    v_tenant_id,
    v_revenue_account_code,
    v_revenue_account_name,
    'income',
    'operatingIncome',
    'Ingresos operacionales por ventas',
    null
  );

  v_iva_account_id := public.ensure_account(
    v_tenant_id,
    v_iva_account_code,
    v_iva_account_name,
    'liability',
    'currentLiability',
    'IVA generado en ventas',
    null
  );

  select coalesce(
           sum(
             case
               when coalesce((item->>'is_service')::boolean, false) then 0
               when coalesce(nullif(item->>'purchase_treatment', ''), 'inventory') = 'workshop_consumable' then 0
               else coalesce((item->>'quantity')::numeric, 0) * coalesce((item->>'cost')::numeric, 0)
             end
           ),
           0
         )
    into v_total_cost
    from jsonb_array_elements(coalesce(p_invoice.items, '[]'::jsonb)) item
   where (item->>'cost') is not null
     and (item->>'cost') <> '';

  if v_total_cost > 0 then
    v_inventory_account_id := public.ensure_account(
      v_tenant_id,
      v_inventory_account_code,
      v_inventory_account_name,
      'asset',
      'currentAsset',
      'Inventario disponible para la venta',
      null
    );

    v_cogs_account_id := public.ensure_account(
      v_tenant_id,
      v_cogs_account_code,
      v_cogs_account_name,
      'expense',
      'costOfGoodsSold',
      'Costo de ventas',
      null
    );
  end if;

  v_invoice_number := coalesce(nullif(p_invoice.invoice_number, ''), p_invoice.id::text);
  v_customer_name := coalesce(nullif(p_invoice.customer_name, ''), 'Cliente');
  v_description := format('Factura %s - %s', v_invoice_number, v_customer_name);

  insert into public.journal_entries (
    id,
    tenant_id,
    entry_number,
    entry_date,
    description,
    type,
    source_module,
    source_reference,
    status,
    total_debit,
    total_credit,
    created_at,
    updated_at
  ) values (
    v_entry_id,
    v_tenant_id,
    public.get_next_document_number(v_tenant_id, 'journal_entry'),
    coalesce(p_invoice.date, now()),
    v_description,
    'sales',
    'sales_invoices',
    p_invoice.invoice_number,
    'posted',
    v_total,
    v_total,
    now(),
    now()
  );

  insert into public.journal_lines (
    id,
    tenant_id,
    entry_id,
    account_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_tenant_id,
    v_entry_id,
    v_receivable_account_id,
    v_receivable_account_code,
    v_receivable_account_name,
    v_description,
    v_total,
    0,
    now(),
    now()
  );

  if v_total - v_iva <> 0 then
    insert into public.journal_lines (
      id,
      tenant_id,
      entry_id,
      account_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_tenant_id,
      v_entry_id,
      v_revenue_account_id,
      v_revenue_account_code,
      v_revenue_account_name,
      format('Ingreso por venta %s', v_invoice_number),
      0,
      v_total - v_iva,
      now(),
      now()
    );
  end if;

  if v_iva <> 0 then
    insert into public.journal_lines (
      id,
      tenant_id,
      entry_id,
      account_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_tenant_id,
      v_entry_id,
      v_iva_account_id,
      v_iva_account_code,
      v_iva_account_name,
      format('IVA débito factura %s', v_invoice_number),
      0,
      v_iva,
      now(),
      now()
    );
  end if;

  if v_total_cost > 0 then
    insert into public.journal_lines (
      id,
      tenant_id,
      entry_id,
      account_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_tenant_id,
      v_entry_id,
      v_cogs_account_id,
      v_cogs_account_code,
      v_cogs_account_name,
      format('Costo de ventas %s', v_invoice_number),
      v_total_cost,
      0,
      now(),
      now()
    ), (
      gen_random_uuid(),
      v_tenant_id,
      v_entry_id,
      v_inventory_account_id,
      v_inventory_account_code,
      v_inventory_account_name,
      format('Salida inventario factura %s', v_invoice_number),
      0,
      v_total_cost,
      now(),
      now()
    );
  end if;
end;
$$;

create or replace function public.delete_sales_invoice_journal_entry(p_invoice_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_invoice_number text;
  v_tenant_id uuid;
begin
  if p_invoice_id is null then
    return;
  end if;

  select si.invoice_number, si.tenant_id
    into v_invoice_number, v_tenant_id
    from public.sales_invoices si
   where si.id = p_invoice_id;

  if v_tenant_id is null then
    return;
  end if;

  delete from public.journal_entries
   where tenant_id = v_tenant_id
     and source_module = 'sales_invoices'
     and source_reference in (
       coalesce(nullif(v_invoice_number, ''), p_invoice_id::text),
       p_invoice_id::text
     );
end;
$$;

-- Idempotent wrapper: ensures a sales invoice JE exists for confirmed/paid invoices.
-- Called from Dart after updateInvoiceStatus as a safety net in case the trigger
-- did not fire (old trigger version, depth > 1, or any other reason).
-- Internally uses create_sales_invoice_journal_entry which has its own duplicate check.
create or replace function public.ensure_sales_invoice_journal_entry(p_invoice_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_invoice public.sales_invoices%rowtype;
begin
  if p_invoice_id is null then
    return;
  end if;

  select * into v_invoice
    from public.sales_invoices
   where id = p_invoice_id;

  if not found then
    raise notice 'ensure_sales_invoice_journal_entry: invoice % not found', p_invoice_id;
    return;
  end if;

  -- create_sales_invoice_journal_entry already checks for duplicate JE,
  -- so this call is idempotent — safe to call even if trigger already ran.
  perform public.create_sales_invoice_journal_entry(v_invoice);
end;
$$;

grant execute on function public.ensure_sales_invoice_journal_entry(uuid) to authenticated;

-- Stable comparison of only the invoice fields that can change physical stock.
-- Price, tax, cost, notes, and line ordering must not create stock reversals.
create or replace function public.invoice_inventory_signature(p_items jsonb)
returns jsonb
language sql
immutable
set search_path = public
as $$
  select coalesce(
    jsonb_agg(item_signature order by item_signature::text),
    '[]'::jsonb
  )
  from (
    select jsonb_build_object(
      'product_id', nullif(item->>'product_id', ''),
      'product_sku', nullif(item->>'product_sku', ''),
      'quantity', coalesce(nullif(item->>'quantity', '')::numeric, 0),
      'purchase_treatment', coalesce(nullif(item->>'purchase_treatment', ''), 'inventory'),
      'is_service', coalesce(nullif(item->>'is_service', '')::boolean, false)
    ) as item_signature
    from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) item
  ) normalized_items;
$$;

create or replace function public.handle_sales_invoice_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_non_posted constant text[] := array[
    'draft','borrador',
    'sent','enviado','enviada','issued','emitido','emitida',
    'cancelled','cancelado','cancelada','anulado','anulada'
  ];
  v_old_status text;
  v_new_status text;
  v_old_posted boolean;
  v_new_posted boolean;
begin
  raise notice 'handle_sales_invoice_change: TG_OP=%', TG_OP;

  -- 🔄 CIRCULAR SYNC GUARD: Skip if already syncing in either direction
  if current_setting('app.syncing_job_to_invoice', true) = 'true' or
     current_setting('app.syncing_invoice_to_job', true) = 'true' then
    raise notice 'handle_sales_invoice_change: skipping due to active sync';
    if TG_OP = 'DELETE' then return OLD; end if;
    return NEW;
  end if;

  -- Prevent infinite recursion
  if pg_trigger_depth() > 1 then
    raise notice 'handle_sales_invoice_change: trigger depth > 1, returning';
    if TG_OP = 'DELETE' then
      return OLD;
    else
      return NEW;
    end if;
  end if;

  if TG_OP = 'INSERT' then
    v_new_status := lower(coalesce(NEW.status, 'draft'));
    raise notice 'handle_sales_invoice_change: INSERT invoice %, status %', NEW.id, v_new_status;

    -- Only process if status is "confirmed" or "paid" (NOT "draft" or "sent")
    if not (v_new_status = any (v_non_posted)) then
      raise notice 'handle_sales_invoice_change: INSERT with posted status, consuming inventory';
      perform public.consume_sales_invoice_inventory(NEW);
      perform public.create_sales_invoice_journal_entry(NEW);
    else
      raise notice 'handle_sales_invoice_change: INSERT with non-posted status (%), skipping', v_new_status;
    end if;

    perform public.recalculate_sales_invoice_payments(NEW.id);
    -- SYNC: Update linked trabajo with invoice data
    perform public.sync_invoice_items_to_job(NEW.id);
    perform public.sync_invoice_status_to_job(NEW.id);
    return NEW;

  elsif TG_OP = 'UPDATE' then
    v_old_status := lower(coalesce(OLD.status, 'draft'));
    v_new_status := lower(coalesce(NEW.status, 'draft'));

    raise notice 'handle_sales_invoice_change: UPDATE invoice %, old status %, new status %', NEW.id, v_old_status, v_new_status;

    v_old_posted := not (v_old_status = any (v_non_posted));
    v_new_posted := not (v_new_status = any (v_non_posted));

    -- Handle inventory changes based on status transition
    if v_old_posted and v_new_posted then
      -- A posted document remains the stock owner. If its item snapshot changes,
      -- reverse the previously posted snapshot and apply the new one atomically.
      -- Both helpers use the same invoice reference, so retries remain net-idempotent.
      if public.invoice_inventory_signature(OLD.items)
           is distinct from public.invoice_inventory_signature(NEW.items) then
        raise notice 'handle_sales_invoice_change: posted items changed, replacing inventory snapshot';
        perform public.restore_sales_invoice_inventory(OLD);
        perform public.consume_sales_invoice_inventory(NEW);
      else
        raise notice 'handle_sales_invoice_change: both posted without item changes, no inventory change';
      end if;
    elsif v_old_posted and not v_new_posted then
      -- Changed from posted to non-posted: restore inventory
      raise notice 'handle_sales_invoice_change: changed to non-posted, restore only';
      perform public.restore_sales_invoice_inventory(OLD);
    elsif not v_old_posted and v_new_posted then
      -- Changed from non-posted to posted: consume inventory
      raise notice 'handle_sales_invoice_change: changed to posted, consume';
      perform public.consume_sales_invoice_inventory(NEW);
    else
      -- Both non-posted: no inventory change
      raise notice 'handle_sales_invoice_change: both non-posted, no inventory change';
    end if;

    -- JOURNAL ENTRY HANDLING (DELETE-based reversals, Zoho Books style)
    if v_old_posted and not v_new_posted then
      -- Confirmed/Paid → Draft/Sent: DELETE journal entry
      raise notice 'handle_sales_invoice_change: reverting to non-posted, deleting journal entry';
      delete from public.journal_entries
      where source_module = 'sales_invoices'
        and source_reference = OLD.invoice_number;

      -- Soft-delete associated payments
      raise notice 'handle_sales_invoice_change: reverting to non-posted, soft-deleting payments';
      update public.sales_payments
      set deleted_at = now()
      where invoice_id = OLD.id
        and deleted_at is null;

    elsif not v_old_posted and v_new_posted then
      -- Draft/Sent → Confirmed: CREATE journal entry
      raise notice 'handle_sales_invoice_change: changing to posted, creating journal entry';
      perform public.create_sales_invoice_journal_entry(NEW);

    elsif v_old_posted and v_new_posted then
      -- Both posted: delete old, create new (amounts might have changed)
      raise notice 'handle_sales_invoice_change: both posted, recreating journal entry';
      delete from public.journal_entries
      where source_module = 'sales_invoices'
        and source_reference = OLD.invoice_number;
      perform public.create_sales_invoice_journal_entry(NEW);
    else
      -- Both non-posted: no journal entry action
      raise notice 'handle_sales_invoice_change: both non-posted, no journal entry action';
    end if;

    perform public.recalculate_sales_invoice_payments(NEW.id);
    -- SYNC: Update linked trabajo with invoice changes
    perform public.sync_invoice_items_to_job(NEW.id);
    perform public.sync_invoice_status_to_job(NEW.id);
    return NEW;

  elsif TG_OP = 'DELETE' then
    v_old_status := lower(coalesce(OLD.status, 'draft'));
    raise notice '🔵 handle_sales_invoice_change: DELETE invoice %, status %', OLD.id, v_old_status;

    -- If was posted, restore inventory
    if not (v_old_status = any (v_non_posted)) then
      perform public.restore_sales_invoice_inventory(OLD);
    end if;

    -- DELETE invoice journal entry (using invoice_number as reference)
    delete from public.journal_entries
    where source_module = 'sales_invoices'
      and source_reference = OLD.invoice_number;

    -- DELETE all payment journal entries for this invoice
    delete from public.journal_entries
    where source_module = 'sales_payments'
      and source_reference in (
        select sp.id::text
          from public.sales_payments sp
         where sp.invoice_id = OLD.id
      );

    raise notice '🔵 handle_sales_invoice_change: DELETE completed, now cascade trigger should fire';
    return OLD;
  end if;

  return NULL;
end;
$$;

do $$
begin
  -- Drop and recreate trigger to ensure it uses latest function
  drop trigger if exists trg_sales_invoices_change on public.sales_invoices;

  create trigger trg_sales_invoices_change
    after insert or update or delete on public.sales_invoices
    for each row execute procedure public.handle_sales_invoice_change();

  raise notice 'Trigger trg_sales_invoices_change created successfully';
exception
  when others then
    raise notice 'Error creating trigger: %', SQLERRM;
end $$;

create or replace function public.handle_sales_payment_change()
returns trigger as $$
begin
  if TG_OP = 'INSERT' then
    perform public.recalculate_sales_invoice_payments(NEW.invoice_id);
    perform public.create_sales_payment_journal_entry(NEW);
    return NEW;
  elsif TG_OP = 'UPDATE' then
    if NEW.invoice_id is distinct from OLD.invoice_id then
      perform public.recalculate_sales_invoice_payments(OLD.invoice_id);
    end if;
    perform public.delete_sales_payment_journal_entry(OLD.id);
    perform public.recalculate_sales_invoice_payments(NEW.invoice_id);
    perform public.create_sales_payment_journal_entry(NEW);
    return NEW;
  elsif TG_OP = 'DELETE' then
    perform public.delete_sales_payment_journal_entry(OLD.id);
    perform public.recalculate_sales_invoice_payments(OLD.invoice_id);
    return OLD;
  end if;
  return NULL;
end;
$$ language plpgsql;

do $$
begin
  if not exists (
    select 1
      from pg_trigger t
      join pg_class c on c.oid = t.tgrelid
      join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public'
       and c.relname = 'sales_payments'
       and t.tgname = 'trg_sales_payments_change'
  ) then
    create trigger trg_sales_payments_change
      after insert or update or delete on public.sales_payments
      for each row execute procedure public.handle_sales_payment_change();
  end if;
end $$;

