create index if not exists idx_bike_observations_tenant on bike_observations(tenant_id);
create index if not exists idx_bike_observations_bike on bike_observations(bike_id, observed_at desc, created_at desc);
create index if not exists idx_bike_observations_job on bike_observations(job_id) where job_id is not null;
create index if not exists idx_bike_observations_job_bike on bike_observations(job_bike_id) where job_bike_id is not null;
create index if not exists idx_bike_observations_item on bike_observations(mechanic_job_item_id) where mechanic_job_item_id is not null;
create index if not exists idx_bike_observations_lifecycle on bike_observations(lifecycle_id) where lifecycle_id is not null;
create index if not exists idx_bike_observations_system on bike_observations(bike_id, system_key, location_key, observed_at desc);
create index if not exists idx_bike_observations_slot on bike_observations(bike_id, component_slot_key, location_key, observed_at desc) where component_slot_key is not null;
create index if not exists idx_bike_observations_key on bike_observations(observation_key);

alter table bike_observations enable row level security;

-- Table: bike_interventions
-- Historical actions that changed bike state or component lifecycle
create table if not exists bike_interventions (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade not null,
  bike_id uuid references bikes(id) on delete cascade not null,
  job_id uuid,
  job_bike_id uuid,
  mechanic_job_item_id uuid,
  product_id uuid references products(id) on delete set null,
  service_product_id uuid references products(id) on delete set null,
  from_lifecycle_id uuid references bike_component_lifecycles(id) on delete set null,
  to_lifecycle_id uuid references bike_component_lifecycles(id) on delete set null,
  system_key text not null,
  component_slot_key text,
  location_key text not null default 'none'
    check (location_key in ('none', 'front', 'rear', 'left', 'right', 'center')),
  intervention_type text not null
    check (intervention_type in ('replacement', 'service', 'adjustment', 'installation', 'removal', 'inspection')),
  title text not null,
  summary text,
  performed_at timestamp with time zone not null default now(),
  source text not null default 'manual',
  payload jsonb not null default '{}'::jsonb,
  created_by uuid references auth.users(id) default auth.uid(),
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now()
);

create index if not exists idx_bike_interventions_tenant on bike_interventions(tenant_id);
create index if not exists idx_bike_interventions_bike on bike_interventions(bike_id, performed_at desc, created_at desc);
create index if not exists idx_bike_interventions_job on bike_interventions(job_id) where job_id is not null;
create index if not exists idx_bike_interventions_job_bike on bike_interventions(job_bike_id) where job_bike_id is not null;
create index if not exists idx_bike_interventions_item on bike_interventions(mechanic_job_item_id) where mechanic_job_item_id is not null;
create index if not exists idx_bike_interventions_system on bike_interventions(bike_id, system_key, location_key, performed_at desc);
create index if not exists idx_bike_interventions_slot on bike_interventions(bike_id, component_slot_key, location_key, performed_at desc) where component_slot_key is not null;
create index if not exists idx_bike_interventions_from_lifecycle on bike_interventions(from_lifecycle_id) where from_lifecycle_id is not null;
create index if not exists idx_bike_interventions_to_lifecycle on bike_interventions(to_lifecycle_id) where to_lifecycle_id is not null;

alter table bike_interventions enable row level security;

-- Table: service_packages
-- Predefined service templates (e.g., "Basic Tune-up", "Full Overhaul")
create table if not exists service_packages (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade not null,
  name text not null,
  description text,
  estimated_duration_hours numeric(5,2) not null default 1,
  base_labor_cost numeric(12,2) not null default 0,
  items jsonb not null default '[]'::jsonb, -- Array of {product_id, quantity, description}
  is_active boolean not null default true,
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  unique(tenant_id, name) -- Each tenant has their own service packages
);

do $$ begin
  create index if not exists idx_service_packages_tenant on service_packages(tenant_id);
  create index if not exists idx_service_packages_name on service_packages using gin (to_tsvector('spanish', coalesce(name, '')));
exception
  when undefined_table then raise notice '⚠ Table service_packages does not exist';
  when undefined_column then raise notice '⚠ Column tenant_id does not exist in service_packages';
end $$;

-- Table: mechanic_jobs (trabajos)
-- Main table for tracking service jobs/work orders
-- NOTE: This must exist BEFORE the table default uses it (fresh bootstrap safety).
create sequence if not exists public.mechanic_job_number_seq
  start with 1
  increment by 1
  no cycle;

create or replace function public.generate_mechanic_job_number()
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_next_number integer;
begin
  v_next_number := nextval('public.mechanic_job_number_seq');
  return 'PG-' || lpad(v_next_number::text, 5, '0');
end;
$$;

create table if not exists mechanic_jobs (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade not null,
  job_number text not null unique default public.generate_mechanic_job_number(), -- Auto-generated: PG-00001
  customer_id uuid not null references customers(id) on delete cascade,
  bike_id uuid not null references bikes(id) on delete cascade,
  service_package_id uuid references service_packages(id) on delete set null,

  -- Dates and timeline
  arrival_date timestamp with time zone not null default now(),
  deadline timestamp with time zone,
  diagnostic_deadline timestamp with time zone,
  diagnostic_sent_at timestamp with time zone,
  started_at timestamp with time zone,
  completed_at timestamp with time zone,
  delivered_at timestamp with time zone,

  -- Status and priority
  -- NOTE: status CHECK constraint removed (Oct 2025) to support flexible job_statuses system
  -- Valid statuses are now managed via job_statuses table (Notion-style custom statuses)
  status text not null default 'PENDIENTE',
  priority text not null default 'NORMAL'
    check (priority in ('URGENTE','ALTA','NORMAL','BAJA')),

  -- Job details
  client_request text, -- What the client reported
  diagnosis text, -- Mechanic's diagnosis
  work_performed text, -- What was actually done
  notes text, -- Internal notes

  -- Assignment
  assigned_to uuid references customers(id) on delete set null, -- Will be employee_id when HR module exists
  assigned_technician_name text, -- Temporary until employees table exists

  -- Costs and invoicing
  estimated_cost numeric(12,2) not null default 0,
  final_cost numeric(12,2) not null default 0,
  parts_cost numeric(12,2) not null default 0,
  labor_cost numeric(12,2) not null default 0,
  discount_amount numeric(12,2) not null default 0,
  tax_amount numeric(12,2) not null default 0,
  total_cost numeric(12,2) not null default 0,

  -- Invoicing
  invoice_id uuid references sales_invoices(id) on delete restrict,
  is_invoiced boolean not null default false,
  is_paid boolean not null default false,

  -- Warranty
  is_warranty_job boolean not null default false,
  warranty_notes text,

  -- Customer approval
  requires_approval boolean not null default false,
  approved_by_customer boolean not null default false,
  approved_at timestamp with time zone,

  -- Images and attachments
  image_urls text[] not null default array[]::text[],

  -- Soft delete
  deleted_at timestamp with time zone,
  deleted_by uuid references auth.users(id) on delete set null,

  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now()
);

-- Keep the canonical snapshot compatible with databases created before the
-- diagnostic timeline fields were introduced by the historical standalone
-- migration `20260207_add_diagnostic_deadline.sql`.
alter table mechanic_jobs
  add column if not exists diagnostic_deadline timestamp with time zone,
  add column if not exists diagnostic_sent_at timestamp with time zone;

-- Status backbone: mechanic_jobs.status_id (FK to job_statuses)
alter table mechanic_jobs add column if not exists status_id uuid;

do $$ begin
  if not exists (
    select 1
      from information_schema.table_constraints
     where constraint_name = 'mechanic_jobs_status_id_fkey'
  ) then
    alter table mechanic_jobs add constraint mechanic_jobs_status_id_fkey
      foreign key (tenant_id, status_id) references job_statuses(tenant_id, id) on delete set null;
  end if;
exception
  when others then raise notice '⚠️ mechanic_jobs.status_id FK: %', sqlerrm;
end $$;

create index if not exists idx_mechanic_jobs_status_id on mechanic_jobs(status_id);

-- Add tax_treatment column to mechanic_jobs
alter table mechanic_jobs
  add column if not exists tax_treatment text not null default 'no_tax'
  check (tax_treatment in ('no_tax', 'tax_included'));

comment on column mechanic_jobs.tax_treatment is
  'Tax treatment for the invoice created from this job. no_tax = no IVA, tax_included = 19% IVA included';

