        gen_random_uuid(),
        p_tenant_id,
        'footer',
        'Inicio',
        'page',
        '/tienda',
        false,
        v_links_parent_id,
        0,
        true,
        true,
        true
      ),
      (
        gen_random_uuid(),
        p_tenant_id,
        'footer',
        'Productos',
        'page',
        '/productos',
        false,
        v_links_parent_id,
        1,
        true,
        true,
        true
