-- Global smart tasks realtime sync for the right-toolbar tasks panel.
do $$
begin
  if to_regclass('public.smart_tasks') is not null then
    alter table public.smart_tasks replica identity full;

    if exists (
      select 1
      from pg_publication
      where pubname = 'supabase_realtime'
    ) and not exists (
      select 1
      from pg_publication_tables
      where pubname = 'supabase_realtime'
        and schemaname = 'public'
        and tablename = 'smart_tasks'
    ) then
      alter publication supabase_realtime add table public.smart_tasks;
    end if;
  end if;
end $$;

create or replace function public.create_online_order_erp_notification()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_body text;
begin
  v_body := coalesce(nullif(NEW.order_number, ''), 'Pedido web')
    || ' · '
    || coalesce(nullif(NEW.customer_name, ''), 'Cliente');

  if coalesce(NEW.total, 0) > 0 then
    v_body := v_body || ' · $' || trim(to_char(NEW.total, 'FM999G999G999G990'));
  end if;

  insert into public.erp_notifications (
    tenant_id,
    type,
    title,
    body,
    route,
    entity_type,
    entity_id,
    severity,
    data
  ) values (
    NEW.tenant_id,
    'online_order_created',
    'Nueva venta online',
    v_body,
    '/website/orders?order=' || NEW.id::text,
    'online_order',
    NEW.id,
    'success',
    jsonb_build_object(
      'order_id', NEW.id,
      'order_number', NEW.order_number,
      'customer_name', NEW.customer_name,
      'total', NEW.total,
      'payment_status', NEW.payment_status,
      'delivery_type', NEW.delivery_type
    )
  ) on conflict (tenant_id, type, entity_type, entity_id) do update
    set title = excluded.title,
        body = excluded.body,
        route = excluded.route,
        severity = excluded.severity,
        data = excluded.data,
        read_at = null,
        updated_at = now();

  return NEW;
end;
$$;

drop trigger if exists trg_online_order_erp_notification on online_orders;
create trigger trg_online_order_erp_notification
  after insert on online_orders
  for each row execute function public.create_online_order_erp_notification();

-- ============================================================
-- Shared helper: resolve a human-readable actor name from a user id.
-- Prefers the linked employee (trabajador) name, then auth metadata,
-- then email. SECURITY DEFINER so triggers can read auth.users.
-- ============================================================
create or replace function public.erp_actor_display_name(
  p_user_id uuid,
  p_tenant_id uuid
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text;
begin
  if p_user_id is null then
    return null;
  end if;

  -- Prefer the linked employee (trabajador) full name.
  select nullif(trim(coalesce(e.first_name, '') || ' ' || coalesce(e.last_name, '')), '')
    into v_name
  from public.user_profiles up
  join public.employees e on e.id = up.employee_id
  where up.user_id = p_user_id
    and up.tenant_id = p_tenant_id
  limit 1;

  if v_name is not null then
    return v_name;
  end if;

  -- Fallback to auth user metadata or email.
  select nullif(
           coalesce(
             u.raw_user_meta_data->>'full_name',
             u.raw_user_meta_data->>'name',
             u.email
           ), '')
    into v_name
  from auth.users u
  where u.id = p_user_id
  limit 1;

  return v_name;
end;
$$;

grant execute on function public.erp_actor_display_name(uuid, uuid) to authenticated;

-- ============================================================
-- Notification source: new workshop job (trabajo)
-- ============================================================
create or replace function public.create_mechanic_job_erp_notification()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_customer_name text;
  v_bike_label text;
  v_client_request text;
  v_body text;
begin
  -- Skip soft-deleted rows
  if NEW.deleted_at is not null then
    return NEW;
  end if;

  select name into v_customer_name
  from public.customers
  where id = NEW.customer_id;

  select nullif(trim(
           coalesce(b.brand, '') || ' ' || coalesce(b.model, '')
           || case
                when nullif(trim(coalesce(b.color, '')), '') is not null
                  then ' · ' || b.color
                else ''
              end
         ), '')
    into v_bike_label
  from public.bikes b
  where b.id = NEW.bike_id;

  v_client_request := nullif(left(coalesce(NEW.client_request, ''), 300), '');

  v_body := coalesce(nullif(NEW.job_number, ''), 'Trabajo')
    || ' · '
    || coalesce(nullif(v_customer_name, ''), 'Cliente');

  insert into public.erp_notifications (
    tenant_id,
    type,
    title,
    body,
    route,
    entity_type,
    entity_id,
    severity,
    data
  ) values (
    NEW.tenant_id,
    'mechanic_job_created',
    'Nuevo trabajo',
    v_body,
    '/taller/pegas?job=' || NEW.id::text,
    'mechanic_job',
    NEW.id,
    'info',
    jsonb_build_object(
      'job_id', NEW.id,
      'job_number', NEW.job_number,
      'customer_id', NEW.customer_id,
      'customer_name', v_customer_name,
      'bike_id', NEW.bike_id,
      'bike_label', v_bike_label,
      'client_request', v_client_request,
      'priority', NEW.priority,
      'status', NEW.status
    )
  ) on conflict (tenant_id, type, entity_type, entity_id) do nothing;

  return NEW;
end;
$$;

drop trigger if exists trg_mechanic_job_erp_notification on mechanic_jobs;
create trigger trg_mechanic_job_erp_notification
  after insert on mechanic_jobs
  for each row execute function public.create_mechanic_job_erp_notification();

-- ============================================================
-- Notification source: new sales payment received
-- ============================================================
create or replace function public.create_sales_payment_erp_notification()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_body text;
  v_payment_method text;
  v_customer_name text;
  v_recorded_by text;
begin
  -- Skip soft-deleted rows
  if NEW.deleted_at is not null then
    return NEW;
  end if;

  if TG_OP = 'UPDATE' and NEW.date is not distinct from OLD.date then
    return NEW;
  end if;

  select name into v_payment_method
  from public.payment_methods
  where tenant_id = NEW.tenant_id
    and id = NEW.payment_method_id;

  select customer_name into v_customer_name
  from public.sales_invoices
  where id = NEW.invoice_id;

  v_recorded_by := public.erp_actor_display_name(auth.uid(), NEW.tenant_id);

  v_body := coalesce(nullif(NEW.invoice_reference, ''), 'Pago');

  if coalesce(NEW.amount, 0) > 0 then
    v_body := v_body || ' · $' || trim(to_char(NEW.amount, 'FM999G999G999G990'));
  end if;

  insert into public.erp_notifications as existing (
    tenant_id,
    type,
    title,
    body,
    route,
    entity_type,
    entity_id,
    severity,
    data,
    occurred_at
  ) values (
    NEW.tenant_id,
    'sales_payment_received',
    'Nuevo pago recibido',
    v_body,
    '/sales/payments',
    'sales_payment',
    NEW.id,
    'success',
    jsonb_build_object(
      'payment_id', NEW.id,
      'invoice_id', NEW.invoice_id,
      'invoice_reference', NEW.invoice_reference,
      'amount', NEW.amount,
      'payment_method', v_payment_method,
      'customer_name', v_customer_name,
      'recorded_by_name', v_recorded_by,
      'recorded_at', NEW.created_at,
      'payment_date', NEW.date,
      'reference', NEW.reference
    ),
    NEW.date
  ) on conflict (tenant_id, type, entity_type, entity_id) do update
    set occurred_at = excluded.occurred_at,
        data = existing.data
          || jsonb_build_object('payment_date', NEW.date);

  return NEW;
end;
$$;

revoke all on function public.create_sales_payment_erp_notification()
  from public, anon, authenticated, service_role;

drop trigger if exists trg_sales_payment_erp_notification on sales_payments;
create trigger trg_sales_payment_erp_notification
  after insert or update of date on sales_payments
  for each row execute function public.create_sales_payment_erp_notification();

-- ============================================================
-- Notification source: new expense recorded
-- ============================================================
create or replace function public.create_expense_erp_notification()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_body text;
  v_category_name text;
  v_payment_method text;
  v_recorded_by text;
  v_supplier_name text;
begin
  -- Legacy imports may still contain rows without a tenant. Notification
  -- persistence must never make those compatibility writes fail.
  if NEW.tenant_id is null then
    return NEW;
  end if;

  if TG_OP = 'UPDATE'
     and NEW.issue_date is not distinct from OLD.issue_date then
    return NEW;
  end if;

  select name
    into v_category_name
  from public.expense_categories
  where tenant_id = NEW.tenant_id
    and id = NEW.category_id;

  select name
    into v_payment_method
  from public.payment_methods
  where tenant_id = NEW.tenant_id
    and id = NEW.payment_method_id;

  v_recorded_by := public.erp_actor_display_name(
    coalesce(NEW.created_by, auth.uid()),
    NEW.tenant_id
  );
  v_supplier_name := coalesce(
    nullif(trim(NEW.supplier_name), ''),
    'Proveedor no informado'
  );
  v_body := coalesce(nullif(trim(NEW.expense_number), ''), 'Gasto')
    || ' · '
    || v_supplier_name;

  if coalesce(NEW.total_amount, 0) > 0 then
    v_body := v_body
      || ' · $'
      || trim(to_char(NEW.total_amount, 'FM999G999G999G990'));
  end if;

  insert into public.erp_notifications as existing (
    tenant_id,
    type,
    title,
    body,
    route,
    entity_type,
    entity_id,
    severity,
    data,
    occurred_at
  ) values (
    NEW.tenant_id,
    'expense_recorded',
    'Nuevo gasto registrado',
    v_body,
    '/accounting/expenses/' || NEW.id::text,
    'expense',
    NEW.id,
    'info',
    jsonb_build_object(
      'expense_id', NEW.id,
      'expense_number', NEW.expense_number,
      'supplier_id', NEW.supplier_id,
      'supplier_name', NEW.supplier_name,
      'supplier_rut', NEW.supplier_rut,
      'document_type', NEW.document_type,
      'document_number', NEW.document_number,
      'issue_date', NEW.issue_date,
      'subtotal', NEW.subtotal,
      'tax_amount', NEW.tax_amount,
      'total_amount', NEW.total_amount,
      'currency', NEW.currency,
      'posting_status', NEW.posting_status,
      'payment_status', NEW.payment_status,
      'payment_method', v_payment_method,
      'category_name', v_category_name,
      'recorded_by_name', v_recorded_by,
      'recorded_at', NEW.created_at
    ),
    NEW.issue_date
  ) on conflict (tenant_id, type, entity_type, entity_id) do update
    set occurred_at = excluded.occurred_at,
        data = existing.data
          || jsonb_build_object('issue_date', NEW.issue_date);

  return NEW;
end;
$$;

revoke all on function public.create_expense_erp_notification()
  from public, anon, authenticated, service_role;

drop trigger if exists trg_expense_erp_notification on public.expenses;
create trigger trg_expense_erp_notification
  after insert or update of issue_date on public.expenses
  for each row execute function public.create_expense_erp_notification();

-- ============================================================
-- Notification source: WhatsApp catalog product approved (customer-visible)
-- Fires only when status transitions INTO 'customer_visible'.
-- ============================================================
-- The canonical snapshot composes notification and catalog migrations. Ensure
-- trigger-referenced product columns exist before creating the trigger.
alter table public.products
  add column if not exists whatsapp_catalog_sync_status text not null default 'not_synced',
  add column if not exists whatsapp_catalog_title text;

create or replace function public.create_whatsapp_catalog_erp_notification()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text;
  v_body text;
begin
  if NEW.whatsapp_catalog_sync_status is distinct from 'customer_visible' then
    return NEW;
  end if;

  if OLD.whatsapp_catalog_sync_status is not distinct from 'customer_visible' then
    return NEW;
  end if;

  v_name := coalesce(
    nullif(NEW.whatsapp_catalog_title, ''),
    nullif(NEW.name, ''),
    'Producto'
  );

  v_body := v_name || ' ya es visible en el catálogo de WhatsApp';

  insert into public.erp_notifications (
    tenant_id,
    type,
    title,
    body,
    route,
    entity_type,
    entity_id,
    severity,
    data
  ) values (
    NEW.tenant_id,
    'whatsapp_catalog_approved',
    'Producto aprobado en WhatsApp',
    v_body,
    '/inventory/products?product=' || NEW.id::text,
    'product',
    NEW.id,
    'success',
    jsonb_build_object(
      'product_id', NEW.id,
      'product_name', v_name,
      'sku', NEW.sku
    )
  ) on conflict (tenant_id, type, entity_type, entity_id) do update
    set title = excluded.title,
        body = excluded.body,
        route = excluded.route,
        severity = excluded.severity,
        data = excluded.data,
        read_at = null,
        updated_at = now();

  return NEW;
end;
$$;

drop trigger if exists trg_whatsapp_catalog_erp_notification on products;
create trigger trg_whatsapp_catalog_erp_notification
  after update of whatsapp_catalog_sync_status on products
  for each row execute function public.create_whatsapp_catalog_erp_notification();

