-- Update status constraint to include ready_for_pickup
do $$
begin
  alter table online_orders drop constraint if exists online_orders_status_check;
  alter table online_orders add constraint online_orders_status_check
    check (status in ('pending', 'confirmed', 'processing', 'ready_for_pickup', 'shipped', 'delivered', 'cancelled'));
exception when others then
  raise notice 'Could not update online_orders status constraint: %', sqlerrm;
end $$;

-- ============================================================================
-- FUNCTIONS FOR ONLINE ORDER PROCESSING
-- ============================================================================

-- Function to automatically create sales invoice from online order
-- This function handles different payment methods with different tax treatments:
--
-- MERCADOPAGO/CARD:
--   - tax_treatment = 'tax_included' (IVA 19%)
--   - invoice_status = 'paid' (if payment confirmed) or 'confirmed' (if pending)
--   - Creates payment record automatically
--   - Triggers inventory deduction + journal entry
--
-- WIRE TRANSFER/CASH:
--   - tax_treatment = 'no_tax' (no IVA on informal sales)
--   - invoice_status = 'sent' (pending manual confirmation)
--   - NO payment record (user confirms manually in ERP)
--   - Inventory NOT deducted until confirmed
create or replace function public.process_online_order(p_order_id uuid)
returns uuid -- Returns sales_invoice_id
language plpgsql
security definer
set search_path = public
as $$
declare
  v_order record;
  v_invoice_id uuid;
  v_invoice_number text;
  v_items jsonb;
  v_next_number integer;
  v_year text;
  v_payment_method record;
  v_tenant_id uuid;
  v_net_amount numeric(12,2);
  v_iva_amount numeric(12,2);
  v_tax_treatment text;
  v_invoice_status text;
  v_should_create_payment boolean;
  v_invoice_date timestamp with time zone;
begin
  -- Get order details WITH ROW LOCK to prevent race conditions
  -- This ensures only one process can create an invoice for this order
  select * into v_order
  from online_orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'Order not found: %', p_order_id;
  end if;

  -- CRITICAL: Get tenant_id from the order
  v_tenant_id := v_order.tenant_id;
  if v_tenant_id is null then
    raise exception 'Order has no tenant_id: %', p_order_id;
  end if;

  -- Check if invoice already exists
  if v_order.sales_invoice_id is not null then
    -- Invoice exists - check if we need to update it to 'paid' status
    -- This handles the case where webhook arrives after invoice was created
    if v_order.payment_status = 'paid' then
      -- Get payment method for creating payment record
      select * into v_payment_method
      from payment_methods
      where tenant_id = v_tenant_id
        and lower(code) = lower(coalesce(v_order.payment_method, 'mercadopago'))
        and is_active = true
      limit 1;

      -- If payment method not found, try fallback
      if v_payment_method is null then
        select * into v_payment_method
        from payment_methods
        where tenant_id = v_tenant_id
          and is_active = true
        order by sort_order
        limit 1;
      end if;

      -- Check if invoice is not already paid
      perform 1 from sales_invoices
      where id = v_order.sales_invoice_id
        and status != 'paid';

      if found then
        -- Update invoice to paid status
        update sales_invoices
        set status = 'paid',
            paid_amount = total,
            balance = 0,
            updated_at = now()
        where id = v_order.sales_invoice_id;

        -- Create payment record if not exists
        if not exists (
          select 1 from sales_payments
          where invoice_id = v_order.sales_invoice_id
        ) and v_payment_method.id is not null then
          insert into sales_payments (
            tenant_id,
            invoice_id,
            invoice_reference,
            payment_method_id,
            amount,
            date,
            reference,
            notes
          ) values (
            v_tenant_id,
            v_order.sales_invoice_id,
            (select invoice_number from sales_invoices where id = v_order.sales_invoice_id),
            v_payment_method.id,
            v_order.total,
            coalesce(v_order.paid_at, now()),
            v_order.payment_reference,
            'Pago automático - Pedido online #' || v_order.order_number ||
            ' (' || coalesce(v_payment_method.name, v_order.payment_method) || ')'
          );

          raise notice 'Created payment record for existing invoice (order: %)', v_order.order_number;
        end if;

        raise notice 'Updated existing invoice to paid status (order: %)', v_order.order_number;
      end if;
    end if;

    return v_order.sales_invoice_id;
  end if;

  -- Get payment method configuration
  select * into v_payment_method
  from payment_methods
  where tenant_id = v_tenant_id
    and lower(code) = lower(coalesce(v_order.payment_method, 'mercadopago'))
    and is_active = true
  limit 1;

  -- If payment method not found, try fallback
  if v_payment_method is null then
    select * into v_payment_method
    from payment_methods
    where tenant_id = v_tenant_id
      and is_active = true
    order by sort_order
    limit 1;
  end if;

  -- ============================================================================
  -- DETERMINE TAX TREATMENT BASED ON PAYMENT METHOD
  -- ============================================================================
  -- MercadoPago/Card = tax_included (IVA 19%)
  -- Transfer/Cash = no_tax (use tax_amount from order, which frontend sets to 0)
  -- ============================================================================
  if v_order.tax_amount > 0 then
    v_tax_treatment := 'tax_included';
    -- Calculate IVA: net = total / 1.19, iva = total - net
    v_net_amount := round(v_order.total / 1.19, 2);
    v_iva_amount := round(v_order.total - v_net_amount, 2);
  else
    -- Transfer, cash, check = no tax
    v_tax_treatment := 'no_tax';
    v_net_amount := v_order.subtotal;
    v_iva_amount := 0;
  end if;

  -- ============================================================================
  -- DETERMINE INVOICE STATUS BASED ON PAYMENT METHOD + STATUS
  -- ============================================================================
  -- MercadoPago + paid = 'paid' (fully processed)
  -- MercadoPago + pending = 'confirmed' (waiting for webhook)
  -- Transfer = 'sent' (waiting for manual bank confirmation)
  -- Cash on delivery = 'sent' (waiting for delivery confirmation)
  -- ============================================================================
  if v_order.payment_status = 'paid' then
    v_invoice_status := 'paid';
    v_should_create_payment := true;
  elsif lower(v_order.payment_method) = 'mercadopago' and v_order.payment_status = 'pending' then
    v_invoice_status := 'confirmed';
    v_should_create_payment := false;
  else
    -- Transfer, cash on delivery, or unknown = sent (pending)
    v_invoice_status := 'sent';
    v_should_create_payment := false;
  end if;

  v_invoice_date := case
    when v_order.payment_status = 'paid' then
      coalesce(v_order.paid_at, v_order.created_at, now())
    else
      coalesce(v_order.created_at, now())
  end;

  -- Generate invoice number PER TENANT in format: INV-25-00001
  v_year := to_char(v_invoice_date, 'YY');

  perform pg_advisory_xact_lock(hashtextextended(
    'online_order_invoice_number:' || v_tenant_id::text || ':' || v_year,
    0
  ));

  select coalesce(max(cast(substring(invoice_number from '\d+$') as integer)), 0) + 1
  into v_next_number
  from sales_invoices
  where tenant_id = v_tenant_id
    and invoice_number ~ ('^INV-' || v_year || '-\d+$');

  v_invoice_number := 'INV-' || v_year || '-' || lpad(
    v_next_number::text,
    greatest(5, length(v_next_number::text)),
    '0'
  );

  -- Build items JSONB array from order items
  select jsonb_agg(
    jsonb_build_object(
      'product_id', oi.product_id,
      'product_name', oi.product_name,
      'product_sku', oi.product_sku,
      'quantity', oi.quantity,
      'price', oi.unit_price,
      'subtotal', oi.subtotal,
      'cost', oi.unit_cost,
      'tax_rate', oi.tax_rate,
      'is_service', oi.is_service,
      'purchase_treatment', oi.purchase_treatment,
      'product_type', oi.product_type
    ) order by oi.created_at, oi.id
  ) into v_items
  from online_order_items oi
  where oi.order_id = p_order_id
    and oi.tenant_id = v_tenant_id;

  -- Default to empty array if no items
  if v_items is null then
    v_items := '[]'::jsonb;
  end if;

  -- Create sales invoice WITH tenant_id
  -- Only 'paid' status triggers inventory deduction + journal entry
  insert into sales_invoices (
    tenant_id,
    invoice_number,
    customer_id,
    customer_name,
    date,
    due_date,
    status,
    tax_treatment,
    net_amount,
    subtotal,
    iva_amount,
    total,
    paid_amount,
    balance,
    items,
    reference,
    source
  ) values (
    v_tenant_id,
    v_invoice_number,
    v_order.customer_id,
    v_order.customer_name,
    v_invoice_date,
    v_invoice_date + interval '30 days',
    v_invoice_status,
    v_tax_treatment,
    v_net_amount,
    v_order.subtotal,
    v_iva_amount,
    v_order.total,
    case when v_should_create_payment then v_order.total else 0 end,
    case when v_should_create_payment then 0 else v_order.total end,
    v_items,
    'Pedido online #' || v_order.order_number ||
    case
      when v_order.delivery_type = 'pickup' then ' (Retiro en tienda)'
      else ' (Envío)'
    end,
    'ecommerce'
  )
  returning id into v_invoice_id;

  raise notice 'Created invoice % (status: %, tax: %) for online order %',
    v_invoice_number, v_invoice_status, v_tax_treatment, v_order.order_number;

  -- ============================================================================
  -- CRITICAL: Directly call inventory and journal functions here
  -- The trigger handle_sales_invoice_change has pg_trigger_depth() > 1 check
  -- which blocks processing when called from within another trigger
  -- So we call these functions directly to ensure they run
  -- ============================================================================
  if v_invoice_status in ('paid', 'confirmed') then
    -- Need to fetch the full invoice record to pass to functions
    declare
      v_invoice_record sales_invoices%rowtype;
    begin
      select * into v_invoice_record from sales_invoices where id = v_invoice_id;

      -- Consume inventory (deduct stock)
      raise notice 'Calling consume_sales_invoice_inventory for invoice %', v_invoice_number;
      perform public.consume_sales_invoice_inventory(v_invoice_record);

      -- Create sale journal entry
      raise notice 'Calling create_sales_invoice_journal_entry for invoice %', v_invoice_number;
      perform public.create_sales_invoice_journal_entry(v_invoice_record);
    end;
  end if;

  -- Link invoice to order + update order status
  update online_orders
  set
    sales_invoice_id = v_invoice_id,
    status = case
      when status = 'pending' then 'confirmed'
      else status
    end
  where id = p_order_id
    and tenant_id = v_tenant_id;

  -- Create payment record ONLY if payment is confirmed
  if v_should_create_payment and v_payment_method.id is not null then
    insert into sales_payments (
      tenant_id,
      invoice_id,
      invoice_reference,
      payment_method_id,
      amount,
      date,
      reference,
      notes
    ) values (
      v_tenant_id,
      v_invoice_id,
      v_invoice_number,
      v_payment_method.id,
      v_order.total,
      coalesce(v_order.paid_at, v_invoice_date),
      v_order.payment_reference,
      'Pago automático - Pedido online #' || v_order.order_number ||
      ' (' || coalesce(v_payment_method.name, v_order.payment_method) || ')'
    );

    raise notice 'Created payment record for invoice % (method: %)',
      v_invoice_number, v_payment_method.name;
  elsif not v_should_create_payment then
    raise notice 'Invoice % pending manual payment confirmation (method: %)',
      v_invoice_number, v_order.payment_method;
  end if;

  return v_invoice_id;
end;
$$;

--------------------------------------------------------------------------------
-- FUNCTION: cancel_online_order
-- PURPOSE: Cancel an online order, handle refunds, restore inventory
-- CALLED BY: ERP admin panel when cancelling/refunding orders
--------------------------------------------------------------------------------
create or replace function public.cancel_online_order(
  p_order_id uuid,
  p_reason text default 'Cancelado por el administrador',
  p_refund_amount numeric default null -- null = full refund, 0 = no refund
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_order record;
  v_invoice record;
  v_actual_refund numeric;
  v_result jsonb;
begin
  -- Get the order with tenant context
  select * into v_order
  from online_orders
  where id = p_order_id
    and tenant_id = public.user_tenant_id();

  if v_order is null then
    raise exception 'Order not found or access denied: %', p_order_id;
  end if;

  -- Check if already cancelled
  if v_order.status = 'cancelled' then
    raise exception 'Order is already cancelled';
  end if;

  -- Get associated invoice if exists
  if v_order.sales_invoice_id is not null then
    select * into v_invoice
    from sales_invoices
    where id = v_order.sales_invoice_id;
  end if;

  -- Determine refund amount
  if p_refund_amount is null then
    v_actual_refund := v_order.total;
  else
    v_actual_refund := least(p_refund_amount, v_order.total);
  end if;

  -- Start cancellation process
  -- 1. Cancel/delete the invoice (which will restore inventory and delete journal entries)
  if v_invoice is not null then
    -- If invoice is posted (confirmada/pagada), we need to revert it first
    if lower(coalesce(v_invoice.status, '')) in (
      'confirmed',
      'confirmado',
      'confirmada',
      'paid',
      'pagado',
      'pagada'
    ) then
      -- Delete payments first (triggers will handle journal entry reversal)
      delete from sales_payments where invoice_id = v_invoice.id;

      -- Set invoice back to draft (which triggers inventory restoration)
      update sales_invoices
      set status = 'draft',
          updated_at = now()
      where id = v_invoice.id;
    end if;

    -- Now delete the invoice
    delete from sales_invoices where id = v_invoice.id;

    raise notice 'Deleted invoice % and restored inventory', v_invoice.invoice_number;
  end if;

  -- 2. Update the order status
  update online_orders
  set
    status = 'cancelled',
    cancelled_at = now(),
    cancelled_reason = p_reason,
    refund_amount = v_actual_refund,
    refunded_at = case when v_actual_refund > 0 then now() else null end,
    sales_invoice_id = null, -- Clear invoice reference
    updated_at = now()
  where id = p_order_id;

  -- Build result
  v_result := jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'order_number', v_order.order_number,
    'status', 'cancelled',
    'refund_amount', v_actual_refund,
    'invoice_deleted', v_invoice is not null,
    'invoice_number', coalesce(v_invoice.invoice_number, null),
    'message', format('Order %s cancelled. Refund: $%s', v_order.order_number, v_actual_refund)
  );

  return v_result;
end;
$$;

--------------------------------------------------------------------------------
-- FUNCTION: confirm_online_order_payment
-- PURPOSE: Manually confirm wire transfer or other pending payments
-- CALLED BY: ERP admin panel when customer confirms bank transfer
-- This function:
-- 1. Updates invoice status to 'confirmed' (triggers inventory deduction)
-- 2. Creates payment record (triggers journal entry + updates invoice to paid)
-- 3. Updates order payment_status to 'paid'
--------------------------------------------------------------------------------
create or replace function public.confirm_online_order_payment(
  p_order_id uuid,
  p_payment_reference text default null,
  p_payment_date timestamp with time zone default now()
)
returns uuid -- Returns payment_id
language plpgsql
security definer
set search_path = public
as $$
declare
  v_order record;
  v_invoice record;
  v_payment_method_id uuid;
  v_payment_id uuid;
begin
  -- Get order with tenant context
  select * into v_order
  from online_orders
  where id = p_order_id
    and tenant_id = public.user_tenant_id();

  if not found then
    raise exception 'Order not found or access denied: %', p_order_id;
  end if;

  -- Check order has invoice
  if v_order.sales_invoice_id is null then
    raise exception 'Order has no invoice. Call process_online_order first.';
  end if;

  -- Get invoice
  select * into v_invoice
  from sales_invoices
  where id = v_order.sales_invoice_id;

  if not found then
    raise exception 'Invoice not found: %', v_order.sales_invoice_id;
  end if;

  -- Check invoice isn't already paid
  if v_invoice.status = 'paid' then
    raise notice 'Invoice already paid';
    return null;
  end if;

  -- Get payment method
  select id into v_payment_method_id
  from payment_methods
  where tenant_id = v_order.tenant_id
    and lower(code) = lower(coalesce(v_order.payment_method, 'transfer'))
    and is_active = true
  limit 1;

  -- Fallback to any transfer method
  if v_payment_method_id is null then
    select id into v_payment_method_id
    from payment_methods
    where tenant_id = v_order.tenant_id
      and lower(code) in ('transfer', 'transferencia', 'bank_transfer')
      and is_active = true
    limit 1;
  end if;

  if v_payment_method_id is null then
    raise exception 'No payment method found for tenant %', v_order.tenant_id;
  end if;

  -- Update invoice to confirmed (triggers inventory deduction if not already done)
  update sales_invoices
  set
    status = 'confirmed',
    updated_at = now()
  where id = v_invoice.id
    and status != 'paid'; -- Only update if not already paid

  -- Create payment record (triggers journal entry + updates invoice to paid)
  insert into sales_payments (
    tenant_id,
    invoice_id,
    invoice_reference,
    payment_method_id,
    amount,
    date,
    reference,
    notes
  ) values (
    v_order.tenant_id,
    v_invoice.id,
    v_invoice.invoice_number,
    v_payment_method_id,
    v_order.total,
    p_payment_date,
    p_payment_reference,
    'Confirmación manual - Transferencia bancaria - Pedido #' || v_order.order_number
  )
  returning id into v_payment_id;

  -- Update order payment status
  update online_orders
  set
    payment_status = 'paid',
    paid_at = p_payment_date,
    payment_reference = coalesce(p_payment_reference, payment_reference),
    updated_at = now()
  where id = p_order_id;

  raise notice 'Payment confirmed for order % (invoice %)',
    v_order.order_number, v_invoice.invoice_number;

  return v_payment_id;
end;
$$;

grant execute on function public.confirm_online_order_payment(uuid, text, timestamp with time zone) to authenticated;

--------------------------------------------------------------------------------
-- TRIGGER: Auto-create invoice for non-MercadoPago orders on creation
-- MercadoPago orders wait for webhook confirmation before invoice creation
--------------------------------------------------------------------------------
create or replace function public.handle_new_online_order()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if current_setting('app.public_order_rpc_in_progress', true) = 'true' then
    return NEW;
  end if;

  -- Only create invoice immediately for non-MercadoPago orders
  -- MercadoPago orders wait for webhook confirmation
  if lower(coalesce(NEW.payment_method, '')) not in ('mercadopago', 'mercado_pago') then
    -- Create invoice with 'sent' status (pending payment)
    perform public.process_online_order(NEW.id);
    raise notice 'Auto-created invoice for non-MercadoPago order %', NEW.order_number;
  else
    raise notice 'MercadoPago order % - invoice will be created on payment confirmation', NEW.order_number;
  end if;

  return NEW;
end;
$$;

-- Create trigger (replace if exists)
drop trigger if exists trg_online_order_auto_invoice on online_orders;
create trigger trg_online_order_auto_invoice
  after insert on online_orders
  for each row
  execute function public.handle_new_online_order();

--------------------------------------------------------------------------------
-- FUNCTION: update_online_order_status
-- PURPOSE: Update order status with proper business logic
-- CALLED BY: ERP admin panel for order management
--------------------------------------------------------------------------------
create or replace function public.update_online_order_status(
  p_order_id uuid,
  p_new_status text,
  p_tracking_number text default null,
  p_tracking_url text default null,
  p_carrier text default null,
  p_notes text default null
)
returns jsonb
language plpgsql
security definer
as $$
declare
  v_order record;
  v_invoice_id uuid;
begin
  -- Get current order
  select * into v_order
  from online_orders
  where id = p_order_id
    and tenant_id = public.user_tenant_id();

  if v_order is null then
    raise exception 'Order not found or access denied: %', p_order_id;
  end if;

  -- Validate status transition
  if v_order.status = 'cancelled' then
    raise exception 'Cannot change status of cancelled order';
  end if;

  -- Handle status-specific logic
  case p_new_status
    -- Order confirmed (usually after payment)
    when 'confirmed' then
      -- If no invoice yet, create one
      if v_order.sales_invoice_id is null and v_order.payment_status = 'paid' then
        v_invoice_id := public.process_online_order(p_order_id);
      end if;

    -- Processing (preparing order)
    when 'processing' then
      if v_order.sales_invoice_id is null then
        raise exception 'Cannot process order without invoice. Confirm order first.';
      end if;

    -- Ready for pickup (in-store pickup orders)
    when 'ready_for_pickup' then
      if v_order.delivery_type != 'pickup' then
        raise exception 'Can only mark pickup orders as ready_for_pickup';
      end if;
      update online_orders
      set ready_for_pickup_at = now()
      where id = p_order_id;

    -- Shipped
    when 'shipped' then
      if v_order.delivery_type != 'shipping' then
        raise exception 'Can only ship delivery orders, not pickup orders';
      end if;
      update online_orders
      set
        shipped_at = now(),
        tracking_number = coalesce(p_tracking_number, tracking_number),
        tracking_url = coalesce(p_tracking_url, tracking_url),
        shipping_carrier = coalesce(p_carrier, shipping_carrier)
      where id = p_order_id;

    -- Delivered
    when 'delivered' then
      update online_orders
      set delivered_at = now()
      where id = p_order_id;

    -- Cancelled
    when 'cancelled' then
      -- Use dedicated cancel function
      return public.cancel_online_order(p_order_id, coalesce(p_notes, 'Cancelado'));

    else
      raise exception 'Invalid status: %', p_new_status;
  end case;

  -- Update the status
  update online_orders
  set
    status = p_new_status,
    notes = coalesce(p_notes, notes),
    updated_at = now()
  where id = p_order_id;

  return jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'old_status', v_order.status,
    'new_status', p_new_status,
    'invoice_id', coalesce(v_invoice_id, v_order.sales_invoice_id)
  );
end;
$$;

--------------------------------------------------------------------------------
-- TRIGGER: auto_process_paid_online_order
-- PURPOSE: Automatically process order when payment is received
-- FLOW: Customer pays → webhook updates payment_status → trigger creates invoice
--       OR if invoice exists → updates invoice to 'paid' status
--------------------------------------------------------------------------------
create or replace function public.handle_online_order_payment()
returns trigger
language plpgsql
security definer
as $$
declare
  v_invoice_id uuid;
begin
  -- Only process when payment_status changes to 'paid'
  if NEW.payment_status = 'paid' and
     (OLD.payment_status is null or OLD.payment_status != 'paid') and
     NEW.status != 'cancelled' then

    -- Call process_online_order regardless of whether invoice exists
    -- If invoice exists, it will update it to 'paid' status
    -- If invoice doesn't exist, it will create one
    v_invoice_id := public.process_online_order(NEW.id);

    raise notice 'Auto-processed order % -> Invoice %', NEW.order_number, v_invoice_id;
  end if;

  return NEW;
end;
$$;

-- Create the trigger
do $$
begin
  -- Drop existing trigger if any
  drop trigger if exists trg_auto_process_paid_online_order on online_orders;

  -- Create new trigger (AFTER to allow the row to be committed first)
  create trigger trg_auto_process_paid_online_order
    after update of payment_status on online_orders
    for each row
    execute function public.handle_online_order_payment();

  raise notice 'Created trigger trg_auto_process_paid_online_order';
end $$;

-- Grant execute permissions
grant execute on function public.cancel_online_order(uuid, text, numeric) to authenticated;
grant execute on function public.update_online_order_status(uuid, text, text, text, text, text) to authenticated;

-- Tenant/year order numbers serialize on one advisory transaction lock.
create or replace function public.generate_online_order_number(
  p_tenant_id uuid,
  p_at timestamptz default clock_timestamp()
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_year text;
  v_next bigint;
begin
  if p_tenant_id is null or not exists (
    select 1 from public.tenants tenant where tenant.id = p_tenant_id
  ) then
    raise exception 'A valid tenant is required to generate an online order number'
      using errcode = '23503';
  end if;
  v_year := to_char(coalesce(p_at, clock_timestamp()), 'YY');
  perform pg_advisory_xact_lock(hashtextextended(
    'online_order_number:' || p_tenant_id::text || ':' || v_year,
    0
  ));
  select coalesce(max(
    substring(order_number from ('^WEB-' || v_year || '-([0-9]+)$'))::bigint
  ), 0) + 1
    into v_next
    from public.online_orders
   where tenant_id = p_tenant_id
     and order_number ~ ('^WEB-' || v_year || '-[0-9]+$');
  return 'WEB-' || v_year || '-' || lpad(
    v_next::text,
    greatest(5, length(v_next::text)),
    '0'
  );
end;
$$;

create or replace function public.generate_online_order_number()
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tenant_id uuid := public.user_tenant_id();
begin
  if v_tenant_id is null then
    raise exception 'Tenant context is required to generate an online order number'
      using errcode = '42501';
  end if;
  return public.generate_online_order_number(v_tenant_id, clock_timestamp());
end;
$$;

revoke all on function public.generate_online_order_number(uuid, timestamptz)
  from public, anon, authenticated, service_role;
revoke all on function public.generate_online_order_number()
  from public, anon, authenticated, service_role;

-- Trigger to auto-generate order number
create or replace function public.auto_generate_order_number()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if NEW.order_number is null or btrim(NEW.order_number) = '' then
    NEW.order_number := public.generate_online_order_number(
      NEW.tenant_id,
      coalesce(NEW.created_at, clock_timestamp())
    );
  end if;
  return NEW;
end;
$$;

revoke all on function public.auto_generate_order_number()
  from public, anon, authenticated, service_role;

drop trigger if exists trg_auto_generate_order_number on online_orders;
create trigger trg_auto_generate_order_number
  before insert on online_orders
  for each row execute procedure auto_generate_order_number();

-- Secure public checkout RPC: create orders from product IDs and quantities only.
-- Prices, names, SKU snapshots, totals, IVA, and stock checks are derived server-side.
create or replace function public.create_public_online_order(
  p_order_data jsonb,
  p_order_items jsonb
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tenant_id uuid;
  v_customer_id uuid;
  v_auth_uid uuid := auth.uid();
  v_customer_name text;
  v_customer_email text;
  v_customer_phone text;
  v_customer_address text;
  v_delivery_type text;
  v_payment_method text;
  v_order_id uuid;
  v_item jsonb;
  v_product_id uuid;
  v_quantity integer;
  v_product record;
  v_unit_price numeric(12,2);
  v_line_total numeric(12,2);
  v_total numeric(12,2) := 0;
  v_subtotal numeric(12,2) := 0;
  v_tax_amount numeric(12,2) := 0;
  v_customer_id_text text;
  v_checkout_key text;
  v_created_response jsonb;
begin
  if p_order_data is null or jsonb_typeof(p_order_data) <> 'object' then
    raise exception 'Invalid order payload';
  end if;

  if p_order_items is null or jsonb_typeof(p_order_items) <> 'array' or jsonb_array_length(p_order_items) = 0 then
    raise exception 'Order must include at least one item';
  end if;

  if jsonb_array_length(p_order_items) > 50 then
    raise exception 'Order item limit exceeded';
  end if;

  v_tenant_id := nullif(p_order_data->>'tenant_id', '')::uuid;
  if v_tenant_id is null or not exists (select 1 from tenants where id = v_tenant_id) then
    raise exception 'Invalid tenant_id';
  end if;

  v_customer_name := btrim(coalesce(p_order_data->>'customer_name', ''));
  v_customer_email := lower(btrim(coalesce(p_order_data->>'customer_email', '')));
  v_customer_phone := nullif(btrim(coalesce(p_order_data->>'customer_phone', '')), '');
  v_customer_address := nullif(btrim(coalesce(p_order_data->>'customer_address', '')), '');
  v_delivery_type := lower(btrim(coalesce(nullif(p_order_data->>'delivery_type', ''), 'shipping')));
  v_payment_method := lower(btrim(coalesce(nullif(p_order_data->>'payment_method', ''), 'transfer')));
  v_checkout_key := nullif(
    btrim(coalesce(p_order_data->>'checkout_idempotency_key', '')),
    ''
  );

  if length(v_customer_name) < 2 or length(v_customer_name) > 160 then
    raise exception 'Invalid customer name';
  end if;

  if v_customer_email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'Invalid customer email';
  end if;

  if v_customer_phone is not null and length(v_customer_phone) > 40 then
    raise exception 'Invalid customer phone';
  end if;

  if v_delivery_type not in ('shipping', 'pickup') then
    raise exception 'Invalid delivery type: %', v_delivery_type;
  end if;

  if v_payment_method not in ('mercadopago', 'mercado_pago', 'transfer', 'bank_transfer') then
    raise exception 'Invalid payment method: %', v_payment_method;
  end if;

  if v_payment_method = 'mercado_pago' then
    v_payment_method := 'mercadopago';
  elsif v_payment_method = 'bank_transfer' then
    v_payment_method := 'transfer';
  end if;

  if v_delivery_type = 'shipping' and coalesce(nullif(p_order_data->>'shipping_address_line1', ''), v_customer_address) is null then
    raise exception 'Shipping address is required';
  end if;

  v_customer_id_text := nullif(p_order_data->>'customer_id', '');
  if v_customer_id_text is not null then
    v_customer_id := v_customer_id_text::uuid;

    if v_auth_uid is null or not exists (
      select 1
      from customers
      where id = v_customer_id
        and tenant_id = v_tenant_id
        and auth_user_id = v_auth_uid
    ) then
      raise exception 'Invalid customer reference';
    end if;
  end if;

  perform pg_catalog.set_config('app.public_order_rpc_in_progress', 'true', true);

  insert into online_orders (
    tenant_id,
    order_number,
    customer_id,
    customer_email,
    customer_name,
    customer_phone,
    customer_address,
    delivery_type,
    shipping_address_line1,
    shipping_address_line2,
    shipping_city,
    shipping_state,
    shipping_postal_code,
    shipping_country,
    subtotal,
    tax_amount,
    shipping_cost,
    discount_amount,
    total,
    status,
    payment_status,
    payment_method,
    customer_notes
  ) values (
    v_tenant_id,
    public.generate_online_order_number(v_tenant_id, clock_timestamp()),
    v_customer_id,
    v_customer_email,
    v_customer_name,
    v_customer_phone,
    v_customer_address,
    v_delivery_type,
    nullif(btrim(coalesce(p_order_data->>'shipping_address_line1', '')), ''),
    nullif(btrim(coalesce(p_order_data->>'shipping_address_line2', '')), ''),
    nullif(btrim(coalesce(p_order_data->>'shipping_city', '')), ''),
    nullif(btrim(coalesce(p_order_data->>'shipping_state', '')), ''),
    nullif(btrim(coalesce(p_order_data->>'shipping_postal_code', '')), ''),
    coalesce(nullif(btrim(coalesce(p_order_data->>'shipping_country', '')), ''), 'Chile'),
    0,
    0,
    0,
    0,
    0,
    'pending',
    'pending',
    v_payment_method,
    nullif(left(btrim(coalesce(p_order_data->>'customer_notes', '')), 1000), '')
  ) returning id into v_order_id;

  for v_item in select value from jsonb_array_elements(p_order_items)
  loop
    v_product_id := nullif(v_item->>'product_id', '')::uuid;
    v_quantity := coalesce((v_item->>'quantity')::integer, 0);

    if v_product_id is null then
      raise exception 'Order item is missing product_id';
    end if;

    if v_quantity < 1 or v_quantity > 99 then
      raise exception 'Invalid quantity for product %', v_product_id;
    end if;

    select product.id,
           product.name,
           product.sku,
           coalesce(product.website_price, product.price) as public_price,
           product.cost,
           product.tax_rate,
           product.product_type,
           product.is_service,
           product.purchase_treatment,
           product.track_stock,
           product.inventory_qty,
           product.stock_quantity
      into v_product
      from products product
     where product.id = v_product_id
       and product.tenant_id = v_tenant_id
       and product.is_active = true
       and coalesce(product.is_published, false) = true
       and coalesce(product.show_on_website, false) = true
     for update;

    if not found then
      raise exception 'Product is unavailable: %', v_product_id;
    end if;

    if not (
      coalesce(v_product.is_service, false)
      or v_product.product_type = 'service'
    )
       and coalesce(v_product.track_stock, true) then
      if v_product.stock_quantity is not null
         and v_product.inventory_qty is not null
         and v_product.stock_quantity <> v_product.inventory_qty then
        raise exception 'Product stock columns disagree; checkout blocked for %',
          v_product.name;
      end if;
      if coalesce(v_product.stock_quantity, v_product.inventory_qty, 0)
         < v_quantity then
        raise exception 'Insufficient stock for product %', v_product.name;
      end if;
    end if;

    v_unit_price := round(coalesce(v_product.public_price, 0)::numeric, 2);
    v_line_total := round(v_unit_price * v_quantity, 2);
    if v_unit_price <= 0 or v_line_total <= 0 then
      raise exception 'Invalid price for product %', v_product.name;
    end if;

    insert into online_order_items (
      tenant_id,
      order_id,
      product_id,
      product_name,
      product_sku,
      quantity,
      unit_price,
      subtotal,
      unit_cost,
      tax_rate,
      is_service,
      purchase_treatment,
      product_type
    ) values (
      v_tenant_id,
      v_order_id,
      v_product.id,
      v_product.name,
      v_product.sku,
      v_quantity,
      v_unit_price,
      v_line_total,
      v_product.cost,
      v_product.tax_rate,
      (
        coalesce(v_product.is_service, false)
        or v_product.product_type = 'service'
      ),
      coalesce(v_product.purchase_treatment, 'inventory'),
      coalesce(v_product.product_type, 'product')
    );

    v_total := v_total + v_line_total;
  end loop;

  if v_total <= 0 then
    raise exception 'Invalid order total';
  end if;

  if v_payment_method = 'mercadopago' then
    v_subtotal := round(v_total / 1.19, 2);
    v_tax_amount := round(v_total - v_subtotal, 2);
  else
    v_subtotal := v_total;
    v_tax_amount := 0;
  end if;

  update online_orders
     set subtotal = v_subtotal,
         tax_amount = v_tax_amount,
         shipping_cost = 0,
         discount_amount = 0,
         total = v_total
   where id = v_order_id
     and tenant_id = v_tenant_id;

  select jsonb_build_object(
    'success', true,
    'order_id', orders.id,
    'status', orders.status,
    'payment_status', orders.payment_status,
    'version', orders.version,
    'invoice_id', orders.sales_invoice_id,
    'total', orders.total,
    'changed', true
  )
    into v_created_response
    from public.online_orders orders
   where orders.id = v_order_id
     and orders.tenant_id = v_tenant_id;

  insert into public.online_order_events (
    tenant_id, order_id, event_type, from_status, to_status,
    from_payment_status, to_payment_status, changed, expected_version,
    result_version, actor_id, operation_key, request_snapshot,
    response_snapshot
  )
  select
    orders.tenant_id, orders.id, 'order_created', null, orders.status,
    null, orders.payment_status, true, null, orders.version, v_auth_uid,
    'checkout-created:' || orders.id::text,
    jsonb_build_object(
      'source', 'public_checkout',
      'checkout_idempotency_key', v_checkout_key,
      'delivery_type', orders.delivery_type,
      'payment_method', orders.payment_method,
      'item_count', jsonb_array_length(p_order_items)
    ),
    v_created_response
  from public.online_orders orders
  where orders.id = v_order_id
    and orders.tenant_id = v_tenant_id;

  perform pg_catalog.set_config('app.public_order_rpc_in_progress', '', true);

  if v_payment_method <> 'mercadopago' then
    perform public.process_online_order(v_order_id);
  end if;

  return v_order_id;
exception
  when others then
    perform pg_catalog.set_config('app.public_order_rpc_in_progress', '', true);
    raise;
end;
$$;

grant execute on function public.create_public_online_order(jsonb, jsonb) to anon, authenticated;

-- Secure public order reader for order-confirmation pages.
-- The UUID order id is the bearer token; tenant_id must still match the current storefront.
create or replace function public.get_public_online_order(
  p_order_id uuid,
  p_tenant_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_order jsonb;
begin
  select to_jsonb(o) || jsonb_build_object('online_order_items', coalesce(items.items, '[]'::jsonb))
  into v_order
  from online_orders o
  left join lateral (
    select jsonb_agg(to_jsonb(oi) order by oi.created_at) as items
    from online_order_items oi
    where oi.order_id = o.id
      and oi.tenant_id = o.tenant_id
  ) items on true
  where o.id = p_order_id
    and o.tenant_id = p_tenant_id;

  return v_order;
end;
$$;

grant execute on function public.get_public_online_order(uuid, uuid) to anon, authenticated;

