--------------------------------------------------------------------------------
-- PUBLIC STORE RLS POLICIES
-- Allow both anonymous AND authenticated website customers to read tenant-scoped data
-- These policies enable public-facing storefronts to work with or without auth
--
-- ARCHITECTURE NOTE:
-- - ERP Users: Have user_profiles record → use user_tenant_id() function
-- - Website Customers: Have customers record (NO user_profiles) → use explicit tenant_id filter
-- - Anonymous Visitors: No auth → use explicit tenant_id filter
--
-- SECURITY NOTE: These policies allow broad read access, but the application
-- layer (PublicInventoryService) MUST filter by tenant_id using .eq('tenant_id', tenantId)
-- to prevent cross-tenant data leakage. These policies provide defense-in-depth
-- but rely on app-layer filtering for tenant isolation.
--------------------------------------------------------------------------------

-- Drop existing policies first (both anon and authenticated versions)
drop policy if exists "public_products_select" on products;
drop policy if exists "public_products_select_authenticated" on products;
do $$
begin
  if exists (select 1 from information_schema.tables where table_name = 'categories') then
    drop policy if exists "public_categories_select" on categories;
    drop policy if exists "public_categories_select_authenticated" on categories;
  end if;
exception when others then null;
end $$;
drop policy if exists "public_product_categories_select" on product_categories;
drop policy if exists "public_product_categories_select_authenticated" on product_categories;
drop policy if exists "public_website_banners_select" on website_banners;
drop policy if exists "public_website_banners_select_authenticated" on website_banners;
drop policy if exists "public_website_content_select" on website_content;
drop policy if exists "public_website_content_select_authenticated" on website_content;
drop policy if exists "public_website_settings_select" on website_settings;
drop policy if exists "public_website_settings_select_authenticated" on website_settings;
drop policy if exists "public_website_blocks_select" on website_blocks;
drop policy if exists "public_website_blocks_select_authenticated" on website_blocks;
drop policy if exists "website_blocks_select_public" on website_blocks;
drop policy if exists "public_tenants_select" on tenants;
drop policy if exists "public_tenants_select_authenticated" on tenants;
drop policy if exists "public_orders_insert" on orders;
drop policy if exists "public_order_items_insert" on order_items;
drop policy if exists "public_online_orders_insert" on online_orders;
drop policy if exists "public_online_order_items_insert" on online_order_items;
drop policy if exists "public_online_orders_insert_authenticated" on online_orders;
drop policy if exists "public_online_order_items_insert_authenticated" on online_order_items;
drop policy if exists "public_online_orders_select_authenticated" on online_orders;
drop policy if exists "public_online_order_items_select_authenticated" on online_order_items;
drop policy if exists "public_featured_products_select" on featured_products;
drop policy if exists "public_featured_products_select_authenticated" on featured_products;
drop policy if exists "public_product_brands_select" on product_brands;
drop policy if exists "public_product_brands_select_authenticated" on product_brands;
drop policy if exists "public_customers_select_own" on customers;
drop policy if exists "public_customers_update_own" on customers;
drop policy if exists "public_customers_insert_own" on customers;
drop policy if exists "public_mechanic_jobs_select_own" on mechanic_jobs;
drop policy if exists "public_bikes_select_own" on bikes;

-- ============================================================================
-- TENANT DETECTION POLICIES
-- ============================================================================

-- Tenants: Public read access (for subdomain lookup)
-- Required for public store tenant detection from URL
create policy "public_tenants_select" on tenants
  for select
  to anon
  using (is_active = true);

-- Tenants: Authenticated users can also lookup tenants (for website customers)
create policy "public_tenants_select_authenticated" on tenants
  for select
  to authenticated
  using (is_active = true);

-- ============================================================================
-- WEBSITE CONTENT POLICIES (anon + authenticated)
-- ============================================================================

-- Website blocks: Public read access (for homepage content)
-- App must filter by tenant_id explicitly
create policy "public_website_blocks_select" on website_blocks
  for select
  to anon
  using (
    coalesce(is_visible, true)
    and (
      page_id is null
      or exists (
        select 1
        from public.website_pages page
        where page.id = website_blocks.page_id
          and page.tenant_id = website_blocks.tenant_id
          and page.is_published = true
      )
    )
  );

create policy "public_website_blocks_select_authenticated" on website_blocks
  for select
  to authenticated
  using (
    coalesce(is_visible, true)
    and (
      page_id is null
      or exists (
        select 1
        from public.website_pages page
        where page.id = website_blocks.page_id
          and page.tenant_id = website_blocks.tenant_id
          and page.is_published = true
      )
    )
  );

revoke insert, update, delete, truncate, references, trigger
  on table public.website_blocks
  from anon;
grant select on table public.website_blocks to anon;

-- ============================================================================
-- PRODUCT CATALOG POLICIES (anon + authenticated)
-- These allow BOTH anonymous visitors AND logged-in website customers
-- to browse products. The app layer filters by tenant_id.
-- ============================================================================

-- Products: Public read access (only active products)
-- App must filter by tenant_id explicitly
-- Note: We allow products with 0 stock to be displayed (can show as "out of stock")
create policy "public_products_select" on products
  for select
  to anon
  using (
    is_active = true
    and coalesce(is_published, false) = true
    and coalesce(show_on_website, false) = true
  );

-- Products: Authenticated website customers can also browse
-- This is SEPARATE from ERP products_select which uses user_tenant_id()
-- Website customers don't have user_profiles, so they need this policy
create policy "public_products_select_authenticated" on products
  for select
  to authenticated
  using (
    is_active = true
    and coalesce(is_published, false) = true
    and coalesce(show_on_website, false) = true
    -- Allow if user is ERP user (has user_profiles) OR is website customer
    -- ERP users already have products_select policy, but this won't conflict
    -- because PostgreSQL RLS policies are OR'd together
  );

-- Product Categories: Public read access (hierarchical categories)
-- App must filter by tenant_id explicitly
create policy "public_product_categories_select" on product_categories
  for select
  to anon
  using (is_active = true);

create policy "public_product_categories_select_authenticated" on product_categories
  for select
  to authenticated
  using (is_active = true);

-- Legacy Categories: Public read access (if table exists)
-- App must filter by tenant_id explicitly
do $$
begin
  if exists (select 1 from information_schema.tables where table_name = 'categories') then
    execute 'create policy "public_categories_select" on categories for select to anon using (true)';
    execute 'create policy "public_categories_select_authenticated" on categories for select to authenticated using (true)';
  end if;
exception when duplicate_object then null;
end $$;

-- Website banners: Public read access (only active)
-- App must filter by tenant_id explicitly
create policy "public_website_banners_select" on website_banners
  for select
  to anon
  using (active = true);

create policy "public_website_banners_select_authenticated" on website_banners
  for select
  to authenticated
  using (active = true);

-- Website content: Public read access (tenant-isolated)
-- App must filter by tenant_id explicitly for multi-tenant routing
do $$ begin
  drop policy if exists "public_website_content_select" on website_content;
  drop policy if exists "public_website_content_select_authenticated" on website_content;
  create policy "public_website_content_select" on website_content
    for select
    to anon
    using (tenant_id is not null); -- Defense-in-depth: require valid tenant
  create policy "public_website_content_select_authenticated" on website_content
    for select
    to authenticated
    using (tenant_id is not null);
exception
  when undefined_table then raise notice '⚠ Table website_content does not exist';
end $$;

-- Website settings: Public read access
-- App must filter by tenant_id explicitly
create policy "public_website_settings_select" on website_settings
  for select
  to anon
  using (
    tenant_id is not null and
    lower(key) not like '%access_token%' and
    lower(key) not like '%secret%' and
    lower(key) not like '%password%' and
    lower(key) not like '%private%'
  );

create policy "public_website_settings_select_authenticated" on website_settings
  for select
  to authenticated
  using (
    tenant_id is not null and
    lower(key) not like '%access_token%' and
    lower(key) not like '%secret%' and
    lower(key) not like '%password%' and
    lower(key) not like '%private%'
  );

-- Featured products: Public read access
-- App must filter by tenant_id explicitly
create policy "public_featured_products_select" on featured_products
  for select
  to anon
  using (active = true);

create policy "public_featured_products_select_authenticated" on featured_products
  for select
  to authenticated
  using (active = true);

-- Product brands: Public read access
-- App must filter by tenant_id explicitly
create policy "public_product_brands_select" on product_brands
  for select
  to anon
  using (is_active = true);

create policy "public_product_brands_select_authenticated" on product_brands
  for select
  to authenticated
  using (is_active = true);

-- ============================================================================
-- CUSTOMER ACCOUNT POLICIES
-- Allow website customers to view/manage their own data
-- ============================================================================

-- Customers: Authenticated users can view their own customer record
create policy "public_customers_select_own" on customers
  for select
  to authenticated
  using (auth_user_id = auth.uid());

-- Customers: Authenticated users can update their own customer record
create policy "public_customers_update_own" on customers
  for update
  to authenticated
  using (auth_user_id = auth.uid());

-- Customers: INSERT own record (for website signup - user can only create their own customer record)
-- This is CRITICAL because website customers don't have user_profiles, so user_tenant_id() returns NULL
-- and the regular customers_insert policy fails
create policy "public_customers_insert_own" on customers
  for insert
  to authenticated
  with check (
    auth_user_id = auth.uid() AND  -- Can only create their own record
    tenant_id IS NOT NULL          -- Must specify a valid tenant
  );

-- Online Orders: Authenticated customers can view their own orders
create policy "public_online_orders_select_authenticated" on online_orders
  for select
  to authenticated
  using (customer_id IN (
    SELECT id FROM customers WHERE auth_user_id = auth.uid()
  ));

-- Online Order Items: Authenticated customers can view their own order items
create policy "public_online_order_items_select_authenticated" on online_order_items
  for select
  to authenticated
  using (order_id IN (
    SELECT id FROM online_orders WHERE customer_id IN (
      SELECT id FROM customers WHERE auth_user_id = auth.uid()
    )
  ));

-- Mechanic Jobs (Trabajos): Website customers can view their own service history
create policy "public_mechanic_jobs_select_own" on mechanic_jobs
  for select
  to authenticated
  using (customer_id IN (
    SELECT id FROM customers WHERE auth_user_id = auth.uid()
  ));

-- Bikes: Website customers can view their own bikes
create policy "public_bikes_select_own" on bikes
  for select
  to authenticated
  using (customer_id IN (
    SELECT id FROM customers WHERE auth_user_id = auth.uid()
  ));

-- Public checkout writes go through create_public_online_order(), which validates
-- the storefront tenant, customer ownership, product availability, prices, tax,
-- and totals server-side before inserting online_orders / online_order_items.
drop policy if exists "public_online_orders_insert" on online_orders;
drop policy if exists "public_online_orders_insert_authenticated" on online_orders;
drop policy if exists "public_online_order_items_insert" on online_order_items;
drop policy if exists "public_online_order_items_insert_authenticated" on online_order_items;

-- Legacy order tables are not part of public checkout. Keep anonymous writes closed.
do $$
begin
  if exists (select 1 from information_schema.tables where table_name = 'orders') then
    execute 'drop policy if exists "public_orders_insert" on orders';
  end if;
exception when duplicate_object then null;
end $$;

do $$
begin
  if exists (select 1 from information_schema.tables where table_name = 'order_items') then
    execute 'drop policy if exists "public_order_items_insert" on order_items';
  end if;
end $$;

-- Minimal exact read-side closure from
-- 20260718290000_add_online_inventory_reservations.sql. The public catalog
-- wrapper below must never exist without the reservation ledger and canonical
-- availability projection it calls. Reservation write/lifecycle orchestration
-- remains owned by its forward migration and is intentionally not duplicated
-- into this focused closure.
create unique index if not exists uq_online_orders_tenant_id_id
  on public.online_orders(tenant_id, id);
create unique index if not exists uq_products_tenant_id_id
  on public.products(tenant_id, id);
create unique index if not exists uq_online_order_items_tenant_id_id
  on public.online_order_items(tenant_id, id);

create table if not exists public.online_order_inventory_reservations (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete restrict,
  order_id uuid not null,
  order_item_id uuid not null,
  product_id uuid not null,
  quantity integer not null check (quantity > 0),
  state text not null default 'active' check (
    state in ('active', 'consuming', 'consumed', 'released', 'expired')
  ),
  cycle integer not null default 1 check (cycle > 0),
  version bigint not null default 0 check (version >= 0),
  reserved_at timestamptz not null default clock_timestamp(),
  expires_at timestamptz not null,
  consumption_started_at timestamptz,
  consumed_at timestamptz,
  released_at timestamptz,
  expired_at timestamptz,
  release_reason text,
  sales_invoice_id uuid references public.sales_invoices(id) on delete restrict,
  stock_movement_ids uuid[] not null default array[]::uuid[],
  created_by uuid references auth.users(id) on delete set null,
  updated_at timestamptz not null default clock_timestamp(),
  unique (tenant_id, id),
  unique (tenant_id, order_item_id, product_id),
  foreign key (tenant_id, order_id)
    references public.online_orders(tenant_id, id) on delete restrict,
  foreign key (tenant_id, order_item_id)
    references public.online_order_items(tenant_id, id) on delete restrict,
  foreign key (tenant_id, product_id)
    references public.products(tenant_id, id) on delete restrict,
  check (expires_at > reserved_at),
  check (state <> 'consuming' or consumption_started_at is not null),
  check (state <> 'consumed' or consumed_at is not null),
  check (state <> 'released' or released_at is not null),
  check (state <> 'expired' or expired_at is not null)
);

create index if not exists idx_online_inventory_reservations_product_active
  on public.online_order_inventory_reservations(
    tenant_id, product_id, expires_at, order_id
  ) where state = 'active';
create index if not exists idx_online_inventory_reservations_order
  on public.online_order_inventory_reservations(
    tenant_id, order_id, state, product_id
  );
create index if not exists idx_online_inventory_reservations_expiry
  on public.online_order_inventory_reservations(expires_at, tenant_id, id)
  where state = 'active';
create index if not exists idx_online_inventory_reservations_invoice
  on public.online_order_inventory_reservations(tenant_id, sales_invoice_id)
  where sales_invoice_id is not null;

alter table public.online_order_inventory_reservations enable row level security;

drop policy if exists online_inventory_reservations_select
  on public.online_order_inventory_reservations;
create policy online_inventory_reservations_select
  on public.online_order_inventory_reservations
  for select to authenticated
  using (tenant_id = public.user_tenant_id());

revoke all on public.online_order_inventory_reservations
  from public, anon, authenticated, service_role;
grant select on public.online_order_inventory_reservations to authenticated;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'codex_test_runner') then
    grant select on public.online_order_inventory_reservations
      to codex_test_runner;
  end if;
end;
$$;

create or replace function public.online_product_available_quantity(
  p_tenant_id uuid,
  p_product_id uuid
)
returns integer
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_product public.products%rowtype;
  v_available integer;
begin
  select product.* into v_product
    from public.products product
   where product.id = p_product_id
     and product.tenant_id = p_tenant_id;
  if not found then
    return 0;
  end if;

  if coalesce(v_product.is_service, false)
     or v_product.product_type = 'service'
     or not coalesce(v_product.track_stock, true) then
    return greatest(
      coalesce(v_product.stock_quantity, v_product.inventory_qty, 0),
      0
    );
  end if;

  if coalesce(v_product.is_set, false) then
    select min(greatest(floor(
      (
        coalesce(component.stock_quantity, component.inventory_qty, 0)
        - coalesce(reserved.quantity, 0)
      )::numeric / set_component.quantity_in_set
    ), 0))::integer
      into v_available
      from public.product_set_components set_component
      join public.products component
        on component.id = set_component.component_product_id
       and component.tenant_id = set_component.tenant_id
      left join lateral (
        select coalesce(sum(reservation.quantity), 0)::integer as quantity
          from public.online_order_inventory_reservations reservation
         where reservation.tenant_id = component.tenant_id
           and reservation.product_id = component.id
           and reservation.state = 'active'
           and reservation.expires_at > clock_timestamp()
      ) reserved on true
     where set_component.tenant_id = p_tenant_id
       and set_component.set_product_id = p_product_id;
    return greatest(coalesce(v_available, 0), 0);
  end if;

  select greatest(
    coalesce(v_product.stock_quantity, v_product.inventory_qty, 0)
      - coalesce(sum(reservation.quantity), 0),
    0
  )::integer
    into v_available
    from public.online_order_inventory_reservations reservation
   where reservation.tenant_id = p_tenant_id
     and reservation.product_id = p_product_id
     and reservation.state = 'active'
     and reservation.expires_at > clock_timestamp();

  return greatest(coalesce(v_available,
    coalesce(v_product.stock_quantity, v_product.inventory_qty, 0)), 0);
end;
$$;

revoke all on function public.online_product_available_quantity(uuid, uuid)
  from public, anon, authenticated, service_role;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'codex_test_runner') then
    revoke all on function public.online_product_available_quantity(uuid, uuid)
      from codex_test_runner;
  end if;
end;
$$;

comment on table public.online_order_inventory_reservations is
  'Current tenant-scoped online stock commitments. Rows do not change physical stock; active commitments become consumed only after matching invoice stock movements exist.';
comment on function public.online_product_available_quantity(uuid, uuid) is
  'Physical quantity minus live online commitments. Sets resolve the minimum available component bundle; services and non-stock products are never invented as reservations.';

drop function if exists public.get_public_products(uuid, uuid[], uuid[], text, text, text, boolean, text, boolean, boolean, boolean, text, integer, integer);
drop function if exists public.search_public_products(text, uuid, integer, text, boolean, boolean, boolean);
drop function if exists public.get_public_featured_products(uuid, integer, text, boolean, boolean, boolean);
drop function if exists public.get_public_product_category_counts(uuid, text, boolean, text, boolean, boolean, boolean);

create or replace function public.get_public_products_without_inventory_reservations(
  p_tenant_id uuid,
  p_category_ids uuid[] default null,
  p_product_ids uuid[] default null,
  p_sku text default null,
  p_search_term text default null,
  p_product_type text default null,
  p_only_in_stock boolean default true,
  p_sort_by text default 'name',
  p_limit integer default 20,
  p_offset integer default 0
)
returns table (
  id uuid,
  tenant_id uuid,
  name text,
  sku text,
  barcode text,
  price numeric,
  cost numeric,
  inventory_qty integer,
  stock_quantity integer,
  image_url text,
  image_url_optimized text,
  image_urls text[],
  description text,
  website_description text,
  category text,
  category_id uuid,
  category_name text,
  brand_id uuid,
  brand text,
  model text,
  manufacturer text,
  manufacturer_sku text,
  gtin text,
  product_type text,
  track_stock boolean,
  is_active boolean,
  is_published boolean,
  show_on_website boolean,
  created_at timestamptz,
  updated_at timestamptz,
  total_count bigint
)
language sql
security definer
set search_path = public
stable
as $$
  with args as (
    select
      s.term,
      coalesce(t.tokens, array[]::text[]) as tokens,
      greatest(coalesce(p_limit, 20), 0) as page_limit,
      greatest(coalesce(p_offset, 0), 0) as page_offset,
      lower(coalesce(nullif(trim(p_sort_by), ''), 'name')) as sort_by,
      nullif(trim(coalesce(p_sku, '')), '') as wanted_sku,
      nullif(trim(coalesce(p_product_type, '')), '') as wanted_product_type,
      -- The outer reservation-aware wrapper is the sole stock-policy owner.
      'all'::text as stock_policy,
      lower(coalesce((
          select ws.value
          from public.website_settings ws
          where ws.tenant_id = p_tenant_id
            and ws.key = 'product_visibility_require_image'
          limit 1
        ), 'false')) in ('true', '1', 'yes', 'si', 'sí') as require_image,
      lower(coalesce((
          select ws.value
          from public.website_settings ws
          where ws.tenant_id = p_tenant_id
            and ws.key = 'product_visibility_require_visible_category'
          limit 1
        ), 'false')) in ('true', '1', 'yes', 'si', 'sí') as require_visible_category,
      lower(coalesce((
          select ws.value
          from public.website_settings ws
          where ws.tenant_id = p_tenant_id
            and ws.key = 'product_visibility_include_uncategorized'
          limit 1
        ), 'true')) in ('true', '1', 'yes', 'si', 'sí') as include_uncategorized
    from (
      select trim(
        regexp_replace(
          unaccent(lower(trim(coalesce(p_search_term, '')))),
          '[^a-z0-9]+',
          ' ',
          'g'
        )
      ) as term
    ) s
    cross join lateral (
      select array_agg(token) as tokens
      from regexp_split_to_table(s.term, '\s+') as token_parts(token)
      where token <> ''
    ) t
  ),
  normalized as (
    select
      p.*,
      a.term,
      a.tokens,
      a.page_limit,
      a.page_offset,
      a.sort_by,
      (
        a.term ~ '(^| )(servicio|servicios|mantencion|mantenciones|reparacion|reparaciones|ajuste|ajustes|instalacion|instalaciones|limpieza|lavado|engrase|sangrado|purga|centrado|enrayado|diagnostico|revision)( |$)'
      ) as service_intent,
      trim(regexp_replace(unaccent(lower(concat_ws(' ', p.website_name, p.name))), '[^a-z0-9]+', ' ', 'g')) as name_n,
      trim(regexp_replace(unaccent(lower(coalesce(p.sku, ''))), '[^a-z0-9]+', ' ', 'g')) as sku_n,
      trim(regexp_replace(unaccent(lower(coalesce(p.barcode, ''))), '[^a-z0-9]+', ' ', 'g')) as barcode_n,
      trim(regexp_replace(unaccent(lower(coalesce(p.gtin, ''))), '[^a-z0-9]+', ' ', 'g')) as gtin_n,
      trim(regexp_replace(unaccent(lower(coalesce(p.category_name, p.category, ''))), '[^a-z0-9]+', ' ', 'g')) as category_n,
      trim(regexp_replace(unaccent(lower(coalesce(p.brand, ''))), '[^a-z0-9]+', ' ', 'g')) as brand_n,
      trim(regexp_replace(unaccent(lower(coalesce(p.model, ''))), '[^a-z0-9]+', ' ', 'g')) as model_n,
      trim(regexp_replace(unaccent(lower(coalesce(p.manufacturer, ''))), '[^a-z0-9]+', ' ', 'g')) as manufacturer_n,
      trim(regexp_replace(unaccent(lower(coalesce(p.manufacturer_sku, ''))), '[^a-z0-9]+', ' ', 'g')) as manufacturer_sku_n,
      trim(regexp_replace(unaccent(lower(concat_ws(' ', p.website_description, p.description))), '[^a-z0-9]+', ' ', 'g')) as description_n
    from public.products p
    cross join args a
    where p.tenant_id = p_tenant_id
      and p.is_active = true
      and coalesce(p.is_published, false) = true
      and coalesce(p.show_on_website, false) = true
      and (
        p_product_ids is null
        or cardinality(p_product_ids) = 0
        or p.id = any(p_product_ids)
      )
      and (
        p_category_ids is null
        or cardinality(p_category_ids) = 0
        or p.category_id = any(p_category_ids)
      )
      and (
        a.wanted_sku is null
        or lower(p.sku) = lower(a.wanted_sku)
      )
      and (
        a.wanted_product_type is null
        or p.product_type = a.wanted_product_type
      )
      and (
        not a.require_image
        or nullif(btrim(coalesce(p.website_image_url, '')), '') is not null
        or nullif(btrim(coalesce(p.website_image_url_optimized, '')), '') is not null
        or cardinality(coalesce(p.website_image_urls, array[]::text[])) > 0
        or nullif(btrim(coalesce(p.image_url, '')), '') is not null
        or nullif(btrim(coalesce(p.image_url_optimized, '')), '') is not null
        or cardinality(coalesce(p.image_urls, array[]::text[])) > 0
      )
      and (
        not a.require_visible_category
        or (p.category_id is null and a.include_uncategorized)
        or exists (
          select 1
          from public.product_categories pc
          where pc.id = p.category_id
            and pc.tenant_id = p_tenant_id
            and pc.is_active = true
            and coalesce(pc.show_on_website, false) = true
        )
      )
      and (
        a.stock_policy = 'all'
        or coalesce(p.is_service, false)
        or p.product_type = 'service'
        or (
          a.stock_policy = 'available_only'
          and (
            coalesce(p.track_stock, true) = false
            or coalesce(p.stock_quantity, p.inventory_qty, 0) > 0
          )
        )
        or (
          a.stock_policy = 'out_of_stock_only'
          and coalesce(p.track_stock, true) = true
          and coalesce(p.stock_quantity, p.inventory_qty, 0) <= 0
        )
      )
  ),
  enriched as (
    select
      n.*,
      trim(concat_ws(
        ' ',
        case
          when n.name_n like '%pinon%'
            or n.category_n in ('pinones', 'cassette')
            then 'pinon pinones cassette freewheel rueda libre coronas'
          else null
        end,
        case
          when concat_ws(' ', n.name_n, n.category_n) like '%cadena%'
            then 'cadena chain transmision'
          else null
        end,
        case
          when concat_ws(' ', n.name_n, n.category_n) like '%camara%'
            then 'camara tubo tube valvula neumatico'
          else null
        end,
        case
          when concat_ws(' ', n.name_n, n.category_n) like '%cubierta%'
            or concat_ws(' ', n.name_n, n.category_n) like '%neumatico%'
            then 'cubierta neumatico tire goma'
          else null
        end
      )) as alias_n
    from normalized n
  ),
  matched as (
    select
      e.*,
      (
        case when e.term <> '' and e.sku_n = e.term then 1000 else 0 end +
        case when e.term <> '' and e.barcode_n = e.term then 980 else 0 end +
        case when e.term <> '' and e.gtin_n = e.term then 980 else 0 end +
        case when e.term <> '' and e.name_n = e.term then 850 else 0 end +
        case when e.term <> '' and e.name_n like e.term || '%' then 760 else 0 end +
        case when e.term <> '' and e.name_n like '%' || e.term || '%' then 650 else 0 end +
        case when e.term <> '' and e.category_n = e.term then 620 else 0 end +
        case when e.term <> '' and e.category_n like '%' || e.term || '%' then 560 else 0 end +
        case when e.term <> '' and e.alias_n like '%' || e.term || '%' then 500 else 0 end +
        case when e.term <> '' and e.sku_n like '%' || e.term || '%' then 460 else 0 end +
        case when e.term <> '' and e.manufacturer_sku_n like '%' || e.term || '%' then 420 else 0 end +
        case when e.term <> '' and e.brand_n like '%' || e.term || '%' then 360 else 0 end +
        case when e.term <> '' and e.model_n like '%' || e.term || '%' then 320 else 0 end +
        case when e.term <> '' and e.manufacturer_n like '%' || e.term || '%' then 300 else 0 end
      ) as phrase_strong_score,
      coalesce((
        select sum(
          case
            when token ~ '^[0-9]+$' and e.sku_n = token then 120
            when token ~ '^[0-9]+$' and e.barcode_n = token then 120
            when token ~ '^[0-9]+$' and e.gtin_n = token then 120
            when token ~ '^[0-9]+$' and e.name_n ~ ('(^|[^0-9])' || token || '([^0-9]|$)') then 70
            when token ~ '^[0-9]+$' and e.category_n ~ ('(^|[^0-9])' || token || '([^0-9]|$)') then 58
            when token ~ '^[0-9]+$' then 0
            when e.name_n like token || '%' then 95
            when e.name_n like '%' || token || '%' then 76
            when e.category_n like '%' || token || '%' then 66
            when e.alias_n like '%' || token || '%' then 56
            when e.sku_n like '%' || token || '%' then 54
            when e.manufacturer_sku_n like '%' || token || '%' then 48
            when e.brand_n like '%' || token || '%' then 42
            when e.model_n like '%' || token || '%' then 38
            when e.manufacturer_n like '%' || token || '%' then 34
            when length(token) >= 4 and greatest(
              word_similarity(token, e.name_n),
              word_similarity(token, e.category_n),
              word_similarity(token, e.brand_n),
              word_similarity(token, e.model_n),
              word_similarity(token, e.manufacturer_n),
              word_similarity(token, e.alias_n)
            ) >= case when length(token) >= 5 then 0.56 else 0.72 end then 28
            else 0
          end
        )
        from unnest(e.tokens) as token_parts(token)
        where token <> ''
      ), 0) as token_strong_score,
      coalesce((
        select sum(
          case
            when token ~ '^[0-9]+$' and e.description_n ~ ('(^|[^0-9])' || token || '([^0-9]|$)') then 8
            when token !~ '^[0-9]+$' and e.description_n like '%' || token || '%' then 8
            when token !~ '^[0-9]+$' and length(token) >= 5 and word_similarity(token, e.description_n) >= 0.86 then 5
            else 0
          end
        )
        from unnest(e.tokens) as token_parts(token)
        where token <> ''
      ), 0) as weak_description_score
    from enriched e
    where e.term = ''
      or not exists (
        select 1
        from unnest(e.tokens) as token_parts(token)
        where token <> ''
          and not (
            (
              token ~ '^[0-9]+$'
              and (
                e.sku_n = token
                or e.barcode_n = token
                or e.gtin_n = token
                or e.name_n ~ ('(^|[^0-9])' || token || '([^0-9]|$)')
                or e.category_n ~ ('(^|[^0-9])' || token || '([^0-9]|$)')
                or e.description_n ~ ('(^|[^0-9])' || token || '([^0-9]|$)')
              )
            )
            or (
              token !~ '^[0-9]+$'
              and (
                e.name_n like '%' || token || '%'
                or e.category_n like '%' || token || '%'
                or e.alias_n like '%' || token || '%'
                or e.sku_n like '%' || token || '%'
                or e.barcode_n like '%' || token || '%'
                or e.gtin_n like '%' || token || '%'
                or e.brand_n like '%' || token || '%'
                or e.model_n like '%' || token || '%'
                or e.manufacturer_n like '%' || token || '%'
                or e.manufacturer_sku_n like '%' || token || '%'
                or e.description_n like '%' || token || '%'
                or (
                  length(token) >= 4
                  and greatest(
                    word_similarity(token, e.name_n),
                    word_similarity(token, e.category_n),
                    word_similarity(token, e.brand_n),
                    word_similarity(token, e.model_n),
                    word_similarity(token, e.manufacturer_n),
                    word_similarity(token, e.alias_n)
                  ) >= case when length(token) >= 5 then 0.56 else 0.72 end
                )
                or (
                  length(token) >= 5
                  and word_similarity(token, e.description_n) >= 0.86
                )
              )
            )
          )
      )
  ),
  scored as (
    select
      m.*,
      (m.phrase_strong_score + m.token_strong_score) as strong_score,
      (
        m.phrase_strong_score +
        m.token_strong_score +
        m.weak_description_score +
        case when m.product_type = 'service' and not m.service_intent
          then -260 else 0 end
      ) as search_score
    from matched m
  ),
  ranked as (
    select s.*
    from scored s
    where s.term = ''
      or s.product_type <> 'service'
      or s.service_intent
      or s.strong_score > 0
      or not exists (
        select 1
        from scored product_match
        where product_match.product_type <> 'service'
          and product_match.strong_score > 0
      )
  ),
  counted as (
    select p.*, count(*) over() as row_total
    from ranked p
  )
  select
    p.id,
    p.tenant_id,
    coalesce(nullif(btrim(p.website_name), ''), p.name) as name,
    p.sku,
    p.barcode,
    coalesce(p.website_price, p.price) as price,
    0::numeric as cost,
    p.inventory_qty,
    p.stock_quantity,
    coalesce(nullif(btrim(p.website_image_url), ''), p.image_url) as image_url,
    coalesce(nullif(btrim(p.website_image_url_optimized), ''), p.image_url_optimized) as image_url_optimized,
    case
      when cardinality(coalesce(p.website_image_urls, array[]::text[])) > 0
        then p.website_image_urls
      else p.image_urls
    end as image_urls,
    p.description,
    p.website_description,
    p.category,
    p.category_id,
    p.category_name,
    p.brand_id,
    p.brand,
    p.model,
    p.manufacturer,
    p.manufacturer_sku,
    p.gtin,
    p.product_type,
    p.track_stock,
    p.is_active,
    p.is_published,
    p.show_on_website,
    p.created_at,
    p.updated_at,
    p.row_total as total_count
  from counted p
  order by
    case when p.term <> '' then p.search_score end desc nulls last,
    case when p.term = '' and p.sort_by = 'price_asc'
      then coalesce(p.website_price, p.price) end asc nulls last,
    case when p.term = '' and p.sort_by = 'price_desc'
      then coalesce(p.website_price, p.price) end desc nulls last,
    case when p.term = '' and p.sort_by = 'newest'
      then p.created_at end desc nulls last,
    coalesce(nullif(btrim(p.website_name), ''), p.name) asc,
    p.id asc
  limit (select page_limit from args)
  offset (select page_offset from args);
$$;

revoke all on function public.get_public_products_without_inventory_reservations(
  uuid, uuid[], uuid[], text, text, text, boolean, text, integer, integer
) from public, anon, authenticated, service_role;

create or replace function public.get_public_products(
  p_tenant_id uuid,
  p_category_ids uuid[] default null::uuid[],
  p_product_ids uuid[] default null::uuid[],
  p_sku text default null::text,
  p_search_term text default null::text,
  p_product_type text default null::text,
  p_only_in_stock boolean default true,
  p_sort_by text default 'name'::text,
  p_limit integer default 20,
  p_offset integer default 0
)
returns table(
  id uuid, tenant_id uuid, name text, sku text, barcode text, price numeric,
  cost numeric, inventory_qty integer, stock_quantity integer, image_url text,
  image_url_optimized text, image_urls text[], description text,
  website_description text, category text, category_id uuid,
  category_name text, brand_id uuid, brand text, model text, manufacturer text,
  manufacturer_sku text, gtin text, product_type text, track_stock boolean,
  is_active boolean, is_published boolean, show_on_website boolean,
  created_at timestamp with time zone, updated_at timestamp with time zone,
  total_count bigint
)
language sql
stable
security definer
set search_path to 'public'
as $$
  with policy as (
    select case lower(coalesce(
      nullif(btrim(coalesce((
        select setting.value
          from public.website_settings setting
         where setting.tenant_id = p_tenant_id
           and setting.key = 'product_visibility_stock_policy'
         limit 1
      ), '')), ''),
      case when p_only_in_stock then 'available_only' else 'all' end
    ))
      when 'all' then 'all'
      when 'both' then 'all'
      when 'out_of_stock_only' then 'out_of_stock_only'
      when 'out_of_stock' then 'out_of_stock_only'
      when 'sin_stock' then 'out_of_stock_only'
      else 'available_only'
    end as stock_policy
  ), raw_rows as (
    select raw.*
      from public.get_public_products_without_inventory_reservations(
        p_tenant_id,
        p_category_ids,
        p_product_ids,
        p_sku,
        p_search_term,
        p_product_type,
        false,
        p_sort_by,
        2147483647,
        0
      ) with ordinality as raw
  ), candidate as (
    -- One join instead of one function call per row. `is_set` and `is_service`
    -- are the only facts the inner catalog query does not already return.
    select r.id,
           r.tenant_id,
           r.stock_quantity,
           r.inventory_qty,
           coalesce(product.is_set, false) as is_set,
           coalesce(product.is_service, false) as is_service
      from raw_rows r
      join public.products product
        on product.id = r.id
       and product.tenant_id = r.tenant_id
     where r.product_type is distinct from 'service'
       and coalesce(r.track_stock, true)
  ), reserved as (
    -- Aggregated once for the whole tenant, then joined. Covers both the
    -- products themselves and the components of any set among them.
    select reservation.product_id,
           sum(reservation.quantity)::integer as quantity
      from public.online_order_inventory_reservations reservation
     where reservation.tenant_id = p_tenant_id
       and reservation.state = 'active'
       and reservation.expires_at > clock_timestamp()
     group by reservation.product_id
  ), simple_availability as (
    select candidate.id,
           greatest(
             coalesce(candidate.stock_quantity, candidate.inventory_qty, 0)
               - coalesce(reserved.quantity, 0),
             0
           ) as available_quantity
      from candidate
      left join reserved on reserved.product_id = candidate.id
     where not candidate.is_set
       and not candidate.is_service
  ), set_availability as (
    -- A set is limited by its scarcest component. An inner join means a set
    -- with no components produces no row here and resolves to zero below,
    -- which is what the per-row function returned for that case.
    select candidate.id,
           min(greatest(floor(
             (
               coalesce(component.stock_quantity, component.inventory_qty, 0)
               - coalesce(component_reserved.quantity, 0)
             )::numeric / set_component.quantity_in_set
           ), 0))::integer as available_quantity
      from candidate
      join public.product_set_components set_component
        on set_component.tenant_id = candidate.tenant_id
       and set_component.set_product_id = candidate.id
      join public.products component
        on component.id = set_component.component_product_id
       and component.tenant_id = set_component.tenant_id
      left join reserved component_reserved
        on component_reserved.product_id = component.id
     where candidate.is_set
       and not candidate.is_service
     group by candidate.id
  ), availability as (
    select id, available_quantity from simple_availability
    union all
    select id, available_quantity from set_availability
  ), base_rows as (
    select r.*,
           case
             when r.product_type = 'service'
               or not coalesce(r.track_stock, true)
               or coalesce(service_like.is_service, false)
               then greatest(coalesce(r.stock_quantity, r.inventory_qty, 0), 0)
             else coalesce(availability.available_quantity, 0)
           end as available_quantity
      from raw_rows r
      left join availability on availability.id = r.id
      left join candidate service_like on service_like.id = r.id
  ), filtered as (
    select base.*
      from base_rows base
      cross join policy
     where policy.stock_policy = 'all'
        or base.product_type = 'service'
        or not coalesce(base.track_stock, true)
        or (
          policy.stock_policy = 'available_only'
          and base.available_quantity > 0
        )
        or (
          policy.stock_policy = 'out_of_stock_only'
          and base.available_quantity <= 0
        )
  ), paged as (
    select filtered.*,
           count(*) over() as filtered_total
      from filtered
     order by filtered.ordinality
     limit greatest(coalesce(p_limit, 20), 0)
     offset greatest(coalesce(p_offset, 0), 0)
  )
  select
    paged.id,
    paged.tenant_id,
    paged.name,
    paged.sku,
    paged.barcode,
    paged.price,
    paged.cost,
    case
      when paged.product_type = 'service'
        or not coalesce(paged.track_stock, true)
        then paged.inventory_qty
      else paged.available_quantity
    end as inventory_qty,
    case
      when paged.product_type = 'service'
        or not coalesce(paged.track_stock, true)
        then paged.stock_quantity
      else paged.available_quantity
    end as stock_quantity,
    paged.image_url,
    paged.image_url_optimized,
    paged.image_urls,
    paged.description,
    paged.website_description,
    paged.category,
    paged.category_id,
    paged.category_name,
    paged.brand_id,
    paged.brand,
    paged.model,
    paged.manufacturer,
    paged.manufacturer_sku,
    paged.gtin,
    paged.product_type,
    paged.track_stock,
    paged.is_active,
    paged.is_published,
    paged.show_on_website,
    paged.created_at,
    paged.updated_at,
    paged.filtered_total as total_count
  from paged
  order by paged.ordinality;
$$;

