-- Server-backed visitor facets. The canonical public product RPC remains the
-- publication, visibility, search and availability owner; these additive v1
-- facades filter its complete result before counting and pagination.
create or replace function public.get_public_products_faceted_v1(
  p_tenant_id uuid,
  p_category_ids uuid[] default null,
  p_search_term text default null,
  p_product_type text default null,
  p_only_in_stock boolean default true,
  p_brand_ids uuid[] default null,
  p_min_price numeric default null,
  p_max_price numeric default null,
  p_sort_by text default 'name',
  p_limit integer default 20,
  p_offset integer default 0
)
returns table (
  id uuid,
  tenant_id uuid,
  name text,
  sku text,
  barcode text,
  price numeric,
  cost numeric,
  inventory_qty integer,
  stock_quantity integer,
  image_url text,
  image_url_optimized text,
  image_urls text[],
  description text,
  website_description text,
  category text,
  category_id uuid,
  category_name text,
  brand_id uuid,
  brand text,
  model text,
  manufacturer text,
  manufacturer_sku text,
  gtin text,
  product_type text,
  track_stock boolean,
  is_active boolean,
  is_published boolean,
  show_on_website boolean,
  created_at timestamptz,
  updated_at timestamptz,
  total_count bigint
)
language sql
stable
security definer
set search_path = public
as $$
  with args as (
    select
      case
        when p_min_price is null then null
        when p_min_price >= 0 then p_min_price
        else null
      end as min_price,
      case
        when p_max_price is null then null
        when p_max_price >= 0 then p_max_price
        else null
      end as max_price,
      (
        (p_min_price is null or p_min_price >= 0)
        and (p_max_price is null or p_max_price >= 0)
        and (
          p_min_price is null
          or p_max_price is null
          or p_min_price <= p_max_price
        )
      ) as is_valid
  ), base_rows as (
    select product.*
    from public.get_public_products(
      p_tenant_id := p_tenant_id,
      p_category_ids := p_category_ids,
      p_search_term := p_search_term,
      p_product_type := p_product_type,
      -- The canonical RPC applies the site's publication stock policy first.
      -- Request its rule-allowed universe here, then apply the visitor's
      -- optional availability facet to the reservation-aware quantities it
      -- returns. A visitor can narrow a rule, never widen it.
      p_only_in_stock := true,
      p_sort_by := p_sort_by,
      p_limit := 2147483647,
      p_offset := 0
    ) with ordinality as product
  ), available_rows as (
    select base.*
    from base_rows base
    where not coalesce(p_only_in_stock, true)
      or base.product_type = 'service'
      or not coalesce(base.track_stock, true)
      or coalesce(base.stock_quantity, base.inventory_qty, 0) > 0
  ), filtered as (
    select base.*
    from available_rows base
    cross join args
    where args.is_valid
      and (
        p_brand_ids is null
        or cardinality(p_brand_ids) = 0
        or base.brand_id = any(p_brand_ids)
      )
      and (args.min_price is null or base.price >= args.min_price)
      and (args.max_price is null or base.price <= args.max_price)
  ), page_contract as (
    select
      least(greatest(coalesce(p_limit, 20), 1), 100)::bigint as page_limit,
      greatest(coalesce(p_offset, 0), 0)::bigint as requested_offset,
      count(*)::bigint as total_count
    from filtered
  ), page_window as (
    -- The row contract carries total_count, so a non-empty result can never
    -- disappear solely because limit is zero or the requested offset is stale.
    -- Clamp to at least one row and to the start of the final valid page.
    select
      contract.page_limit,
      contract.total_count,
      case
        when contract.total_count = 0 then 0::bigint
        else least(
          contract.requested_offset,
          (
            (contract.total_count - 1) / contract.page_limit
          ) * contract.page_limit
        )
      end as page_offset
    from page_contract contract
  ), paged as (
    select filtered.*, page.total_count as filtered_total
    from filtered
    cross join page_window page
    order by filtered.ordinality
    limit (select page_limit from page_window)
    offset (select page_offset from page_window)
  )
  select
    paged.id,
    paged.tenant_id,
    paged.name,
    paged.sku,
    paged.barcode,
    paged.price,
    paged.cost,
    paged.inventory_qty,
    paged.stock_quantity,
    paged.image_url,
    paged.image_url_optimized,
    paged.image_urls,
    paged.description,
    paged.website_description,
    paged.category,
    paged.category_id,
    paged.category_name,
    paged.brand_id,
    paged.brand,
    paged.model,
    paged.manufacturer,
    paged.manufacturer_sku,
    paged.gtin,
    paged.product_type,
    paged.track_stock,
    paged.is_active,
    paged.is_published,
    paged.show_on_website,
    paged.created_at,
    paged.updated_at,
    paged.filtered_total
  from paged
  order by paged.ordinality;
$$;

comment on function public.get_public_products_faceted_v1(
  uuid, uuid[], text, text, boolean, uuid[], numeric, numeric, text, integer,
  integer
) is
  'Server-paged public catalog facade. Applies stable brand IDs and effective storefront price filters after canonical public eligibility and reservation-aware availability. Clamps page size to 1..100 and stale offsets to the final valid page so every non-empty response carries total_count.';

revoke all on function public.get_public_products_faceted_v1(
  uuid, uuid[], text, text, boolean, uuid[], numeric, numeric, text, integer,
  integer
) from public, anon, authenticated, service_role;
grant execute on function public.get_public_products_faceted_v1(
  uuid, uuid[], text, text, boolean, uuid[], numeric, numeric, text, integer,
  integer
) to anon, authenticated;

create or replace function public.get_public_product_facets_v1(
  p_tenant_id uuid,
  p_category_ids uuid[] default null,
  p_search_term text default null,
  p_product_type text default null,
  p_only_in_stock boolean default true,
  p_brand_ids uuid[] default null,
  p_min_price numeric default null,
  p_max_price numeric default null
)
returns table (
  facet_key text,
  value_id text,
  value_label text,
  item_count bigint,
  range_min numeric,
  range_max numeric
)
language sql
stable
security definer
set search_path = public
as $$
  with args as (
    select
      case
        when p_min_price is null then null
        when p_min_price >= 0 then p_min_price
        else null
      end as min_price,
      case
        when p_max_price is null then null
        when p_max_price >= 0 then p_max_price
        else null
      end as max_price,
      (
        (p_min_price is null or p_min_price >= 0)
        and (p_max_price is null or p_max_price >= 0)
        and (
          p_min_price is null
          or p_max_price is null
          or p_min_price <= p_max_price
        )
      ) as is_valid
  ), canonical_universe as materialized (
    -- Load the canonical search/type/publication/site-stock universe exactly
    -- once. Every facet projection below is derived from this same
    -- reservation-aware snapshot, preventing duplicate full catalog scans.
    select product.*
    from public.get_public_products(
      p_tenant_id := p_tenant_id,
      p_category_ids := null,
      p_search_term := p_search_term,
      p_product_type := p_product_type,
      p_only_in_stock := true,
      p_sort_by := 'name',
      p_limit := 2147483647,
      p_offset := 0
    ) product
  ), available_universe as materialized (
    select base.*
    from canonical_universe base
    where not coalesce(p_only_in_stock, true)
      or base.product_type = 'service'
      or not coalesce(base.track_stock, true)
      or coalesce(base.stock_quantity, base.inventory_qty, 0) > 0
  ), selected_category_rows as materialized (
    -- Brand and price metadata respect the active category selection. This is
    -- the exact direct-ID predicate owned by the canonical product RPC, now
    -- applied after its single unselected-universe call.
    select base.*
    from available_universe base
    where p_category_ids is null
      or cardinality(p_category_ids) = 0
      or base.category_id = any(p_category_ids)
  ), category_filtered_rows as materialized (
    -- Category options and the summary deliberately exclude the current
    -- category selection while respecting every other active facet.
    select base.*
    from available_universe base
    cross join args
    where args.is_valid
      and (
        p_brand_ids is null
        or cardinality(p_brand_ids) = 0
        or base.brand_id = any(p_brand_ids)
      )
      and (args.min_price is null or base.price >= args.min_price)
      and (args.max_price is null or base.price <= args.max_price)
  ), category_rows as (
    -- Keep direct counts for every active canonical category. The category
    -- publication owner decides which IDs become visible filter options, so a
    -- hidden descendant can still roll up into its visible published ancestor.
    select
      'category'::text as facet_key,
      base.category_id::text as value_id,
      nullif(btrim(canonical_category.name), '') as value_label,
      count(*)::bigint as item_count,
      null::numeric as range_min,
      null::numeric as range_max
    from category_filtered_rows base
    join public.product_categories canonical_category
      on canonical_category.id = base.category_id
     and canonical_category.tenant_id = p_tenant_id
     and canonical_category.is_active = true
    group by base.category_id, canonical_category.name
  ), summary_rows as (
    -- This is the exact total for the category-option universe. It includes
    -- uncategorized products, so consumers must not derive "Todas" by summing
    -- only the category rows.
    select
      'summary'::text as facet_key,
      null::text as value_id,
      null::text as value_label,
      count(*)::bigint as item_count,
      null::numeric as range_min,
      null::numeric as range_max
    from category_filtered_rows
  ), brand_rows as (
    -- Brand counts exclude the current brand selection, but respect every
    -- other active facet so alternatives remain useful and truthful.
    select
      'brand'::text as facet_key,
      base.brand_id::text as value_id,
      coalesce(nullif(btrim(canonical_brand.name), ''), nullif(btrim(base.brand), ''))
        as value_label,
      count(*)::bigint as item_count,
      null::numeric as range_min,
      null::numeric as range_max
    from selected_category_rows base
    cross join args
    left join public.product_brands canonical_brand
      on canonical_brand.id = base.brand_id
     and (
       canonical_brand.tenant_id is null
       or canonical_brand.tenant_id = p_tenant_id
     )
    where args.is_valid
      and base.brand_id is not null
      and (args.min_price is null or base.price >= args.min_price)
      and (args.max_price is null or base.price <= args.max_price)
    group by
      base.brand_id,
      coalesce(nullif(btrim(canonical_brand.name), ''), nullif(btrim(base.brand), ''))
  ), price_rows as (
    -- Price bounds exclude the current price range, but respect the selected
    -- brands and every route/publication/availability filter.
    select
      'price'::text as facet_key,
      null::text as value_id,
      null::text as value_label,
      count(*)::bigint as item_count,
      min(base.price)::numeric as range_min,
      max(base.price)::numeric as range_max
    from selected_category_rows base
    cross join args
    where args.is_valid
      and (
        p_brand_ids is null
        or cardinality(p_brand_ids) = 0
        or base.brand_id = any(p_brand_ids)
      )
  )
  select * from category_rows
  where value_label is not null
  union all
  select * from brand_rows
  where value_label is not null
  union all
  select * from price_rows
  union all
  select * from summary_rows
  order by facet_key, value_label nulls first, value_id nulls first;
$$;

comment on function public.get_public_product_facets_v1(
  uuid, uuid[], text, text, boolean, uuid[], numeric, numeric
) is
  'Public category, brand, price and total-summary facet metadata derived from the complete canonical eligible catalog. Counts exclude their own facet and respect all other filters.';

revoke all on function public.get_public_product_facets_v1(
  uuid, uuid[], text, text, boolean, uuid[], numeric, numeric
) from public, anon, authenticated, service_role;
grant execute on function public.get_public_product_facets_v1(
  uuid, uuid[], text, text, boolean, uuid[], numeric, numeric
) to anon, authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================
-- F29 TAX DECLARATIONS & HR ENHANCEMENTS
-- ==============================================================================
-- Chilean Monthly Tax Declaration (Formulario 29) + Enhanced HR Module
-- Includes: Medical leaves (licencias médicas), payroll integration, contracts
-- Date: December 2024
-- ==============================================================================

-- ============================================================================
-- F29 TAX DECLARATIONS MODULE
-- ============================================================================

-- F29 monthly tax declarations
create table if not exists f29_declarations (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade not null,
  period_month integer not null check (period_month between 1 and 12),
  period_year integer not null check (period_year between 2000 and 2100),
  status text not null check (status in ('draft', 'submitted', 'paid')) default 'draft',

  -- IVA Section (Lines 1-43)
  iva_debito_ventas numeric(15,2) default 0, -- Line 3: Domestic sales IVA
  iva_debito_exportaciones numeric(15,2) default 0, -- Line 5: Exports (usually 0)
  iva_debito_activos_fijos numeric(15,2) default 0, -- Line 7: Fixed asset sales IVA
  iva_debito_total numeric(15,2) default 0, -- Line 15: Total IVA débito

  iva_credito_compras numeric(15,2) default 0, -- Line 30: Purchases IVA
  iva_credito_importaciones numeric(15,2) default 0, -- Line 31: Import IVA
  iva_credito_activos_fijos numeric(15,2) default 0, -- Line 32: Fixed asset purchases IVA
  iva_credito_total numeric(15,2) default 0, -- Line 40: Total IVA crédito

  iva_remanente_mes_anterior numeric(15,2) default 0, -- Line 35: Previous month credit carryover
  iva_remanente_mes_siguiente numeric(15,2) default 0, -- Line 42: Credit to carry forward
  iva_neto numeric(15,2) default 0, -- Line 43: Net IVA (débito - crédito)

  -- PPM Section (Lines 50-60)
  ppm_ventas_netas numeric(15,2) default 0, -- Line 50: Net sales base
  ppm_tasa_porcentaje numeric(5,2) default 1.0, -- Line 52: PPM rate (%)
  ppm_monto numeric(15,2) default 0, -- Line 54: PPM amount to pay
  ppm_remanente numeric(15,2) default 0, -- Line 56: PPM credit carryover

  -- Retenciones - Tax Withholdings (Lines 70-100)
  retencion_segunda_categoria numeric(15,2) default 0, -- Line 72: Employee income tax
  retencion_honorarios numeric(15,2) default 0, -- Line 74: Professional fees (10%)
  retencion_arrendamiento numeric(15,2) default 0, -- Line 76: Rental income

  -- Otros Impuestos - Other Taxes (Lines 110-150)
  impuesto_adicional numeric(15,2) default 0, -- Line 115: Additional tax
  impuesto_especifico numeric(15,2) default 0, -- Line 117: Specific tax

  -- Totals
  total_a_pagar numeric(15,2) default 0, -- Total amount to pay
  total_a_favor numeric(15,2) default 0, -- Total credit in favor

  -- Filing tracking
  folio_number text, -- SII confirmation folio
  filed_at timestamp with time zone,
  paid_at timestamp with time zone,
  payment_reference text,
  due_date date,

  -- Metadata
  notes text,
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now(),

  unique(tenant_id, period_year, period_month)
);

create index if not exists idx_f29_declarations_tenant on f29_declarations(tenant_id);
create index if not exists idx_f29_declarations_period on f29_declarations(tenant_id, period_year, period_month);
create index if not exists idx_f29_declarations_status on f29_declarations(tenant_id, status);

-- Enable RLS
alter table f29_declarations enable row level security;

-- RLS Policies
drop policy if exists "f29_select" on f29_declarations;
drop policy if exists "f29_insert" on f29_declarations;
drop policy if exists "f29_update" on f29_declarations;
drop policy if exists "f29_delete" on f29_declarations;

create policy "f29_select" on f29_declarations for select to authenticated
  using (tenant_id = public.user_tenant_id());

create policy "f29_insert" on f29_declarations for insert to authenticated
  with check (tenant_id = public.user_tenant_id());

create policy "f29_update" on f29_declarations for update to authenticated
  using (tenant_id = public.user_tenant_id());

create policy "f29_delete" on f29_declarations for delete to authenticated
  using (tenant_id = public.user_tenant_id());

-- ============================================================================
-- F29 AUTO-GENERATION RPC FUNCTION
-- ============================================================================

create or replace function public.generate_f29_from_accounting(
  p_tenant_id uuid,
  p_year integer,
  p_month integer
)
returns jsonb
security definer
language plpgsql
as $$
declare
  v_start_date date;
  v_end_date date;
  v_iva_debito numeric(15,2);
  v_iva_credito numeric(15,2);
  v_ventas_netas numeric(15,2);
  v_ppm_monto numeric(15,2);
  v_retencion_honorarios numeric(15,2);
  v_retencion_segunda numeric(15,2);
  v_iva_neto numeric(15,2);
  v_total_pagar numeric(15,2);
  v_due_date date;
  v_f29_id uuid;
begin
  -- Calculate period dates
  v_start_date := make_date(p_year, p_month, 1);
  v_end_date := (v_start_date + interval '1 month' - interval '1 day')::date;

  -- Due date: 12th of following month
  v_due_date := make_date(p_year, p_month, 1) + interval '1 month 12 days' - interval '1 day';

  -- Calculate IVA Débito (Sales tax collected) - Account 2150
  -- Sum CREDIT movements (IVA débito is a liability, increases with CREDIT)
  select coalesce(sum(jl.credit_amount - jl.debit_amount), 0)
  into v_iva_debito
  from journal_lines jl
  join journal_entries je on jl.entry_id = je.id
  join accounts a on jl.account_id = a.id
  where je.tenant_id = p_tenant_id
    and a.code = '2150'
    and je.entry_date >= v_start_date
    and je.entry_date <= v_end_date
    and je.status = 'posted';

  -- Calculate IVA Crédito (Purchase tax paid) - Account 2120
  -- Sum DEBIT movements (IVA crédito is an asset, increases with DEBIT)
  select coalesce(sum(jl.debit_amount - jl.credit_amount), 0)
  into v_iva_credito
  from journal_lines jl
  join journal_entries je on jl.entry_id = je.id
  join accounts a on jl.account_id = a.id
  where je.tenant_id = p_tenant_id
    and a.code = '2120'
    and je.entry_date >= v_start_date
    and je.entry_date <= v_end_date
    and je.status = 'posted';

  -- Calculate Net Sales (Revenue) - Account 4100
  -- Sum CREDIT movements (revenue is CREDIT)
  select coalesce(sum(jl.credit_amount - jl.debit_amount), 0)
  into v_ventas_netas
  from journal_lines jl
  join journal_entries je on jl.entry_id = je.id
  join accounts a on jl.account_id = a.id
  where je.tenant_id = p_tenant_id
    and a.code = '4100'
    and je.entry_date >= v_start_date
    and je.entry_date <= v_end_date
    and je.status = 'posted';

  -- Calculate PPM (1% of net sales by default)
  -- TODO: Get tenant-specific PPM rate from settings
  v_ppm_monto := v_ventas_netas * 0.01;

  -- Calculate withholdings (if HR module tracks this)
  -- TODO: Query payroll/honorarios tables when implemented
  v_retencion_honorarios := 0;
  v_retencion_segunda := 0;

  -- Calculate net IVA (positive = owe to SII, negative = SII owes us)
  v_iva_neto := v_iva_debito - v_iva_credito;

  -- Calculate total to pay
  v_total_pagar := greatest(v_iva_neto, 0) + v_ppm_monto + v_retencion_honorarios + v_retencion_segunda;

  -- Insert or update F29 declaration
  insert into f29_declarations (
    tenant_id,
    period_month,
    period_year,
    status,
    iva_debito_ventas,
    iva_debito_total,
    iva_credito_compras,
    iva_credito_total,
    iva_neto,
    ppm_ventas_netas,
    ppm_monto,
    retencion_honorarios,
    retencion_segunda_categoria,
    total_a_pagar,
    total_a_favor,
    due_date,
    updated_at
  ) values (
    p_tenant_id,
    p_month,
    p_year,
    'draft',
    v_iva_debito,
    v_iva_debito,
    v_iva_credito,
    v_iva_credito,
    v_iva_neto,
    v_ventas_netas,
    v_ppm_monto,
    v_retencion_honorarios,
    v_retencion_segunda,
    case when v_iva_neto >= 0 then v_total_pagar else 0 end,
    case when v_iva_neto < 0 then abs(v_iva_neto) else 0 end,
    v_due_date,
    now()
  )
  on conflict (tenant_id, period_year, period_month)
  do update set
    iva_debito_ventas = excluded.iva_debito_ventas,
    iva_debito_total = excluded.iva_debito_total,
    iva_credito_compras = excluded.iva_credito_compras,
    iva_credito_total = excluded.iva_credito_total,
    iva_neto = excluded.iva_neto,
    ppm_ventas_netas = excluded.ppm_ventas_netas,
    ppm_monto = excluded.ppm_monto,
    retencion_honorarios = excluded.retencion_honorarios,
    retencion_segunda_categoria = excluded.retencion_segunda_categoria,
    total_a_pagar = excluded.total_a_pagar,
    total_a_favor = excluded.total_a_favor,
    due_date = excluded.due_date,
    updated_at = now()
  returning id into v_f29_id;

  return jsonb_build_object(
    'success', true,
    'f29_id', v_f29_id,
    'period', format('%s/%s', p_month, p_year),
    'iva_debito', v_iva_debito,
    'iva_credito', v_iva_credito,
    'iva_neto', v_iva_neto,
    'ventas_netas', v_ventas_netas,
    'ppm_monto', v_ppm_monto,
    'total_a_pagar', v_total_pagar
  );
end;
$$;

grant execute on function public.generate_f29_from_accounting(uuid, integer, integer) to authenticated;

-- ============================================================================
-- ENHANCED HR MODULE - MEDICAL LEAVES (LICENCIAS MÉDICAS)
-- ============================================================================

-- Medical leaves (doctor notes / licencias médicas)
create table if not exists medical_leaves (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade not null,
  employee_id uuid references employees(id) on delete cascade not null,

  -- Leave details
  leave_type text not null check (leave_type in (
    'enfermedad_comun', -- Common illness
    'accidente_trabajo', -- Work accident
    'enfermedad_profesional', -- Occupational disease
    'maternal', -- Maternity leave
    'paternal', -- Paternity leave
    'pre_post_natal' -- Pre/post natal
  )),

  -- Dates
  start_date date not null,
  end_date date not null,
  days_count integer generated always as (end_date - start_date + 1) stored,

  -- Medical certificate
  certificate_number text, -- Folio de licencia médica
  doctor_name text,
  doctor_rut text,
  issuing_institution text, -- COMPIN, IST, Mutual, etc.

  -- Status
  status text not null check (status in (
    'pending', -- Waiting approval
    'approved', -- Approved by COMPIN/IST
    'rejected', -- Rejected
    'paid' -- Subsidy paid
  )) default 'pending',

  -- Financial
  daily_subsidy_amount numeric(10,2), -- Subsidio diario
  total_subsidy_amount numeric(10,2), -- Total subsidy
  paid_by text check (paid_by in ('employer', 'mutual', 'isapre', 'fonasa')),
  paid_at timestamp with time zone,

  -- Attachments
  certificate_url text, -- Scanned medical certificate
  approval_url text, -- COMPIN/IST approval

  -- Notes
  diagnosis text,
  notes text,

  -- Metadata
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now()
);

create index if not exists idx_medical_leaves_tenant on medical_leaves(tenant_id);
create index if not exists idx_medical_leaves_employee on medical_leaves(employee_id);
create index if not exists idx_medical_leaves_dates on medical_leaves(start_date, end_date);
create index if not exists idx_medical_leaves_status on medical_leaves(tenant_id, status);

alter table medical_leaves enable row level security;

drop policy if exists "medical_leaves_select" on medical_leaves;
drop policy if exists "medical_leaves_insert" on medical_leaves;
drop policy if exists "medical_leaves_update" on medical_leaves;
drop policy if exists "medical_leaves_delete" on medical_leaves;

create policy "medical_leaves_select" on medical_leaves for select to authenticated
  using (tenant_id = public.user_tenant_id());

create policy "medical_leaves_insert" on medical_leaves for insert to authenticated
  with check (tenant_id = public.user_tenant_id());

create policy "medical_leaves_update" on medical_leaves for update to authenticated
  using (tenant_id = public.user_tenant_id());

create policy "medical_leaves_delete" on medical_leaves for delete to authenticated
  using (tenant_id = public.user_tenant_id());

