  end if;

  -- Online Order Items
  if v_backup_data ? 'online_order_items' and v_backup_data->'online_order_items' is not null and jsonb_typeof(v_backup_data->'online_order_items') = 'array' then
    insert into online_order_items select * from jsonb_populate_recordset(null::online_order_items, v_backup_data->'online_order_items');
    v_tables_restored := v_tables_restored + 1;
  end if;

  -- Update backup record
  update database_backups
  set status = 'restored',
      restored_at = now(),
      restored_by = auth.uid()
  where id = p_backup_id;

  return jsonb_build_object(
    'success', true,
    'backup_id', p_backup_id,
    'tables_restored', v_tables_restored,
    'summary', v_summary
  );
exception
  when others then
    return jsonb_build_object(
      'success', false,
      'error', SQLERRM
    );
end;
$$;

grant execute on function public.restore_backup(uuid, uuid) to authenticated;

-- Function: Get backup summary without loading full data
create or replace function public.get_backup_summary(p_backup_id uuid)
returns jsonb
security definer
language plpgsql
as $$
declare
  v_result jsonb;
begin
  select jsonb_build_object(
    'id', id,
    'backup_name', backup_name,
    'backup_type', backup_type,
    'status', status,
    'summary', summary,
    'size_mb', round((backup_size_bytes / 1024.0 / 1024.0)::numeric, 2),
    'created_at', created_at,
    'created_by', created_by,
    'notes', notes
  ) into v_result
  from database_backups
  where id = p_backup_id;

  return v_result;
end;
$$;

grant execute on function public.get_backup_summary(uuid) to authenticated;

-- Function: Delete old backups based on retention policy
create or replace function public.cleanup_old_backups(p_tenant_id uuid)
returns jsonb
security definer
language plpgsql
as $$
declare
  v_keep_count int;
  v_auto_delete boolean;
  v_deleted_count int := 0;
  v_backup_ids uuid[];
begin
  -- Get retention settings
  select keep_last_n_backups, auto_delete_old
  into v_keep_count, v_auto_delete
  from backup_schedules
  where tenant_id = p_tenant_id;

  if not found or not v_auto_delete then
    return jsonb_build_object('success', true, 'deleted_count', 0, 'message', 'Auto-delete disabled');
  end if;

  -- Get IDs of backups to delete (keep newest N, delete older)
  select array_agg(id) into v_backup_ids
  from (
    select id
    from database_backups
    where tenant_id = p_tenant_id
      and status = 'completed'
      and backup_type in ('automatic', 'scheduled')
    order by created_at desc
    offset v_keep_count
  ) old_backups;

  if v_backup_ids is not null then
    delete from database_backups
    where id = any(v_backup_ids);

    get diagnostics v_deleted_count = row_count;
  end if;

  return jsonb_build_object(
    'success', true,
    'deleted_count', v_deleted_count,
    'kept_count', v_keep_count,
    'scope', 'automatic_and_scheduled_only'
  );
end;
$$;

grant execute on function public.cleanup_old_backups(uuid) to authenticated;

-- ============================================================
-- DOCUMENT NUMBERING SYSTEM
-- Sequential human-friendly numbers for all document types
-- ============================================================

-- Table: document_sequences
-- Stores last used number for each document type per tenant
create table if not exists document_sequences (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade not null,
  document_type text not null, -- 'sales_invoice', 'purchase_invoice', 'journal_entry', etc.
  last_number integer not null default 0,
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  unique(tenant_id, document_type)
);

create index if not exists idx_document_sequences_tenant on document_sequences(tenant_id);

-- RLS for document_sequences
alter table document_sequences enable row level security;

drop policy if exists "document_sequences_select" on document_sequences;
drop policy if exists "document_sequences_insert" on document_sequences;
drop policy if exists "document_sequences_update" on document_sequences;

create policy "document_sequences_select" on document_sequences
  for select to authenticated
  using (tenant_id = public.user_tenant_id());

create policy "document_sequences_insert" on document_sequences
  for insert to authenticated
  with check (tenant_id = public.user_tenant_id());

create policy "document_sequences_update" on document_sequences
  for update to authenticated
  using (tenant_id = public.user_tenant_id());

-- Function: get_next_document_number
-- Generates next sequential number for a document type
-- Format: PREFIX-NNNN (e.g., FV-0143)
create or replace function public.get_next_document_number(
  p_tenant_id uuid,
  p_document_type text,
  p_prefix text default null
) returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_tenant_id uuid;
  v_next_number integer;
  v_max_existing integer := 0;
  v_max_journal_reference integer := 0;
  v_prefix text;
  v_table_name text;
  v_column_name text;
  v_formatted_number text;
begin
  v_actor_tenant_id := public.user_tenant_id();

  if auth.uid() is not null then
    if v_actor_tenant_id is null then
      raise exception 'Could not resolve tenant for authenticated user';
    end if;

    if p_tenant_id is null or p_tenant_id <> v_actor_tenant_id then
      raise exception 'Cross-tenant document sequence access is not allowed';
    end if;
  end if;

  -- Default prefixes if not provided
  v_prefix := coalesce(p_prefix, case p_document_type
    when 'sales_invoice' then 'FV'
    when 'purchase_invoice' then 'FC'
    when 'sales_payment' then 'PV'
    when 'purchase_payment' then 'PC'
    when 'journal_entry' then 'AC'
    when 'mechanic_job' then 'PG'
    when 'stock_adjustment' then 'AJ'
    when 'expense' then 'GTO'
    else 'DOC'
  end);

  case p_document_type
    when 'sales_invoice' then
      v_table_name := 'sales_invoices';
      v_column_name := 'invoice_number';
    when 'purchase_invoice' then
      v_table_name := 'purchase_invoices';
      v_column_name := 'invoice_number';
    when 'sales_payment' then
      v_table_name := 'sales_payments';
      v_column_name := 'payment_number';
    when 'purchase_payment' then
      v_table_name := 'purchase_payments';
      v_column_name := 'payment_number';
    when 'journal_entry' then
      v_table_name := 'journal_entries';
      v_column_name := 'entry_number';
    when 'mechanic_job' then
      v_table_name := 'mechanic_jobs';
      v_column_name := 'job_number';
    when 'stock_adjustment' then
      v_table_name := 'stock_adjustments';
      v_column_name := 'reference';
    when 'expense' then
      v_table_name := 'expenses';
      v_column_name := 'expense_number';
    else
      v_table_name := null;
      v_column_name := null;
  end case;

  -- Self-heal stale sequence rows by never issuing a number below the real max
  if v_table_name is not null and v_column_name is not null then
    execute format(
      'select coalesce(max((substring(%1$I from ''([0-9]+)$''))::integer), 0)
         from public.%2$I
        where tenant_id = $1
          and %1$I ~ $2',
      v_column_name,
      v_table_name
    )
    into v_max_existing
    using p_tenant_id, '^' || v_prefix || '-[0-9]+$';
  end if;

  if p_document_type = 'expense' then
    select coalesce(
      max((substring(entry.source_reference from '([0-9]+)$'))::integer),
      0
    )
    into v_max_journal_reference
    from public.journal_entries entry
    where entry.tenant_id = p_tenant_id
      and entry.source_module = 'expenses'
      and entry.source_reference ~ ('^' || v_prefix || '-[0-9]+$');

    v_max_existing := greatest(v_max_existing, v_max_journal_reference);
  end if;

  -- Insert or update sequence (atomic operation)
  insert into document_sequences (tenant_id, document_type, last_number)
  values (p_tenant_id, p_document_type, greatest(v_max_existing, 0) + 1)
  on conflict (tenant_id, document_type)
  do update set
    last_number = greatest(document_sequences.last_number, v_max_existing) + 1,
    updated_at = now()
  returning last_number into v_next_number;

  -- Format: PREFIX-NNNNN (e.g., FV-00143)
  v_formatted_number := v_prefix || '-' || lpad(v_next_number::text, 5, '0');

  return v_formatted_number;
end;
$$;

grant execute on function public.get_next_document_number(uuid, text, text) to authenticated;

-- Function: preview_next_document_number
-- Returns what the NEXT number would be, WITHOUT incrementing
-- Used for form previews - number is only "consumed" when actually saving
create or replace function public.preview_next_document_number(
  p_tenant_id uuid,
  p_document_type text,
  p_prefix text default null
) returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_tenant_id uuid;
  v_current_number integer;
  v_max_existing integer := 0;
  v_max_journal_reference integer := 0;
  v_next_number integer;
  v_prefix text;
  v_table_name text;
  v_column_name text;
  v_formatted_number text;
begin
  v_actor_tenant_id := public.user_tenant_id();

  if auth.uid() is not null then
    if v_actor_tenant_id is null then
      raise exception 'Could not resolve tenant for authenticated user';
    end if;

    if p_tenant_id is null or p_tenant_id <> v_actor_tenant_id then
      raise exception 'Cross-tenant document sequence access is not allowed';
    end if;
  end if;

  -- Default prefixes if not provided
  v_prefix := coalesce(p_prefix, case p_document_type
    when 'sales_invoice' then 'FV'
    when 'purchase_invoice' then 'FC'
    when 'sales_payment' then 'PV'
    when 'purchase_payment' then 'PC'
    when 'journal_entry' then 'AC'
    when 'mechanic_job' then 'PG'
    when 'stock_adjustment' then 'AJ'
    when 'expense' then 'GTO'
    else 'DOC'
  end);

  case p_document_type
    when 'sales_invoice' then
      v_table_name := 'sales_invoices';
      v_column_name := 'invoice_number';
    when 'purchase_invoice' then
      v_table_name := 'purchase_invoices';
      v_column_name := 'invoice_number';
    when 'sales_payment' then
      v_table_name := 'sales_payments';
      v_column_name := 'payment_number';
    when 'purchase_payment' then
      v_table_name := 'purchase_payments';
      v_column_name := 'payment_number';
    when 'journal_entry' then
      v_table_name := 'journal_entries';
      v_column_name := 'entry_number';
    when 'mechanic_job' then
      v_table_name := 'mechanic_jobs';
      v_column_name := 'job_number';
    when 'stock_adjustment' then
      v_table_name := 'stock_adjustments';
      v_column_name := 'reference';
    when 'expense' then
      v_table_name := 'expenses';
      v_column_name := 'expense_number';
    else
      v_table_name := null;
      v_column_name := null;
  end case;

  if v_table_name is not null and v_column_name is not null then
    execute format(
      'select coalesce(max((substring(%1$I from ''([0-9]+)$''))::integer), 0)
         from public.%2$I
        where tenant_id = $1
          and %1$I ~ $2',
      v_column_name,
      v_table_name
    )
    into v_max_existing
    using p_tenant_id, '^' || v_prefix || '-[0-9]+$';
  end if;

  if p_document_type = 'expense' then
    select coalesce(
      max((substring(entry.source_reference from '([0-9]+)$'))::integer),
      0
    )
    into v_max_journal_reference
    from public.journal_entries entry
    where entry.tenant_id = p_tenant_id
      and entry.source_module = 'expenses'
      and entry.source_reference ~ ('^' || v_prefix || '-[0-9]+$');

    v_max_existing := greatest(v_max_existing, v_max_journal_reference);
  end if;

  -- Get current sequence value (or 0 if none)
  select coalesce(last_number, 0) into v_current_number
  from document_sequences
  where tenant_id = p_tenant_id and document_type = p_document_type;

  -- Preview should never suggest a number below the real max already in use
  v_next_number := greatest(coalesce(v_current_number, 0), coalesce(v_max_existing, 0)) + 1;

  -- Format: PREFIX-NNNNN (e.g., FV-00143)
  v_formatted_number := v_prefix || '-' || lpad(v_next_number::text, 5, '0');

  return v_formatted_number;
end;
$$;

grant execute on function public.preview_next_document_number(uuid, text, text) to authenticated;

-- Deleted legacy expenses can leave valid journal evidence behind. Keep the
-- expense sequence above those preserved references so they are never reused.
with journal_maximums as (
  select
    entry.tenant_id,
    max((substring(entry.source_reference from '([0-9]+)$'))::integer)
      as max_number
  from public.journal_entries entry
  where entry.source_module = 'expenses'
    and entry.source_reference ~ '^GTO-[0-9]+$'
  group by entry.tenant_id
)
update public.document_sequences sequence
set last_number = greatest(sequence.last_number, maximum.max_number),
    updated_at = now()
from journal_maximums maximum
where sequence.tenant_id = maximum.tenant_id
  and sequence.document_type = 'expense'
  and sequence.last_number < maximum.max_number;

comment on function public.get_next_document_number(uuid, text, text) is
  'Issues tenant-scoped document numbers and prevents expense references from colliding with preserved expense journals.';
comment on function public.preview_next_document_number(uuid, text, text) is
  'Previews tenant-scoped document numbers, including preserved expense journal references in the high-water mark.';

