-- Keep the tenant-scoped expense dashboard RPC authenticated-only even when
-- hosted Supabase default privileges directly grant new functions to API roles.
\ir ../migrations/20260716100000_restrict_expense_period_details_acl.sql
\ir ../migrations/20260716110000_add_mechanic_job_sale_collection_mode.sql
\ir ../migrations/20260716111000_classify_pg00465_sale_collection.sql
-- Protect the authoritative job when a linked draft invoice is deleted from
-- Sales, and freeze the received-bike aggregate after a proposal decision.
\ir ../migrations/20260717010000_protect_linked_workshop_invoice_deletion.sql
-- Prevent approval of an empty workshop proposal; the immutable approval
-- snapshot must contain at least one product or service line.
\ir ../migrations/20260717020000_require_quotation_items_before_approval.sql
-- Approved standalone product quotations become sale/none wrappers and one
-- linked invoice without inventing workshop intake.
\ir ../migrations/20260717030000_convert_approved_quotation_to_sale.sql
-- Strategic dashboard: auditable workshop flow, capacity, service/product
-- economics, inventory movement, and explicit actual labor-hour capture.
\ir ../migrations/20260717040000_add_strategic_workshop_metrics.sql
-- Expense headers, lines, payments, accrual journals, and payment journals
-- share the same operation/checkpoint trace without rewriting history.
\ir ../migrations/20260717050000_trace_expense_accounting_operations.sql
-- Provenance-aware workshop lifecycle metrics and explicit product/service/
-- unclassified sales separation. Historical job rows are not rewritten.
\ir ../migrations/20260717060000_rebuild_workshop_time_metrics.sql
-- Prevent preserved legacy expense journals from colliding with newly issued
-- GTO numbers and make UUID document lineage authoritative in expense traces.
\ir ../migrations/20260717080000_prevent_expense_number_journal_collisions.sql
-- Atomic, idempotent simple-expense edits with optimistic concurrency,
-- integer CLP tax rounding, and immutable superseded-journal evidence.
\ir ../migrations/20260718090000_add_atomic_expense_edit.sql
-- Preserve the original posting audit timestamp across the RPC draft bridge.
\ir ../migrations/20260718091000_preserve_expense_posted_at_on_atomic_edit.sql
-- Non-workshop invoices, including anonymous ecommerce transfer invoices, must
-- bypass workshop synchronization before its authenticated actor assertion.
\ir ../migrations/20260718120000_gate_workshop_invoice_sync_by_link.sql
-- Canonical online-order lifecycle: tenant/year numbering, public checkout
-- price/stock truth, prospective product snapshots, optimistic replay-safe
-- transitions, append-only event receipts, protected mutation boundaries, and
-- tenant-scoped invoice SKU resolution.
\ir ../migrations/20260718130000_harden_online_order_lifecycle.sql
-- Delivery-safe transactional order communications: immutable event-derived
-- outbox, dry-run-first Resend worker contract, signed provider evidence,
-- recipient suppressions, and redacted guest access tokens. Payment status,
-- official payment voucher, and SII/DTE document evidence remain distinct.
\ir ../migrations/20260718140000_add_transactional_order_email_foundation.sql
-- Official online-order artifacts remain a separate append-only legal-evidence
-- boundary. Only complete Mercado Pago vouchers or issued/accepted Chilean DTEs
-- can enqueue the corresponding transactional document email.
\ir ../migrations/20260718150000_add_online_order_official_document_ledger.sql
-- Unpaid standalone invoices can be discarded without physical deletion:
-- stock, journal evidence, status, actor and reason remain atomically linked.
\ir ../migrations/20260718160000_add_atomic_sales_invoice_discard.sql
-- Public order UUIDs are identifiers, never bearer credentials. Checkout now
-- returns a hashed/expiring access token atomically; confirmation and Mercado
-- Pago authorization consume only its redacted projection.
\ir ../migrations/20260718170000_secure_public_order_access.sql
-- A Mercado Pago voucher is valid as a boleta only when a separately verified
-- tenant SII emission-model declaration and every prescribed fiscal field are
-- bound into immutable evidence. No tenant is configured or backfilled here.
\ir ../migrations/20260718180000_harden_mercadopago_voucher_fiscal_evidence.sql
-- Provider truth commits before derived sale effects. Mercado Pago retries are
-- replay-safe; paid orders that cannot yet reconcile stock/invoice/accounting
-- remain explicitly action_required with append-only processing evidence.
\ir ../migrations/20260718190000_split_mercadopago_payment_processing.sql
-- Ecommerce tax classification follows each immutable product-line snapshot,
-- never the payment rail. Gross CLP prices split into per-line net/IVA and
-- unclassified or historically inconsistent pending rows fail closed.
\ir ../migrations/20260718200000_fix_online_order_tax_classification.sql
-- Paid-order correction saga: durable Mercado Pago/manual refund evidence is
-- committed before replay-safe atomic return, credit-note and refund-ledger
-- effects. Also replace the legacy global order-number key with tenant scope.
\ir ../migrations/20260718210000_add_online_order_correction_workflow.sql
-- Every current/future product tax classification receives immutable
-- provenance. The exact audited public Viñabike batch applies only when its
-- no-PII membership and commercial snapshot hashes still match.
\ir ../migrations/20260718220000_apply_curated_product_tax_classification.sql
-- Verified Viñabike sender identity plus a fail-closed pg_cron/pg_net worker.
-- The scheduler is installed disabled, requires explicit dry-run acceptance
-- before send, re-checks recipient suppressions at claim time, and reconciles
-- signed provider events that race the worker acknowledgement.
\ir ../migrations/20260718230000_prepare_transactional_email_delivery.sql
-- Push notifications use a dedicated Vault/Edge shared secret. The message
-- trigger contains no bearer JWT, and the Edge Function rejects unauthenticated
-- callers before reading the request body.
\ir ../migrations/20260718240000_secure_push_notification_webhook.sql
\ir ../migrations/20260718250000_sync_storefront_sales_contact.sql
-- A claimed Mercado Pago voucher must match the exact sanitized provider card
-- evidence. Payments API redirects/tickets/3DS resources never qualify as an
-- official artifact, and `approved` alone remains non-fiscal.
\ir ../migrations/20260718260000_bind_mercadopago_voucher_to_provider_evidence.sql
-- Public storefront settings keep only their non-sensitive projection. Legacy
-- permissive policies and destructive API-role grants are removed so provider
-- tokens and future credentials remain service-role only.
\ir ../migrations/20260718270000_harden_website_settings_secret_access.sql
-- Public checkout and confirmation use tokenized SECURITY DEFINER RPCs.
-- Direct order/order-line table access is removed from anon, and authenticated
-- sessions retain only RLS-governed reads; all mutation paths stay audited.
\ir ../migrations/20260718280000_close_direct_public_online_order_reads.sql
-- Unpaid online checkout reserves available physical inventory without moving
-- stock. Cancellation/expiry releases it; invoice posting converts the exact
-- commitment to append-only, movement-linked consumption evidence. Product
-- sets reserve components and public catalog availability subtracts live
-- commitments.
\ir ../migrations/20260718290000_add_online_inventory_reservations.sql
-- Public checkout, legal pages and Google Merchant use the same server-side
-- gross-CLP shipping tariff. The immutable order snapshot separates shipping
-- net/IVA from product amounts and rejects overlapping rate ranges.
\ir ../migrations/20260718300000_align_merchant_transparency_and_online_shipping.sql
-- Public order creation re-prices products and shipping inside the database,
-- rejects stale browser consent, and posts shipping as a taxable non-stock
-- invoice line without fabricating an inventory movement.
\ir ../migrations/20260718300010_apply_authoritative_online_shipping_quote.sql
-- Checkout Pro preferences are durable, replay-safe provider resources. Their
-- lifetime is bounded by the authoritative inventory reservation, and paid or
-- cancelled orders queue every remaining link for provider-side expiration.
\ir ../migrations/20260718310000_harden_mercadopago_preference_lifecycle.sql
-- Approved provider truth may include a credential-free Mercado Pago payment
-- receipt. Record and email it as explicitly non-fiscal; never weaken the
-- separately verified SII voucher-as-boleta path.
\ir ../migrations/20260718320000_produce_mercadopago_payment_voucher.sql
-- Messaging access is tenant-scoped, internal chats are participant-scoped,
-- webhook evidence is API-append-only, and provider status replay is monotonic.
\ir ../migrations/20260719120000_harden_messaging_access.sql
-- Messaging attachments use a private tenant/conversation registry, verified
-- runtime signing and replay-safe publication; legacy public objects migrate
-- through guarded service-only maintenance commands.
\ir ../migrations/20260719163000_private_messaging_attachments.sql
-- Read receipts are bounded by exact visible-message evidence; customer,
-- staff-support, internal/group and WhatsApp creation are atomic/idempotent.
-- Participant, customer-binding and retained-context identity stay immutable;
-- unsafe legacy supplier recipient edges are removed with append-only audit.
\ir ../migrations/20260719210000_atomic_messaging_commands.sql
-- The retained primary context ledger is authoritative over the legacy scalar
-- projection. Repair legacy drift without changing business timestamps, then
-- enforce exact scalar/primary equivalence at transaction commit.
\ir ../migrations/20260719213000_reconcile_conversation_context_projection.sql
-- Legacy context/session and trigger helpers retain their definitions for
-- owner-controlled SQL, but their effective ACLs contain no PUBLIC or named
-- non-owner grantee. Product stock imports use the audited canonical command.
\ir ../migrations/20260719214000_harden_legacy_internal_rpcs.sql
-- The authenticated expense rebuild proves the source tenant before
-- delegating to a retained owner-only implementation. Journal create/delete
-- compatibility names are service/trigger-only, closing direct employee UUID
-- mutations while preserving database-trigger behavior.
\ir ../migrations/20260719215000_harden_expense_journal_rpc_tenant_scope.sql
-- The production diagnostic reader is sealed as NOLOGIN with no password or
-- inheritable/settable memberships. It retains table SELECT evidence only;
-- explicit/default routine execution is removed without changing any other
-- grantee's ACL. A Supabase-owned non-SET/non-INHERIT admin edge may remain.
\ir ../migrations/20260719216000_harden_diagnostic_role_identity_acl.sql
-- Finalize the complete expense journal RPC boundary under a fresh immutable
-- version. This also makes payment-journal cleanup safe when an expense DELETE
-- cascades over payments after the parent row is no longer visible.
\ir ../migrations/20260719217000_finalize_expense_journal_rpc_hardening.sql
-- Exact supplier/listing identity survives OCR review, supplier-code matches
-- never cross supplier boundaries, and AE SKUs are globally serialized with
-- tenant-scoped replay receipts.
\ir ../migrations/20260721013000_add_supplier_product_aliases_and_sku_reservations.sql
-- Product-set composition is one tenant-scoped aggregate. Physical stock
-- belongs to canonical components, set headers remain virtual, and the exact
-- legacy Viñabike graph/AE0368 omission are repaired only behind immutable
-- production fingerprints and append-only inventory trace evidence.
\ir ../migrations/20260721190000_canonicalize_product_set_inventory.sql
-- Instagram professional and Facebook Page messaging share the canonical
-- support inbox. Credentials remain Vault-only; webhook/send evidence is
-- tenant-scoped, replay-safe and limited to the standard reply window.
-- Deployment status: DEPLOYED AND VERIFIED (2026-07-21, project xzdvtzdqjeyqxnkqprtf).
--
-- Add a tenant-scoped Meta transport for Instagram professional accounts and
-- Facebook Pages. Webhook evidence and outbound attempts are durable; access
-- tokens live only in Supabase Vault and are never exposed to authenticated
-- clients. The first delivery slice accepts inbound text/media placeholders,
-- comments/mentions, provider read/delivery evidence, and outbound text inside
-- the standard 24-hour reply window.
--
-- Forward plan:
--   * extend canonical conversation/message provider constraints;
--   * add tenant-owned channel, binding, webhook and send-attempt ledgers;
--   * add one-time OAuth state plus Vault-backed credential commands;
--   * add service-only webhook/send RPCs with replay-safe receipts.
--
-- Recovery plan:
--   Roll back Edge Functions and client callers while retaining all additive
--   tables and provider evidence. Do not delete webhook/send history or Vault
--   secrets. A forward migration may deactivate channels or replace RPC bodies.

begin;

set local lock_timeout = '5s';
set local statement_timeout = '90s';

do $$
begin
  if to_regclass('public.conversations') is null
     or to_regclass('public.messages') is null
     or to_regclass('public.erp_notifications') is null then
    raise exception 'Messaging and ERP notification foundations are required';
  end if;

  if not exists (
    select 1 from pg_extension where extname = 'supabase_vault'
  ) then
    raise exception 'Supabase Vault is required for Meta credentials';
  end if;
end;
$$;

-- Keep the base messaging aggregate canonical. Existing values are retained;
-- only the supported provider vocabulary expands.
alter table public.conversations
  drop constraint if exists conversations_channel_check;
alter table public.conversations
  add constraint conversations_channel_check
  check (
    channel in (
      'internal',
      'website_portal',
      'whatsapp',
      'instagram',
      'facebook_messenger'
    )
  );

alter table public.conversations
  drop constraint if exists conversations_type_channel_check;
alter table public.conversations
  add constraint conversations_type_channel_check
  check (
    (type = 'internal' and channel = 'internal')
    or (
      type = 'support'
      and channel in (
        'website_portal',
        'whatsapp',
        'instagram',
        'facebook_messenger'
      )
    )
  );

alter table public.messages
  drop constraint if exists messages_external_provider_check;
alter table public.messages
  add constraint messages_external_provider_check
  check (
    external_provider in (
      'whatsapp',
      'instagram',
      'facebook_messenger'
    )
    or external_provider is null
  );

create or replace function public.normalize_conversation_channel()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if new.type = 'internal' then
    new.channel := 'internal';
  elsif new.channel is null or new.channel = 'internal' then
    new.channel := 'website_portal';
  end if;

  return new;
end;
$$;

create table if not exists public.meta_channels (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  provider text not null
    check (provider in ('instagram', 'facebook_messenger')),
  external_account_id text not null,
  display_name text,
  username text,
  granted_scopes text[] not null default '{}'::text[],
  token_expires_at timestamptz,
  subscribed_at timestamptz,
  is_active boolean not null default true,
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  unique(provider, external_account_id),
  unique(tenant_id, provider, external_account_id)
);

create table if not exists public.meta_channel_credentials (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  channel_id uuid not null references public.meta_channels(id) on delete restrict,
  vault_secret_id uuid not null,
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  unique(channel_id)
);

comment on table public.meta_channel_credentials is
  'Service-only references to Supabase Vault secrets; no provider token is stored in public tables.';

create table if not exists public.meta_conversation_bindings (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  channel_id uuid not null references public.meta_channels(id) on delete restrict,
  conversation_id uuid not null references public.conversations(id) on delete restrict,
  external_user_id text not null,
  contact_name text,
  username text,
  last_inbound_at timestamptz,
  last_outbound_at timestamptz,
  reply_window_expires_at timestamptz,
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  unique(channel_id, external_user_id),
  unique(channel_id, conversation_id)
);

create table if not exists public.meta_webhook_events (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  channel_id uuid not null references public.meta_channels(id) on delete restrict,
  event_key text not null,
  event_type text not null check (
    event_type in (
      'message',
      'message_echo',
      'message_status',
      'comment',
      'mention',
      'unknown'
    )
  ),
  direction text not null default 'system'
    check (direction in ('inbound', 'outbound', 'system')),
  occurred_at timestamptz,
  conversation_id uuid references public.conversations(id) on delete set null,
  message_id uuid references public.messages(id) on delete set null,
  external_user_id text,
  external_message_id text,
  external_object_id text,
  payload jsonb not null default '{}'::jsonb,
  processed_at timestamptz not null default clock_timestamp(),
  created_at timestamptz not null default clock_timestamp(),
  unique(channel_id, event_key)
);

comment on column public.meta_webhook_events.payload is
  'Sanitized identifiers and previews only; provider tokens and remote media URLs are forbidden.';

create table if not exists public.meta_outbound_send_attempts (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  actor_id uuid not null references auth.users(id) on delete restrict,
  channel_id uuid not null references public.meta_channels(id) on delete restrict,
  binding_id uuid not null references public.meta_conversation_bindings(id) on delete restrict,
  conversation_id uuid not null references public.conversations(id) on delete restrict,
  idempotency_key text not null,
  request_fingerprint text not null,
  message_text text not null,
  state text not null default 'prepared' check (
    state in (
      'prepared',
      'preflight_failed',
      'provider_accepted',
      'finalized',
      'provider_rejected',
      'outcome_unknown'
    )
  ),
  external_message_id text,
  message_id uuid references public.messages(id) on delete set null,
  provider_accepted_at timestamptz,
  finalized_at timestamptz,
  error_code text,
  error_message text,
  provider_response jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  unique(tenant_id, idempotency_key)
);

alter table public.meta_outbound_send_attempts
  drop constraint if exists meta_outbound_send_attempts_state_check;
alter table public.meta_outbound_send_attempts
  add constraint meta_outbound_send_attempts_state_check check (
    state in (
      'prepared',
      'preflight_failed',
      'provider_accepted',
      'finalized',
      'provider_rejected',
      'outcome_unknown'
    )
  );

create table if not exists public.meta_oauth_states (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  actor_id uuid not null references auth.users(id) on delete cascade,
  state_hash text not null unique,
  redirect_uri text not null,
  expires_at timestamptz not null,
  consumed_at timestamptz,
  created_at timestamptz not null default clock_timestamp(),
  check (length(state_hash) = 64),
  check (expires_at > created_at)
);

create index if not exists idx_meta_channels_tenant_active
  on public.meta_channels(tenant_id, provider, is_active);
create index if not exists idx_meta_bindings_tenant_conversation
  on public.meta_conversation_bindings(tenant_id, conversation_id);
create index if not exists idx_meta_bindings_reply_window
  on public.meta_conversation_bindings(tenant_id, reply_window_expires_at)
  where reply_window_expires_at is not null;
create index if not exists idx_meta_events_tenant_created
  on public.meta_webhook_events(tenant_id, created_at desc);
create index if not exists idx_meta_events_external_message
  on public.meta_webhook_events(channel_id, external_message_id)
  where external_message_id is not null;
create index if not exists idx_meta_attempts_tenant_created
  on public.meta_outbound_send_attempts(tenant_id, created_at desc);
create index if not exists idx_meta_attempts_conversation_created
  on public.meta_outbound_send_attempts(
    tenant_id,
    conversation_id,
    created_at desc
  );
create index if not exists idx_meta_oauth_states_expiry
  on public.meta_oauth_states(expires_at)
  where consumed_at is null;

alter table public.meta_channels enable row level security;
alter table public.meta_channel_credentials enable row level security;
alter table public.meta_conversation_bindings enable row level security;
alter table public.meta_webhook_events enable row level security;
alter table public.meta_outbound_send_attempts enable row level security;
alter table public.meta_oauth_states enable row level security;

drop policy if exists meta_channels_staff_select on public.meta_channels;
create policy meta_channels_staff_select
  on public.meta_channels for select to authenticated
  using (public.messaging_is_staff_in_tenant(tenant_id));

drop policy if exists meta_bindings_staff_select
  on public.meta_conversation_bindings;

drop policy if exists meta_events_staff_select on public.meta_webhook_events;

revoke all on table public.meta_channels
  from public, anon, authenticated, service_role;
revoke all on table public.meta_channel_credentials
  from public, anon, authenticated, service_role;
revoke all on table public.meta_conversation_bindings
  from public, anon, authenticated, service_role;
revoke all on table public.meta_webhook_events
  from public, anon, authenticated, service_role;
revoke all on table public.meta_outbound_send_attempts
  from public, anon, authenticated, service_role;
revoke all on table public.meta_oauth_states
  from public, anon, authenticated, service_role;

grant select on table public.meta_channels to authenticated;
grant select, insert, update on table public.meta_channels to service_role;
grant select, insert, update on table public.meta_channel_credentials to service_role;
grant select, insert, update on table public.meta_conversation_bindings to service_role;
grant select, insert, update on table public.meta_webhook_events to service_role;
grant select, insert, update on table public.meta_outbound_send_attempts to service_role;
grant select, insert, update on table public.meta_oauth_states to service_role;

drop trigger if exists trg_meta_channels_updated_at on public.meta_channels;
create trigger trg_meta_channels_updated_at
  before update on public.meta_channels
  for each row execute function public.set_updated_at();

drop trigger if exists trg_meta_credentials_updated_at
  on public.meta_channel_credentials;
create trigger trg_meta_credentials_updated_at
  before update on public.meta_channel_credentials
  for each row execute function public.set_updated_at();

drop trigger if exists trg_meta_bindings_updated_at
  on public.meta_conversation_bindings;
create trigger trg_meta_bindings_updated_at
  before update on public.meta_conversation_bindings
  for each row execute function public.set_updated_at();

drop trigger if exists trg_meta_attempts_updated_at
  on public.meta_outbound_send_attempts;
create trigger trg_meta_attempts_updated_at
  before update on public.meta_outbound_send_attempts
  for each row execute function public.set_updated_at();

create or replace function public.enforce_meta_tenant_consistency()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_channel public.meta_channels%rowtype;
  v_conversation public.conversations%rowtype;
  v_binding public.meta_conversation_bindings%rowtype;
  v_message public.messages%rowtype;
begin
  if tg_op = 'UPDATE' and new.tenant_id is distinct from old.tenant_id then
    raise exception 'Meta tenant_id is immutable' using errcode = '23514';
  end if;

  if tg_table_name = 'meta_channels' then
    if tg_op = 'UPDATE' and (
      new.provider is distinct from old.provider
      or new.external_account_id is distinct from old.external_account_id
    ) then
      raise exception 'Meta provider account identity is immutable'
        using errcode = '23514';
    end if;
    return new;
  end if;

  if tg_table_name = 'meta_oauth_states' then
    if not exists (
      select 1
      from public.user_profiles profile
      where profile.user_id = new.actor_id
        and profile.tenant_id = new.tenant_id
        and coalesce(profile.is_active, true)
    ) then
      raise exception 'Meta OAuth actor does not belong to tenant'
        using errcode = '23514';
    end if;
    if tg_op = 'UPDATE' and (
      new.actor_id is distinct from old.actor_id
      or new.state_hash is distinct from old.state_hash
      or new.redirect_uri is distinct from old.redirect_uri
      or new.expires_at is distinct from old.expires_at
      or new.created_at is distinct from old.created_at
    ) then
      raise exception 'Meta OAuth state evidence is immutable'
        using errcode = '23514';
    end if;
    return new;
  end if;

  select channel.* into v_channel
  from public.meta_channels channel
  where channel.id = new.channel_id;

  if not found or v_channel.tenant_id is distinct from new.tenant_id then
    raise exception 'Meta channel must belong to row tenant'
      using errcode = '23514';
  end if;

  if tg_op = 'UPDATE' and new.channel_id is distinct from old.channel_id then
    raise exception 'Meta channel binding is immutable' using errcode = '23514';
  end if;

  if tg_table_name = 'meta_channel_credentials' then
    return new;
  end if;

  if new.conversation_id is not null then
    select conversation.* into v_conversation
    from public.conversations conversation
    where conversation.id = new.conversation_id;

    if not found
       or v_conversation.tenant_id is distinct from new.tenant_id
       or v_conversation.type <> 'support'
       or v_conversation.channel is distinct from v_channel.provider then
      raise exception 'Meta conversation must match tenant and provider'
        using errcode = '23514';
    end if;
  end if;

  if tg_table_name = 'meta_conversation_bindings' then
    if tg_op = 'UPDATE' and (
      new.external_user_id is distinct from old.external_user_id
      or new.created_at is distinct from old.created_at
    ) then
      raise exception 'Meta external user identity is immutable'
        using errcode = '23514';
    end if;
    return new;
  end if;

  if tg_table_name = 'meta_webhook_events' then
    if tg_op = 'UPDATE' and (
      new.event_key is distinct from old.event_key
      or new.event_type is distinct from old.event_type
      or new.direction is distinct from old.direction
      or new.occurred_at is distinct from old.occurred_at
      or new.external_user_id is distinct from old.external_user_id
      or new.external_message_id is distinct from old.external_message_id
      or new.external_object_id is distinct from old.external_object_id
      or new.payload is distinct from old.payload
      or new.created_at is distinct from old.created_at
    ) then
      raise exception 'Meta webhook evidence is append-only'
        using errcode = '23514';
    end if;

    if new.message_id is not null then
      select message.* into v_message
      from public.messages message
      where message.id = new.message_id;
      if not found
         or v_message.tenant_id is distinct from new.tenant_id
         or v_message.conversation_id is distinct from new.conversation_id then
        raise exception 'Meta event message must match its conversation tenant'
          using errcode = '23514';
      end if;
    end if;
    return new;
  end if;

  if tg_table_name = 'meta_outbound_send_attempts' then
    select binding.* into v_binding
    from public.meta_conversation_bindings binding
    where binding.id = new.binding_id;
    if not found
       or v_binding.tenant_id is distinct from new.tenant_id
       or v_binding.channel_id is distinct from new.channel_id
       or v_binding.conversation_id is distinct from new.conversation_id then
      raise exception 'Meta send attempt binding is inconsistent'
        using errcode = '23514';
    end if;
    if new.message_id is not null then
      select message.* into v_message
      from public.messages message
      where message.id = new.message_id;
      if not found
         or v_message.tenant_id is distinct from new.tenant_id
         or v_message.conversation_id is distinct from new.conversation_id then
        raise exception 'Meta send attempt message is inconsistent'
          using errcode = '23514';
      end if;
    end if;
    if tg_op = 'UPDATE' and (
      new.actor_id is distinct from old.actor_id
      or new.binding_id is distinct from old.binding_id
      or new.conversation_id is distinct from old.conversation_id
      or new.idempotency_key is distinct from old.idempotency_key
      or new.request_fingerprint is distinct from old.request_fingerprint
      or new.message_text is distinct from old.message_text
      or new.created_at is distinct from old.created_at
    ) then
      raise exception 'Meta send request identity is immutable'
        using errcode = '23514';
    end if;
    return new;
  end if;

  return new;
end;
$$;

